  methodologies: [{"slug":"meddpicc","name":"MEDDPICC","description":"Enterprise deal qualification framework","icon":"clipboard-check","count":15},{"slug":"spin","name":"SPIN Selling","description":"Situation, Problem, Implication, Need-payoff","icon":"message-circle-question","count":12},{"slug":"challenger","name":"Challenger Sale","description":"Teach, tailor, take control","icon":"swords","count":10},{"slug":"sandler","name":"Sandler","description":"Pain funnel and upfront contracts","icon":"target","count":10},{"slug":"value-selling","name":"Value Selling","description":"ROI and business case focused","icon":"dollar-sign","count":10},{"slug":"gap-selling","name":"Gap Selling","description":"Current state vs future state","icon":"git-compare","count":10}],
