const PROMPTS = [{"id":"ae-discovery-call","title":"Discovery Call Framework","category":"ae","tags":["discovery","call","qualification"],"difficulty":"intermediate","description":"Structure a discovery call that uncovers real pain","prompt":"Create a discovery call framework for this opportunity.\n\nContext:\n- Prospect: [NAME, TITLE at COMPANY]\n- Company size: [EMPLOYEES / REVENUE]\n- How they found us: [INBOUND / OUTBOUND / REFERRAL]\n- What they said they need: [THEIR STATED NEED]\n- My product: [WHAT YOU SELL]\n\nGenerate:\n1. Opening (build rapport, set agenda, get permission)\n2. Current state questions (how they do it today)\n3. Pain quantification questions (cost of the problem)\n4. Future state questions (what good looks like)\n5. Decision process questions (who, what, when)\n6. Next steps framework\n\nFor each question, include:\n- The question itself\n- Why you're asking it\n- Follow-up questions based on likely answers","group":"ae"},{"id":"ae-demo-script","title":"Demo Script Builder","category":"ae","tags":["demo","presentation","pitch"],"difficulty":"intermediate","description":"Build a demo script tailored to discovery findings","prompt":"Create a demo script based on what I learned in discovery.\n\nDiscovery findings:\n- Main pain point: [THEIR #1 PROBLEM]\n- Secondary pain: [THEIR #2 PROBLEM]\n- Current solution: [WHAT THEY USE TODAY]\n- Why they're looking: [TRIGGER EVENT]\n- Success metrics: [HOW THEY'LL MEASURE SUCCESS]\n- Key stakeholders: [WHO'S INVOLVED]\n- Timeline: [WHEN THEY NEED TO DECIDE]\n\nMy product: [YOUR PRODUCT]\n\nCreate a demo flow that:\n1. Recaps their situation (show you listened)\n2. Shows the 3 most relevant features (tied to their pain)\n3. Includes a \"wow moment\" that differentiates\n4. Handles likely objections preemptively\n5. Ends with clear next steps\n\nTime limit: 20 minutes of demo + 10 minutes Q&A","group":"ae"},{"id":"ae-proposal-email","title":"Proposal Delivery Email","category":"ae","tags":["proposal","email","closing"],"difficulty":"advanced","description":"Email to send with your proposal that drives action","prompt":"Write an email to send with my proposal.\n\nDeal context:\n- Prospect: [NAME, TITLE at COMPANY]\n- What we're proposing: [SOLUTION SUMMARY]\n- Price: [DEAL VALUE]\n- Their timeline: [WHEN THEY SAID THEY NEED TO DECIDE]\n- Champion: [WHO'S PUSHING FOR YOU]\n- Blocker: [WHO MIGHT SAY NO]\n- Competitor: [WHO ELSE THEY'RE EVALUATING]\n\nEmail should:\n1. Reference specific things they said they needed\n2. Summarize the proposal (they'll skim before opening)\n3. Highlight the ROI case\n4. Create urgency without being pushy\n5. Make next steps crystal clear\n6. Give them language to sell internally\n\nUnder 200 words. No attachments - embed key points in the email.","group":"ae"},{"id":"ae-negotiation-prep","title":"Negotiation Preparation","category":"ae","tags":["negotiation","pricing","closing"],"difficulty":"advanced","description":"Prepare for a pricing/terms negotiation","prompt":"Help me prepare for a negotiation on this deal.\n\nDeal context:\n- Prospect: [COMPANY NAME]\n- Our price: [YOUR ASKING PRICE]\n- Their budget: [WHAT THEY SAID / YOUR GUESS]\n- Deal size: [ACV]\n- What they've pushed back on: [PRICE / TERMS / TIMELINE]\n- Their alternatives: [COMPETITORS / STATUS QUO]\n- Our leverage: [WHY THEY NEED US]\n- Their leverage: [WHY WE NEED THEM]\n\nHelp me with:\n1. BATNA analysis (theirs and mine)\n2. Concessions I can offer (and what to get in return)\n3. Anchoring strategy\n4. \"If... then\" trade-offs\n5. Walk-away point\n6. Red lines I shouldn't cross\n\nAlso give me:\n- 3 responses to \"Can you do better on price?\"\n- How to handle \"Competitor X is cheaper\"\n- Language for multi-year discount trades","group":"ae"},{"id":"ae-champion-enablement","title":"Champion Enablement Email","category":"ae","tags":["champion","internal-selling","stakeholder"],"difficulty":"advanced","description":"Give your champion ammo to sell internally","prompt":"Create a champion enablement package for my internal sponsor.\n\nContext:\n- Champion: [NAME, TITLE]\n- Economic buyer: [NAME, TITLE]\n- Other stakeholders: [WHO ELSE NEEDS TO APPROVE]\n- Champion's motivation: [WHY THEY WANT THIS]\n- What they need to prove: [BUSINESS CASE REQUIREMENTS]\n- Objections they'll face: [LIKELY INTERNAL PUSHBACK]\n\nCreate:\n1. One-pager they can share with their boss\n2. Email they can forward to stakeholders\n3. Talk track for their internal meeting\n4. Responses to likely internal objections\n5. ROI calculation framework\n6. Competitive comparison talking points\n\nMake it easy for them to copy-paste and look good internally.","group":"ae"},{"id":"ae-mutual-action-plan","title":"Mutual Action Plan","category":"ae","tags":["map","closing","process"],"difficulty":"advanced","description":"Create a MAP to guide deal to close","prompt":"Create a Mutual Action Plan (MAP) for this deal.\n\nDeal context:\n- Prospect: [COMPANY NAME]\n- Target close date: [DATE]\n- Key stakeholders: [NAMES AND ROLES]\n- Deal value: [ACV]\n- Current stage: [STAGE]\n- Known requirements: [SECURITY / LEGAL / TECHNICAL / PROCUREMENT]\n\nBuild a reverse-engineered timeline that includes:\n1. All steps needed from both sides\n2. Who owns each step\n3. Dependencies between steps\n4. Buffer time for delays\n5. Go-live planning (not just contract signing)\n\nCategories to include:\n- Technical evaluation (POC, security review, integration)\n- Business validation (ROI, stakeholder buy-in)\n- Procurement (legal, finance, contract)\n- Implementation (timeline, resources, training)\n\nFormat as a shareable document they can edit with me.","group":"ae"},{"id":"ae-executive-briefing","title":"Executive Briefing Doc","category":"ae","tags":["executive","document","champion-enablement"],"difficulty":"advanced","description":"Create a doc for champion to share with executives","prompt":"Create an executive briefing document for this deal.\n\nContext:\n- Company: [PROSPECT COMPANY]\n- Executive reader: [C-LEVEL TITLE]\n- Champion: [WHO'S SPONSORING]\n- Initiative: [WHAT THEY'RE TRYING TO DO]\n- Our solution: [YOUR PRODUCT]\n- Investment: [DEAL SIZE]\n\nExecutive's likely questions:\n- Why now? (timing/urgency)\n- Why this? (vs alternatives)\n- What's the risk? (downside mitigation)\n- What's the return? (ROI timeline)\n- Who's done this? (references)\n\nCreate a 1-page brief that:\n1. Leads with their strategic priority (not your product)\n2. Frames the problem in financial terms\n3. Summarizes the recommendation\n4. Provides clear ROI projection\n5. Outlines next steps with timeline\n6. Addresses the \"why not\" objections\n\nWrite in executive voice—no jargon, bullets over paragraphs.","group":"ae"},{"id":"ae-competitive-positioning","title":"Competitive Battle Card","category":"ae","tags":["competitive","positioning","objections"],"difficulty":"intermediate","description":"Position against a specific competitor","prompt":"Help me position against [COMPETITOR] in this deal.\n\nSituation:\n- Prospect: [COMPANY]\n- Competitor: [COMPETITOR NAME]\n- How we know they're involved: [SOURCE]\n- Prospect's evaluation criteria: [WHAT MATTERS TO THEM]\n- Where competitor is strong: [THEIR ADVANTAGES]\n- Where we're strong: [OUR ADVANTAGES]\n\nCreate:\n1. Competitive landmines to plant early\n2. Differentiating questions to ask prospect\n3. Responses to \"why not [competitor]?\"\n4. Head-to-head feature comparison (honest)\n5. Customer proof points vs. competitor\n6. When to walk away (bad fit indicators)\n\nRules:\n- Never trash competitor directly\n- Focus on what's best for the customer\n- Acknowledge where competitor wins\n- Lead with differentiation, not FUD","group":"ae"},{"id":"ae-trial-to-paid","title":"Trial Conversion Playbook","category":"ae","tags":["trial","poc","conversion","closing"],"difficulty":"intermediate","description":"Convert a trial or POC to paid deal","prompt":"Create a trial-to-paid conversion plan.\n\nTrial context:\n- Company: [COMPANY NAME]\n- Trial length: [DAYS]\n- Days remaining: [DAYS LEFT]\n- Users active: [NUMBER]\n- Usage metrics: [KEY ACTIVITY DATA]\n- Success criteria: [WHAT THEY DEFINED AS SUCCESS]\n- Champion: [NAME, TITLE]\n- Blocker/skeptic: [IF ANY]\n\nBuild a conversion plan that includes:\n1. Usage milestones to hit each week\n2. Check-in cadence and talk tracks\n3. Success metrics to highlight\n4. Expansion signals to identify\n5. Objections to preempt\n6. Transition call structure\n7. Urgency creation (without being pushy)\n\nInclude:\n- Email templates for each phase\n- Questions to ask in check-ins\n- Red flags that trial is going poorly\n- Save plays for struggling trials","group":"ae"},{"id":"ae-deal-unstick","title":"Unstick a Stalled Deal","category":"ae","tags":["stalled","stuck","pipeline","deal-strategy"],"difficulty":"advanced","description":"Strategies to move a stalled opportunity forward","prompt":"Help me unstick this stalled deal.\n\nDeal context:\n- Company: [PROSPECT]\n- Deal value: [ACV]\n- Stage: [CURRENT STAGE]\n- Days in stage: [NUMBER]\n- Last meaningful contact: [DATE AND WHAT HAPPENED]\n- Stated next step that didn't happen: [WHAT WAS SUPPOSED TO HAPPEN]\n- Champion status: [ENGAGED / GONE DARK / LEFT COMPANY]\n- Competition: [KNOWN ALTERNATIVES]\n\nDiagnose the stall:\n1. Priority dropped (something else became urgent)\n2. Champion lost influence\n3. Evaluating competitor\n4. Budget disappeared\n5. Internal politics\n6. We didn't earn the next step\n\nFor each diagnosis, provide:\n- How to confirm this is the issue\n- Specific re-engagement strategy\n- Multi-channel outreach sequence\n- When to cut losses","group":"ae"},{"id":"ae-security-questionnaire","title":"Security Questionnaire Prep","category":"ae","tags":["security","questionnaire","enterprise","infosec"],"difficulty":"intermediate","description":"Prepare for security review process","prompt":"Help me navigate this security review process.\n\nContext:\n- Prospect: [COMPANY]\n- Their industry: [INDUSTRY - affects compliance needs]\n- Security contact: [NAME, TITLE]\n- Questionnaire type: [SIG / CAIQ / CUSTOM / VSAQ]\n- Questions I'm stuck on: [LIST SPECIFIC QUESTIONS]\n- Our certifications: [SOC2 / ISO27001 / GDPR / HIPAA / etc.]\n- Our security page: [URL IF EXISTS]\n\nHelp me with:\n1. Understanding what they're really asking\n2. Drafting responses that are accurate and reassuring\n3. Identifying gaps we need to address honestly\n4. Red flags that could slow us down\n5. How to position security as a differentiator\n6. Questions to ask their security team\n\nFormat responses as copy-paste ready with appropriate caveats.","group":"ae"},{"id":"ae-procurement-navigation","title":"Navigate Procurement","category":"ae","tags":["procurement","legal","contract","enterprise"],"difficulty":"advanced","description":"Get through procurement and legal review","prompt":"Help me navigate procurement on this deal.\n\nContext:\n- Company: [PROSPECT]\n- Deal size: [ACV]\n- Procurement contact: [NAME, TITLE]\n- Legal contact: [NAME, TITLE]\n- Contract issues raised: [SPECIFIC REDLINES]\n- Timeline pressure: [WHEN THEY NEED TO GO LIVE]\n- Our leverage: [WHY THEY NEED US]\n\nCommon blockers and how to handle:\n1. Indemnification clauses\n2. Liability caps\n3. Data processing terms\n4. SLA requirements\n5. Termination terms\n6. Auto-renewal concerns\n\nFor this specific deal:\n- What to push back on vs. concede\n- How to keep champion engaged during legal\n- Escalation strategy if stuck\n- Creative deal structures (if needed)\n- Language I can propose for each redline","group":"ae"},{"id":"ae-qbr-presentation","title":"QBR Presentation for Existing Customer","category":"ae","tags":["qbr","customer","expansion","upsell"],"difficulty":"intermediate","description":"Quarterly business review deck for expansion","prompt":"Create a QBR presentation for this customer.\n\nCustomer context:\n- Company: [CUSTOMER NAME]\n- Current ARR: [VALUE]\n- Contract renewal: [DATE]\n- Primary contact: [NAME, TITLE]\n- Executive sponsor: [NAME, TITLE]\n- Products they use: [CURRENT PRODUCTS]\n- Usage metrics: [KEY STATS]\n- Value delivered: [OUTCOMES ACHIEVED]\n\nExpansion opportunity:\n- Additional product: [WHAT YOU WANT TO UPSELL]\n- Additional users/seats: [IF APPLICABLE]\n- New department: [IF EXPANDING USE CASE]\n\nCreate a QBR deck that:\n1. Celebrates their wins (metrics + stories)\n2. Shows ROI vs. original business case\n3. Benchmarks vs. similar customers\n4. Identifies expansion opportunities naturally\n5. Previews product roadmap (relevant items)\n6. Aligns on next quarter goals\n\nInclude talking points and anticipated questions.","group":"ae"},{"id":"challenger-insight","title":"Challenger Commercial Insight","category":"challenger","tags":["challenger","insight","teaching"],"difficulty":"advanced","description":"Develop a commercial teaching insight","prompt":"Help me develop a Challenger-style commercial insight.\n\nContext:\n- My industry: [YOUR MARKET]\n- My product: [WHAT YOU SELL]\n- Target buyer: [WHO YOU SELL TO]\n- Common assumption: [WHAT THEY BELIEVE TODAY]\n\nA good commercial insight should:\n1. Challenge their current thinking\n2. Lead to your unique strength\n3. Be defensible with data\n4. Create urgency to act\n5. Resonate emotionally\n\nFramework:\n- \"Most [buyers] believe [common assumption]...\"\n- \"But our research shows [surprising insight]...\"\n- \"The implication is [business impact]...\"\n- \"The best companies are [doing something different]...\"\n- \"Which is exactly why [your solution matters]...\"\n\nGenerate a teaching pitch I can use to reframe conversations.","group":"challenger"},{"id":"construction-cold-email-1","title":"Construction Executive Cold Email","category":"construction","subcategory":"outreach","tags":["cold-email","construction","contractor"],"difficulty":"intermediate","description":"Cold email for general contractors and construction firms","prompt":"Write a cold email to a construction executive.\n\nContext:\n- Recipient: [NAME, TITLE]\n- Company type: [GC / SUBCONTRACTOR / DEVELOPER / OWNER]\n- Size: [ANNUAL REVENUE / PROJECT SIZE]\n- Signal: [NEW PROJECT / SAFETY INCIDENT / EFFICIENCY INITIATIVE]\n- My solution: [WHAT YOU SELL]\n- Project impact: [HOW YOU HELP]\n\nConstruction Email Rules:\n- Lead with project outcomes (time, cost, safety)\n- Reference specific project types they do\n- Be aware of bid/proposal cycles\n- Speak to safety (critical in construction)\n- Understand field vs. office dynamics\n- Mention integrations with their tools (Procore, etc.)\n\nConstruction buyers care about: safety, schedule, budget, quality, risk.","group":"construction"},{"id":"construction-discovery-1","title":"Construction Discovery Questions","category":"construction","subcategory":"discovery","tags":["discovery","construction","projects"],"difficulty":"intermediate","description":"Discovery for construction technology sales","prompt":"Generate discovery questions for a construction prospect.\n\nContext:\n- Prospect: [NAME, TITLE at COMPANY]\n- Construction type: [COMMERCIAL / RESIDENTIAL / INFRASTRUCTURE]\n- My product: [WHAT YOU SELL]\n- Known pain: [SAFETY / SCHEDULE / COST / QUALITY]\n\nConstruction discovery categories:\n1. Project portfolio and pipeline\n2. Current pain points (field vs. office)\n3. Technology stack (project management, BIM, safety)\n4. Safety program and requirements\n5. Subcontractor and labor management\n6. Decision process (project vs. corporate)\n7. Budget and project economics\n8. Compliance and reporting requirements\n\nConstruction is project-based - understand their pipeline.","group":"construction"},{"id":"construction-objection-1","title":"Handle \"Our Field Crews Won't Use It\"","category":"construction","subcategory":"objections","tags":["objection","adoption","field"],"difficulty":"advanced","description":"Navigate field adoption concerns","prompt":"Help me respond to: \"Our field crews won't use another app/system.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their company: [GC / SPECIALTY]\n- Field challenges: [WHAT THEY'VE TRIED BEFORE]\n- Our approach: [HOW WE'RE DIFFERENT]\n\nField adoption is the #1 challenge in construction tech. Help me:\n1. Validate the concern (tech fatigue is real)\n2. Ask about what has/hasn't worked before\n3. Explain our approach to field usability\n4. Reference similar companies with successful adoption\n5. Propose a pilot with a specific crew\n6. Discuss training and support approach\n\nNever dismiss field adoption concerns - address them directly.","group":"construction"},{"id":"construction-proposal-1","title":"Construction Technology Proposal","category":"construction","subcategory":"proposals","tags":["proposal","construction","technology"],"difficulty":"advanced","description":"Build a case for construction tech investment","prompt":"Write a proposal for a construction technology investment.\n\nContext:\n- Company: [CONTRACTOR NAME]\n- Company size: [ANNUAL REVENUE / EMPLOYEES]\n- Challenge: [WHAT THEY'RE SOLVING]\n- My solution: [WHAT YOU SELL]\n- Investment: [YOUR PRICE]\n- Expected outcomes: [METRICS]\n\nConstruction proposals need:\n1. Safety improvements (always first)\n2. Schedule impact (days saved)\n3. Cost savings (labor, rework, materials)\n4. Risk reduction\n5. Field adoption plan\n6. Integration with existing tools\n7. Training and support\n8. Reference projects/companies\n\nConstruction buyers are conservative - prove it works with references.","group":"construction"},{"id":"construction-follow-up-1","title":"Post-Project Follow-Up","category":"construction","subcategory":"follow-up","tags":["follow-up","project","relationship"],"difficulty":"beginner","description":"Follow up after a project completes","prompt":"Write a follow-up email after a customer's project completes.\n\nContext:\n- Company: [CONTRACTOR]\n- Contact: [NAME, TITLE]\n- Project completed: [PROJECT NAME/TYPE]\n- How we helped: [IF CUSTOMER] or [HOW WE COULD HAVE HELPED]\n- Their pipeline: [UPCOMING PROJECTS IF KNOWN]\n- My solution: [WHAT YOU SELL]\n\nPost-project follow-up should:\n1. Congratulate on project completion\n2. Reference results achieved (if customer)\n3. Capture lessons learned\n4. Discuss upcoming project pipeline\n5. Position for next project\n\nConstruction relationships are project-to-project. Stay connected between projects.","group":"construction"},{"id":"csm-qbr-prep","title":"QBR Preparation Framework","category":"csm","tags":["qbr","review","presentation"],"difficulty":"intermediate","description":"Prepare for a quarterly business review","prompt":"Help me prepare a QBR for a customer.\n\nCustomer context:\n- Company: [CUSTOMER NAME]\n- Contract value: [ARR]\n- Tenure: [HOW LONG A CUSTOMER]\n- Health score: [IF YOU TRACK]\n- Key stakeholders: [WHO WILL ATTEND]\n- Renewal date: [WHEN]\n- Expansion opportunity: [IF ANY]\n\nQBR needs to cover:\n1. Value delivered (metrics, outcomes, ROI)\n2. Product usage and adoption\n3. Support ticket trends\n4. Roadmap alignment (what's coming they'll care about)\n5. Success plan for next quarter\n6. Open items and risks\n7. Expansion discussion (if appropriate)\n\nFormat: Slide outline with talking points for each section.\nInclude questions to ask them (make it two-way).","group":"csm"},{"id":"csm-health-score","title":"Customer Health Score Design","category":"csm","tags":["health-score","churn","retention"],"difficulty":"advanced","description":"Design a customer health scoring model","prompt":"Help me design a customer health score model.\n\nContext:\n- Product type: [WHAT YOU SELL]\n- Customer base: [NUMBER OF CUSTOMERS]\n- Current churn rate: [%]\n- Data available: [USAGE DATA / SUPPORT / NPS / etc.]\n- Historical churn patterns: [WHAT YOU'VE NOTICED]\n\nHealth score components to consider:\n1. Product usage (login frequency, feature adoption, depth)\n2. Engagement (meetings, responses, executive sponsorship)\n3. Support (ticket volume, sentiment, escalations)\n4. Financial (payment history, growth/contraction)\n5. Survey data (NPS, CSAT)\n6. External signals (company health, news)\n\nOutput:\n- Weighted scoring model\n- Data sources needed\n- Score thresholds (healthy/at-risk/critical)\n- Playbooks per segment\n- Leading indicators vs. lagging","group":"csm"},{"id":"csm-churn-save","title":"Churn Save Playbook","category":"csm","tags":["churn","save","retention"],"difficulty":"advanced","description":"Save an at-risk customer from churning","prompt":"Help me save a customer who's at risk of churning.\n\nCustomer situation:\n- Company: [CUSTOMER NAME]\n- ARR: [VALUE]\n- Tenure: [HOW LONG]\n- Why they're at risk: [WHAT HAPPENED / WHAT THEY SAID]\n- Key contact: [NAME, TITLE]\n- Decision maker: [NAME, TITLE]\n- Renewal date: [WHEN]\n- Competitive threat: [IF ANY]\n\nChurn save playbook:\n1. Root cause analysis (is it fixable?)\n2. Executive sponsor engagement (do we need to escalate?)\n3. Quick wins (what can we do immediately?)\n4. Recovery plan (what does success look like?)\n5. Commercial options (discounts, terms, scope change)\n6. Exit interview plan (if we can't save)\n\nGenerate:\n- Talk track for the save conversation\n- Email to request exec meeting\n- 30-day recovery plan\n- Concessions we could offer (and what to get in return)","group":"csm"},{"id":"csm-expansion-email","title":"Expansion Opportunity Email","category":"csm","tags":["expansion","upsell","cross-sell"],"difficulty":"intermediate","description":"Email to introduce an upsell or cross-sell","prompt":"Write an email to introduce an expansion opportunity.\n\nContext:\n- Customer: [COMPANY NAME]\n- Contact: [NAME, TITLE]\n- Current product: [WHAT THEY HAVE]\n- Expansion opportunity: [WHAT YOU WANT TO SELL]\n- Why now: [TRIGGER / TIMING]\n- Value they've gotten: [RESULTS SO FAR]\n\nEmail should:\n1. Lead with their success (not your product)\n2. Connect to a business goal they have\n3. Introduce the expansion naturally\n4. Quantify the additional value\n5. Propose a specific next step\n6. Not feel salesy (you're their CSM, not a rep)\n\nKeep it conversational - this is a relationship, not a transaction.","group":"csm"},{"id":"csm-handoff-doc","title":"Customer Handoff Document","category":"csm","tags":["handoff","transition","documentation"],"difficulty":"beginner","description":"Document for handing off a customer to a new CSM","prompt":"Create a customer handoff document for a CSM transition.\n\nCustomer:\n- Company: [NAME]\n- ARR: [VALUE]\n- Industry: [VERTICAL]\n- Tenure: [HOW LONG]\n- Health: [GOOD / AT RISK / etc.]\n- Renewal date: [WHEN]\n\nDocument needs:\n1. Key contacts (names, roles, communication preferences)\n2. Business context (why they bought, what they're trying to achieve)\n3. Product usage (what they use, what they don't)\n4. Relationship history (key moments, good and bad)\n5. Open items (pending issues, promised deliverables)\n6. Growth opportunities (expansion, advocates)\n7. Watch-outs (sensitivities, past issues, politics)\n\nInclude specific advice for the new CSM on how to build relationship.","group":"csm"},{"id":"wf-discovery-framework","title":"Discovery Call Framework","category":"discovery","tags":["discovery","questions","qualification"],"difficulty":"intermediate","description":"Complete framework for running discovery calls","prompt":"Create a discovery call framework for my sales team.\n\nContext:\n- Product: [WHAT YOU SELL]\n- ICP: [IDEAL CUSTOMER]\n- Average deal size: [ACV]\n- Sales cycle: [LENGTH]\n- Qualification criteria: [BANT / MEDDPICC / etc.]\n\nFramework needs:\n1. Opening (rapport, agenda, permission)\n2. Situation questions (current state)\n3. Problem questions (pain exploration)\n4. Impact questions (quantification)\n5. Future state questions (desired outcome)\n6. Process questions (decision making)\n7. Closing (summary, next steps)\n\nInclude:\n- Specific questions for each section\n- Follow-up prompts\n- Red flags to listen for\n- Note-taking template","group":"discovery"},{"id":"wf-pain-quantification","title":"Pain Quantification Questions","category":"discovery","tags":["pain","quantification","roi"],"difficulty":"advanced","description":"Questions to quantify the cost of the problem","prompt":"Help me quantify the cost of my prospect's problem.\n\nContext:\n- Prospect: [COMPANY and SITUATION]\n- Problem they have: [THE PAIN]\n- My solution: [WHAT YOU SELL]\n- Likely impact areas: [TIME / MONEY / RISK]\n\nGenerate questions that uncover:\n1. Time wasted (hours per week, people involved)\n2. Money lost (direct costs, opportunity cost)\n3. Risk exposure (what could go wrong)\n4. Downstream impact (effects on other teams/metrics)\n5. Strategic cost (competitive disadvantage)\n\nFor each area:\n- Opening question\n- Follow-up to quantify\n- How to calculate the number together\n- Benchmark data to reference","group":"discovery"},{"id":"wf-stakeholder-mapping","title":"Stakeholder Mapping Session","category":"discovery","tags":["stakeholders","buying-committee","mapping"],"difficulty":"advanced","description":"Map the buying committee in discovery","prompt":"Help me map the stakeholders in this opportunity.\n\nContext:\n- Company: [PROSPECT]\n- Deal size: [VALUE]\n- Current contact: [NAME, TITLE]\n- Departments affected: [WHO USES YOUR PRODUCT]\n\nGenerate questions to identify:\n1. Economic Buyer (who has budget authority)\n2. Technical Buyer (who evaluates technically)\n3. User Buyer (who will use it daily)\n4. Champion (who wants you to win)\n5. Coach (who will give you inside info)\n6. Blocker (who might say no)\n\nFor each stakeholder type:\n- Discovery questions to identify them\n- How to get introduced to them\n- What they care about\n- How to win them over\n- Warning signs they're against you","group":"discovery"},{"id":"wf-current-state-deep-dive","title":"Current State Assessment","category":"discovery","tags":["current-state","assessment","questions"],"difficulty":"intermediate","description":"Deep dive into their current situation","prompt":"Generate current state assessment questions.\n\nContext:\n- Prospect's likely current solution: [WHAT THEY USE TODAY]\n- My product: [WHAT I SELL]\n- Problem area: [WHAT THEY'RE TRYING TO SOLVE]\n\nQuestions to understand:\n1. Process (how do they do this today, step by step)\n2. Tools (what software/systems do they use)\n3. People (who's involved, how many)\n4. Time (how long does it take)\n5. Satisfaction (what works, what doesn't)\n6. History (have they tried to fix this before)\n7. Workarounds (what do they do to cope)\n8. Metrics (how do they measure success today)\n\nFor each question:\n- The question to ask\n- Follow-up probes\n- What their answer reveals\n- How to tie it back to your solution","group":"discovery"},{"id":"wf-future-state-visioning","title":"Future State Visioning","category":"discovery","tags":["future-state","vision","questions"],"difficulty":"intermediate","description":"Help prospects envision their ideal future state","prompt":"Create future state visioning questions.\n\nContext:\n- Prospect: [COMPANY]\n- Problem area: [WHAT THEY'RE SOLVING]\n- My solution: [WHAT I SELL]\n\nGenerate questions that help them visualize:\n1. What does success look like in 12 months?\n2. How would they know the problem is solved?\n3. What would their team be able to do that they can't today?\n4. What metrics would be different?\n5. How would their day/week change?\n6. What would stakeholders say about the improvement?\n7. What would they do with time/resources freed up?\n\nFor each question:\n- How to phrase it naturally\n- Follow-up to make it tangible\n- How to connect their vision to your product\n- Warning signs their vision doesn't fit your solution","group":"discovery"},{"id":"wf-competitive-discovery","title":"Competitive Intelligence Discovery","category":"discovery","tags":["competitive","discovery","intelligence"],"difficulty":"advanced","description":"Uncover competitive landscape in discovery","prompt":"Generate questions to understand the competitive landscape.\n\nContext:\n- My product: [WHAT I SELL]\n- Main competitors: [WHO WE COMPETE WITH]\n- Prospect: [COMPANY]\n\nQuestions to uncover:\n1. Are they evaluating alternatives? (without being paranoid)\n2. What solutions have they looked at before?\n3. Why didn't previous solutions work?\n4. What criteria are they using to evaluate?\n5. Who's involved in the evaluation?\n6. What's their timeline?\n7. What would make them choose us vs. others?\n\nFor each question:\n- Natural way to ask it\n- How to handle \"yes we're looking at X\"\n- Red flags that we're losing\n- How to differentiate without trash-talking","group":"discovery"},{"id":"wf-decision-process-mapping","title":"Decision Process Discovery","category":"discovery","tags":["decision-process","buying-process","timeline"],"difficulty":"intermediate","description":"Map their buying process and timeline","prompt":"Generate questions to map their decision process.\n\nContext:\n- Deal size: [VALUE]\n- Company size: [EMPLOYEES]\n- Typical sales cycle: [YOUR AVERAGE]\n\nQuestions to understand:\n1. How have they bought similar solutions before?\n2. Who needs to be involved in this decision?\n3. What's their evaluation process?\n4. What approvals are needed?\n5. Is there a specific timeline or deadline?\n6. What could slow this down?\n7. What happens if they don't decide?\n8. What's the procurement/legal process?\n\nFor each stage of their process:\n- Questions to ask\n- Who you should be talking to\n- Documents they might need\n- Typical timeline\n- How to accelerate without being pushy","group":"discovery"},{"id":"ecom-cold-email-1","title":"E-commerce Executive Cold Email","category":"ecommerce","subcategory":"outreach","tags":["cold-email","ecommerce","dtc"],"difficulty":"beginner","description":"Cold email for e-commerce and DTC brands","prompt":"Write a cold email to an e-commerce executive.\n\nContext:\n- Recipient: [NAME, TITLE at BRAND]\n- Brand type: [DTC / MARKETPLACE SELLER / OMNICHANNEL]\n- Approximate revenue: [SIZE]\n- Platform: [SHOPIFY / MAGENTO / SALESFORCE / CUSTOM]\n- Signal: [NEW LAUNCH / SCALING / CONVERSION ISSUE]\n- My solution: [WHAT YOU SELL]\n- Metric impact: [CVR / AOV / LTV / ROAS]\n\nE-commerce Email Rules:\n- Lead with specific metrics (conversion rate, AOV, ROAS)\n- Reference their actual site/products if possible\n- Be fast and transactional (they're used to quick decisions)\n- Show you understand DTC/e-commerce economics\n- Offer quick wins, not long implementations\n- Mention competitors using you (they're competitive)\n\nE-commerce buyers move fast. Match their pace.","group":"ecommerce"},{"id":"ecom-discovery-1","title":"E-commerce Discovery Questions","category":"ecommerce","subcategory":"discovery","tags":["discovery","conversion","metrics"],"difficulty":"beginner","description":"Discovery for e-commerce optimization","prompt":"Generate discovery questions for an e-commerce prospect.\n\nContext:\n- Prospect: [NAME, TITLE at BRAND]\n- Brand category: [APPAREL / BEAUTY / FOOD / etc.]\n- Channel mix: [DTC / AMAZON / RETAIL]\n- My product: [WHAT YOU SELL]\n- Likely pain: [CVR / ACQUISITION COST / RETENTION]\n\nE-commerce discovery categories:\n1. Current metrics (conversion rate, AOV, LTV, CAC)\n2. Traffic sources and ROAS by channel\n3. Tech stack (platform, apps, integrations)\n4. Team structure (who owns what)\n5. Seasonal patterns and upcoming peaks\n6. Current experiments/tests running\n7. Decision process (usually faster than enterprise)\n\nE-commerce teams are metrics-obsessed. Come with benchmark data.","group":"ecommerce"},{"id":"ecom-objection-1","title":"Handle \"We Just Launched a New Site\"","category":"ecommerce","subcategory":"objections","tags":["objection","timing","replatform"],"difficulty":"intermediate","description":"Navigate timing after a replatform","prompt":"Help me respond to: \"We just launched a new site / replatformed. We're not adding anything else right now.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their platform: [SHOPIFY / MAGENTO / etc.]\n- When they launched: [HOW RECENTLY]\n- Integration complexity: [HOW EASY WE ARE TO ADD]\n\nPost-replatform is actually a great time. Help me:\n1. Validate their caution (replatforms are exhausting)\n2. Position as enhancing their new investment\n3. Explain lightweight integration (if true)\n4. Reference other post-replatform implementations\n5. Propose a small pilot that doesn't require IT\n6. Plant seed for 90 days from now if they're not ready\n\nTiming objections in e-commerce are often soft - they move fast when they see value.","group":"ecommerce"},{"id":"ecom-proposal-1","title":"E-commerce ROI Proposal","category":"ecommerce","subcategory":"proposals","tags":["proposal","roi","conversion"],"difficulty":"intermediate","description":"Quick ROI case for e-commerce","prompt":"Write a quick ROI proposal for an e-commerce brand.\n\nContext:\n- Brand: [NAME]\n- Monthly revenue: [APPROXIMATE]\n- Current conversion rate: [CVR]\n- Current AOV: [AVERAGE ORDER VALUE]\n- My solution: [WHAT YOU SELL]\n- Expected impact: [% IMPROVEMENT]\n- Price: [YOUR COST]\n\nE-commerce proposals need:\n1. Simple math: Current revenue × expected lift = incremental revenue\n2. Payback period (they think in months, not years)\n3. Case study with similar brand\n4. Implementation timeline (they want fast)\n5. A/B test proposal to prove it\n6. Easy cancellation if it doesn't work (reduces risk)\n\nKeep it to one page. E-commerce teams don't read long proposals.","group":"ecommerce"},{"id":"ecom-follow-up-1","title":"Post-Peak Season Follow-Up","category":"ecommerce","subcategory":"follow-up","tags":["follow-up","seasonal","bfcm"],"difficulty":"beginner","description":"Re-engage after Black Friday / holiday","prompt":"Write a follow-up email after peak season ends.\n\nContext:\n- Brand: [NAME]\n- Contact: [NAME, TITLE]\n- Their peak results: [IF KNOWN - BFCM performance]\n- Our last conversation: [WHAT YOU DISCUSSED]\n- My solution: [WHAT YOU SELL]\n\nPost-peak follow-up should:\n1. Acknowledge the peak season push (they're exhausted)\n2. Reference their results if public (congrats or sympathy)\n3. Connect to what they could improve for next year\n4. Remind them of your previous conversation\n5. Propose a quick call now that things are calmer\n6. Reference timeline to implement before next peak\n\nJanuary-February is planning season. Help them think about next year.","group":"ecommerce"},{"id":"ecom-retention-pitch","title":"Customer Retention/LTV Positioning","category":"ecommerce","subcategory":"proposals","tags":["retention","ltv","loyalty","repeat-purchase"],"difficulty":"intermediate","description":"Position around customer lifetime value","prompt":"Create retention/LTV-focused positioning for e-commerce.\n\nContext:\n- Brand: [NAME]\n- Category: [PRODUCT CATEGORY]\n- Current repeat rate: [% OF CUSTOMERS WHO REPEAT]\n- Current LTV: [IF KNOWN]\n- Acquisition cost: [CAC]\n- My solution: [WHAT YOU SELL]\n- LTV impact: [HOW YOU IMPROVE RETENTION]\n\nBuild an LTV business case:\n1. Current LTV calculation\n2. Current CAC to LTV ratio\n3. Industry benchmarks for their category\n4. Improvement potential with your solution\n5. Revenue impact of LTV improvement\n6. ROI projection\n\nAddress:\n- Why retention matters more than acquisition\n- Quick wins to show early value\n- Long-term program evolution\n- Integration with their existing stack","group":"ecommerce"},{"id":"ecom-agency-partnership","title":"E-commerce Agency Partnership Pitch","category":"ecommerce","subcategory":"outreach","tags":["agency","partnership","referral"],"difficulty":"intermediate","description":"Pitch to e-commerce agencies for partnership","prompt":"Create a partnership pitch for an e-commerce agency.\n\nContext:\n- Agency: [NAME]\n- Agency specialty: [SHOPIFY / CRO / PAID MEDIA / EMAIL / FULL SERVICE]\n- Their typical clients: [SIZE AND TYPE]\n- My solution: [WHAT YOU SELL]\n- Partnership model: [REFERRAL / RESELLER / IMPLEMENTATION PARTNER]\n\nAgency partnership pitch:\n1. How we help their clients succeed\n2. Commission/referral structure\n3. How we make them look good\n4. Case study of agency + us working together\n5. Technical support we provide\n6. Co-marketing opportunities\n7. Deal registration and protection\n\nAddress agency concerns:\n- Will this complicate our delivery?\n- How does this affect our margins?\n- Is this easy to position to clients?\n- What's the support model?","group":"ecommerce"},{"id":"ecom-platform-integration","title":"Platform Integration Pitch","category":"ecommerce","subcategory":"proposals","tags":["integration","shopify","platform"],"difficulty":"beginner","description":"Position your integration with Shopify/BigCommerce/etc.","prompt":"Create integration-focused pitch for e-commerce platform.\n\nContext:\n- Prospect platform: [SHOPIFY / BIGCOMMERCE / MAGENTO / WOOCOMMERCE]\n- Our integration: [APP STORE / NATIVE / API]\n- Integration complexity: [ONE-CLICK / DEVELOPER NEEDED]\n- My solution: [WHAT YOU SELL]\n- Integration benefits: [WHAT'S EASY/AUTOMATIC]\n\nPosition the integration:\n1. Installation simplicity (how fast to get started)\n2. Data sync capabilities (what flows automatically)\n3. No developer required (if true)\n4. App store reviews/ratings (if applicable)\n5. Other brands on their platform using us\n6. Support for their specific platform features\n\nInclude:\n- Step-by-step setup overview\n- Time to value (how fast they see results)\n- What data we access and why\n- Security and privacy compliance","group":"ecommerce"},{"id":"ecom-amazon-seller-pitch","title":"Amazon Seller Outreach","category":"ecommerce","subcategory":"outreach","tags":["amazon","marketplace","seller"],"difficulty":"intermediate","description":"Cold outreach to Amazon marketplace sellers","prompt":"Create outreach for Amazon sellers/brands.\n\nContext:\n- Seller: [BRAND/SELLER NAME]\n- Seller type: [1P / 3P / HYBRID]\n- Category: [PRODUCT CATEGORY]\n- Approximate revenue: [SIZE]\n- Signal: [NEW PRODUCT / RANKING CHANGE / REVIEW ISSUE]\n- My solution: [WHAT YOU SELL]\n- Amazon-specific value: [HOW YOU HELP ON AMAZON]\n\nAmazon seller priorities:\n- Buy box ownership\n- Review management and ratings\n- Advertising efficiency (ACOS, TACOS)\n- Inventory management\n- Competitor monitoring\n- Account health and compliance\n\nEmail should:\n1. Reference something specific about their Amazon presence\n2. Speak to Amazon-specific metrics\n3. Understand their seller central pain points\n4. Position quick wins (they're scrappy)\n5. Acknowledge if they have DTC too (multichannel)","group":"ecommerce"},{"id":"edu-cold-email-1","title":"K-12 Administrator Cold Email","category":"education","subcategory":"outreach","tags":["cold-email","k12","edtech"],"difficulty":"intermediate","description":"Cold email for reaching school district administrators","prompt":"Write a cold email to a K-12 administrator.\n\nContext:\n- Recipient: [NAME, TITLE - Superintendent, Curriculum Director, CTO, etc.]\n- District: [DISTRICT NAME]\n- Size: [NUMBER OF STUDENTS / SCHOOLS]\n- Signal: [GRANT / INITIATIVE / ADOPTION CYCLE]\n- My solution: [WHAT YOU SELL]\n- Student outcome impact: [HOW YOU HELP STUDENTS]\n\nEducation Email Rules:\n- Lead with student outcomes, not features\n- Reference research/evidence base if available\n- Understand the buying cycle (often annual)\n- Be aware of budget cycles and funding sources\n- Respect their mission-driven culture\n- Never be pushy (educators are sensitive to sales tactics)\n\nEducators care about: student success, teacher support, equity, evidence-based practices.","group":"education"},{"id":"edu-discovery-1","title":"Education Discovery Questions","category":"education","subcategory":"discovery","tags":["discovery","k12","higher-ed"],"difficulty":"intermediate","description":"Discovery for K-12 and higher ed sales","prompt":"Generate discovery questions for an education prospect.\n\nContext:\n- Prospect: [NAME, TITLE at INSTITUTION]\n- Institution type: [K-12 / HIGHER ED / DISTRICT / STATE]\n- My product: [WHAT YOU SELL]\n- Known initiative: [WHAT THEY'RE WORKING ON]\n\nEducation discovery categories:\n1. Student/learning outcomes (what they measure, goals)\n2. Current solutions (what they use today)\n3. Teacher/staff experience (adoption, workload)\n4. Budget and funding (grants, operating, capital)\n5. Decision process (committees, board approval, procurement)\n6. Implementation timeline (school year considerations)\n7. Equity and access requirements\n8. Integration needs (SIS, LMS, rostering)\n\nEducation buying cycles align to school years. Understand their calendar.","group":"education"},{"id":"edu-objection-1","title":"Handle \"We Don't Have Budget\"","category":"education","subcategory":"objections","tags":["objection","budget","funding"],"difficulty":"advanced","description":"Navigate budget constraints in education","prompt":"Help me respond to: \"We don't have budget for this.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their institution: [TYPE AND SIZE]\n- Price: [YOUR COST]\n- Funding opportunities: [GRANTS, ESSER, TITLE I, etc.]\n\nBudget is real in education, but there are often creative paths. Help me:\n1. Understand the specific constraint (none at all vs. not budgeted)\n2. Ask about grant funding possibilities\n3. Explore alternative budget lines (PD, curriculum, technology)\n4. Discuss pilot options to prove value first\n5. Align to their budget cycle for future\n6. Connect them with similar districts who found funding\n\nNever pressure. Education budgets are genuinely constrained.","group":"education"},{"id":"edu-proposal-1","title":"District RFP Response Framework","category":"education","subcategory":"proposals","tags":["proposal","rfp","district"],"difficulty":"advanced","description":"Framework for responding to education RFPs","prompt":"Help me respond to an education RFP/RFQ.\n\nContext:\n- District/Institution: [NAME]\n- RFP for: [WHAT THEY'RE BUYING]\n- Key requirements: [MUST-HAVES FROM RFP]\n- Evaluation criteria: [HOW THEY'LL SCORE]\n- My solution: [WHAT YOU SELL]\n- Competitors likely responding: [WHO ELSE]\n\nEducation RFP responses need:\n1. Complete compliance matrix (hit every requirement)\n2. Student outcome focus (not features)\n3. Implementation plan (aligned to school calendar)\n4. Professional development included\n5. References from similar districts\n6. Pricing in their required format\n7. Evidence base / research citations\n8. Equity and accessibility statements\n\nEducation RFPs are often checkbox-driven. Don't miss any requirements.","group":"education"},{"id":"edu-follow-up-1","title":"End-of-Year Follow-Up","category":"education","subcategory":"follow-up","tags":["follow-up","planning","budget"],"difficulty":"beginner","description":"Re-engage before summer planning season","prompt":"Write a follow-up email for end-of-year planning season.\n\nContext:\n- Institution: [DISTRICT / SCHOOL / UNIVERSITY]\n- Contact: [NAME, TITLE]\n- Our history: [PREVIOUS CONVERSATIONS]\n- My solution: [WHAT YOU SELL]\n- Next year timing: [WHEN THEY'D IMPLEMENT]\n\nEnd-of-year follow-up should:\n1. Acknowledge end-of-year busyness\n2. Plant seed for summer/fall planning\n3. Reference any pilot results or interest\n4. Offer planning conversation for next year\n5. Be respectful of their timeline\n\nSpring is when next year's budgets form. Be present but patient.","group":"education"},{"id":"edu-grant-positioning","title":"Grant Funding Positioning","category":"education","subcategory":"proposals","tags":["grant","funding","esser","title"],"difficulty":"advanced","description":"Position product for grant-funded purchases","prompt":"Position my product for grant-funded purchase.\n\nContext:\n- District: [DISTRICT NAME]\n- Grant type: [ESSER / TITLE I / STATE / FOUNDATION]\n- Grant deadline: [WHEN FUNDS EXPIRE]\n- My product: [WHAT YOU SELL]\n- Educational outcome: [WHAT IT ACHIEVES]\n- Allowable use alignment: [HOW IT FITS GRANT REQUIREMENTS]\n\nCreate positioning that:\n1. Maps to grant allowable uses\n2. Connects to academic outcomes\n3. Includes required data/assessment\n4. Addresses sustainability (after grant ends)\n5. Provides budget justification language\n6. References similar grant-funded implementations\n\nInclude:\n- Language they can use in grant applications\n- Evidence/research citations\n- Budget line item suggestions\n- Compliance checkboxes to address","group":"education"},{"id":"edu-committee-presentation","title":"School Board / Committee Presentation","category":"education","subcategory":"proposals","tags":["board","committee","presentation"],"difficulty":"advanced","description":"Present to school board or adoption committee","prompt":"Create a school board presentation for my product.\n\nContext:\n- District: [DISTRICT NAME]\n- Board/Committee: [SCHOOL BOARD / ADOPTION COMMITTEE / TECH COMMITTEE]\n- Champion: [WHO'S PRESENTING WITH/FOR YOU]\n- Investment: [TOTAL COST]\n- Students impacted: [NUMBER]\n- Key concern: [WHAT THEY CARE MOST ABOUT]\n\nBoard presentation must address:\n1. Educational need (data-driven)\n2. Alignment to district goals\n3. Evidence of effectiveness\n4. Total cost and funding source\n5. Implementation plan\n6. Professional development included\n7. Success metrics and accountability\n8. Privacy and security\n9. Equity considerations\n10. Community impact\n\nFormat for:\n- 10-minute presentation\n- Board packet document\n- Parent-friendly FAQ","group":"education"},{"id":"edu-pilot-results","title":"Pilot Results Summary","category":"education","subcategory":"follow-up","tags":["pilot","results","expansion"],"difficulty":"intermediate","description":"Summarize pilot results for expansion decision","prompt":"Summarize pilot results for expansion recommendation.\n\nPilot details:\n- District: [DISTRICT]\n- Schools in pilot: [NUMBER/NAMES]\n- Duration: [WEEKS/MONTHS]\n- Students reached: [NUMBER]\n- Teachers involved: [NUMBER]\n- Success metrics tracked: [WHAT WAS MEASURED]\n- Results: [DATA/OUTCOMES]\n- Feedback: [QUALITATIVE FEEDBACK]\n\nCreate summary that:\n1. Shows measurable outcomes\n2. Includes teacher/student quotes\n3. Compares to baseline or control\n4. Addresses challenges honestly\n5. Projects district-wide impact\n6. Recommends expansion path\n7. Provides implementation timeline\n8. Calculates cost per student\n\nFormat for:\n- Superintendent summary (1 page)\n- Board presentation (3 slides)\n- Full report (detailed)","group":"education"},{"id":"edu-teacher-champion","title":"Building Teacher Champions","category":"education","subcategory":"strategy","tags":["teacher","champion","adoption"],"difficulty":"intermediate","description":"Cultivate teacher advocates for edtech adoption","prompt":"Strategy to build teacher champions for my edtech product.\n\nContext:\n- Product: [WHAT YOU SELL]\n- Target grades/subjects: [GRADE LEVELS / SUBJECTS]\n- Current teacher users: [IF ANY]\n- District: [DISTRICT NAME]\n- Goal: [PILOT / ADOPTION / EXPANSION]\n\nBuild champion strategy:\n1. Identify ideal teacher profile\n2. Initial outreach approach\n3. Value proposition for teachers\n4. Support to make them successful\n5. Recognition and visibility\n6. How they influence administration\n7. Peer-to-peer spreading strategy\n\nTeacher motivations:\n- Student outcomes\n- Time savings\n- Professional growth\n- Recognition from peers/admin\n- Making their job easier\n\nProvide outreach templates and talking points.","group":"education"},{"id":"edu-renewal-pitch","title":"District Renewal Pitch","category":"education","subcategory":"proposals","tags":["renewal","expansion","district"],"difficulty":"intermediate","description":"Pitch for contract renewal with expanded scope","prompt":"Create a renewal pitch for this district.\n\nCurrent contract:\n- District: [DISTRICT NAME]\n- Current products: [WHAT THEY HAVE]\n- Contract value: [ANNUAL AMOUNT]\n- Renewal date: [WHEN]\n- Usage level: [HIGH/MEDIUM/LOW]\n- Results achieved: [OUTCOMES DATA]\n\nRenewal pitch should:\n1. Celebrate their success (with data)\n2. Show ROI vs. original expectations\n3. Present expansion opportunities\n4. Offer multi-year incentives\n5. Address any concerns or gaps\n6. Lock in favorable pricing\n7. Align to upcoming initiatives\n\nExpansion angles:\n- Additional schools\n- Additional grade levels\n- Additional products/modules\n- Professional development\n- Support tier upgrade","group":"education"},{"id":"energy-cold-email-1","title":"Utility Executive Cold Email","category":"energy","subcategory":"outreach","tags":["cold-email","utility","energy"],"difficulty":"intermediate","description":"Cold email for energy and utility decision makers","prompt":"Write a cold email to an energy or utility executive.\n\nContext:\n- Recipient: [NAME, TITLE]\n- Utility type: [ELECTRIC / GAS / WATER / MULTI-UTILITY]\n- Size: [CUSTOMERS SERVED / TERRITORY]\n- Signal: [REGULATORY CHANGE / INFRASTRUCTURE / SUSTAINABILITY GOAL]\n- My solution: [WHAT YOU SELL]\n- Regulatory alignment: [HOW YOU HELP WITH COMPLIANCE]\n\nEnergy/Utility Email Rules:\n- Understand their regulatory environment (PUC, FERC, state mandates)\n- Reference sustainability/decarbonization goals\n- Speak to grid reliability, safety, customer experience\n- Be aware of rate case cycles\n- Long sales cycles are normal (12-24+ months)\n- Reference similar utilities or regulatory requirements\n\nUtility buyers care about: reliability, safety, compliance, customer satisfaction, rates.","group":"energy"},{"id":"energy-discovery-1","title":"Utility Discovery Questions","category":"energy","subcategory":"discovery","tags":["discovery","utility","regulated"],"difficulty":"intermediate","description":"Discovery for utility and energy sales","prompt":"Generate discovery questions for a utility prospect.\n\nContext:\n- Prospect: [NAME, TITLE at UTILITY]\n- Utility type: [ELECTRIC / GAS / WATER]\n- My product: [WHAT YOU SELL]\n- Known initiative: [WHAT THEY'RE WORKING ON]\n\nUtility discovery categories:\n1. Regulatory environment (PUC requirements, rate cases, mandates)\n2. Current systems and infrastructure age\n3. Capital vs. operating budget dynamics\n4. Sustainability and decarbonization goals\n5. Customer experience initiatives\n6. Workforce challenges (aging workforce, safety)\n7. Decision process (extremely long and complex)\n8. Rate case timing (critical for budgeting)\n\nUtilities are heavily regulated - understand the regulatory drivers first.","group":"energy"},{"id":"energy-objection-1","title":"Handle \"It's Not in the Rate Case\"","category":"energy","subcategory":"objections","tags":["objection","rate-case","budget"],"difficulty":"advanced","description":"Navigate rate case budget constraints","prompt":"Help me respond to: \"This isn't included in our current rate case / capital plan.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their utility: [TYPE AND SIZE]\n- Their rate case cycle: [IF KNOWN]\n- Budget category: [CAPEX vs OPEX implications]\n\nThis is a real constraint in utilities. Help me:\n1. Understand their rate case timeline\n2. Ask about alternative budget categories (O&M vs. capital)\n3. Explore pilot or proof-of-concept scope\n4. Position for next rate case inclusion\n5. Identify regulatory mandates that could justify faster action\n6. Plant seeds for the next planning cycle\n\nRate cases are real constraints - don't fight them, plan around them.","group":"energy"},{"id":"energy-proposal-1","title":"Utility Business Case","category":"energy","subcategory":"proposals","tags":["proposal","utility","regulated"],"difficulty":"advanced","description":"Build a business case for utility procurement","prompt":"Write a business case for a utility investment.\n\nContext:\n- Utility: [NAME]\n- Initiative: [WHAT THEY'RE TRYING TO ACCOMPLISH]\n- My solution: [WHAT YOU SELL]\n- Regulatory drivers: [MANDATES, RATE CASE REQUIREMENTS]\n- Investment: [YOUR PRICE]\n- Expected outcomes: [METRICS]\n\nUtility business cases need:\n1. Regulatory alignment (how this supports compliance)\n2. Customer benefit (rate impact, service quality)\n3. Reliability/safety improvements\n4. Operating cost savings\n5. Capital efficiency\n6. Implementation risk mitigation\n7. Reference utilities\n8. Alignment with IRP (Integrated Resource Plan) if relevant\n\nFormat for regulatory review - utilities often need to justify to PUC.","group":"energy"},{"id":"energy-follow-up-1","title":"Post-Rate-Case Follow-Up","category":"energy","subcategory":"follow-up","tags":["follow-up","rate-case","budget"],"difficulty":"intermediate","description":"Re-engage after rate case decision","prompt":"Write a follow-up email after a utility's rate case decision.\n\nContext:\n- Utility: [NAME]\n- Contact: [NAME, TITLE]\n- Rate case outcome: [APPROVED / MODIFIED / DENIED - if known]\n- Our previous discussion: [CONTEXT]\n- My solution: [WHAT YOU SELL]\n- Next planning cycle: [WHEN]\n\nPost-rate-case follow-up should:\n1. Acknowledge the rate case process (it's exhausting)\n2. Reference the outcome appropriately\n3. Connect to initiatives that were approved\n4. Position for newly funded programs\n5. Plant seeds for next rate case if needed\n\nRate case outcomes create new opportunities - be ready.","group":"energy"},{"id":"energy-sustainability-pitch","title":"Sustainability/Decarbonization Pitch","category":"energy","subcategory":"proposals","tags":["sustainability","decarbonization","clean-energy"],"difficulty":"advanced","description":"Position for utility sustainability initiatives","prompt":"Position my solution for utility sustainability goals.\n\nContext:\n- Utility: [NAME]\n- Sustainability target: [NET ZERO BY YEAR / RENEWABLE % / ETC]\n- Current progress: [WHERE THEY ARE]\n- My solution: [WHAT YOU SELL]\n- Sustainability contribution: [HOW WE HELP]\n\nAddress utility sustainability priorities:\n1. Decarbonization pathway\n2. Renewable integration\n3. Grid modernization\n4. Electrification (EVs, heating)\n5. Energy efficiency programs\n6. Customer-side resources (DERs)\n7. Environmental justice\n8. Reporting and compliance\n\nPosition around:\n- Regulatory compliance (state mandates)\n- Cost of achieving targets\n- Operational feasibility\n- Customer program effectiveness\n- Measurement and verification\n\nInclude ESG and investor perspective if applicable.","group":"energy"},{"id":"energy-smart-grid-discovery","title":"Smart Grid / AMI Discovery","category":"energy","subcategory":"discovery","tags":["smart-grid","ami","grid-modernization"],"difficulty":"advanced","description":"Discovery for grid modernization initiatives","prompt":"Discovery questions for smart grid/AMI initiative.\n\nContext:\n- Utility: [NAME]\n- Grid initiative: [AMI / DERMS / ADMS / GRID SENSORS / OTHER]\n- Current state: [WHERE THEY ARE IN JOURNEY]\n- My product: [WHAT YOU SELL]\n- Fit: [HOW WE SUPPORT THEIR INITIATIVE]\n\nDiscovery areas:\n1. Current infrastructure (meters, comms, SCADA)\n2. Initiative scope and timeline\n3. Vendor relationships (who's already involved)\n4. Integration requirements\n5. Data management strategy\n6. Customer program goals\n7. Budget and funding source\n8. Regulatory requirements driving initiative\n9. Pilot vs. full deployment approach\n\nFor grid tech:\n- Who owns the decision (ops vs. IT vs. customer)\n- Procurement process (RFP likely)\n- Success metrics\n- Reference utilities they've talked to\n\nGrid modernization is multi-year - understand the full roadmap.","group":"energy"},{"id":"energy-coop-municipal","title":"Co-op / Municipal Utility Approach","category":"energy","subcategory":"outreach","tags":["coop","municipal","public-power"],"difficulty":"intermediate","description":"Approach for electric co-ops and muni utilities","prompt":"Create approach for co-ops and municipal utilities.\n\nContext:\n- Utility: [NAME]\n- Type: [ELECTRIC CO-OP / MUNICIPAL / PUBLIC POWER DISTRICT]\n- Size: [METERS / CUSTOMERS]\n- Region: [STATE/AREA]\n- My solution: [WHAT YOU SELL]\n- Value: [SPECIFIC BENEFIT FOR SMALLER UTILITIES]\n\nCo-op/Muni differences from IOUs:\n1. Smaller staff (fewer specialists)\n2. Board governance (elected or appointed)\n3. Member/customer focus (not shareholder)\n4. Limited budget for technology\n5. Rely on associations (NRECA, APPA)\n6. Often use cooperative buying programs\n\nApproach strategy:\n- Reference similar co-ops/munis\n- Emphasize ease of implementation\n- Address resource constraints\n- Show association partnerships if any\n- Be patient with board approval process\n- Consider joint purchasing opportunities\n\nThese are relationship sales - trust takes time.","group":"energy"},{"id":"energy-customer-program","title":"Utility Customer Program Pitch","category":"energy","subcategory":"proposals","tags":["customer-programs","demand-response","energy-efficiency"],"difficulty":"intermediate","description":"Pitch for utility customer programs (rebates, DR, EE)","prompt":"Pitch for a utility customer program initiative.\n\nContext:\n- Utility: [NAME]\n- Program type: [DEMAND RESPONSE / ENERGY EFFICIENCY / REBATES / RATES / EV]\n- Current program: [WHAT THEY HAVE TODAY]\n- Pain points: [PARTICIPATION / COST / MEASUREMENT]\n- My solution: [WHAT YOU SELL]\n- Program improvement: [HOW WE HELP]\n\nUtility customer program priorities:\n1. Participation rates\n2. Cost per kWh saved (or kW reduced)\n3. M&V (measurement and verification)\n4. Customer experience\n5. Equity and access\n6. Regulatory compliance\n7. Integration with other programs\n\nPosition around:\n- Increased participation\n- Lower program costs\n- Better customer experience\n- Improved M&V accuracy\n- Regulatory reporting\n\nCustomer programs are judged by regulators - help them look good.","group":"energy"},{"id":"fin-cold-email-1","title":"Compliance-Safe Cold Email","category":"financial-services","subcategory":"outreach","tags":["cold-email","compliance","finserv"],"difficulty":"intermediate","description":"Cold email for financial services that respects regulatory concerns","prompt":"Write a cold email to a financial services executive that respects compliance concerns.\n\nContext:\n- Recipient: [NAME, TITLE at FINANCIAL INSTITUTION]\n- Institution type: [BANK / CREDIT UNION / WEALTH MANAGEMENT / INSURANCE]\n- Regulatory environment: [KEY REGULATIONS: SOX, FINRA, SEC, PCI-DSS, etc.]\n- Signal: [WHAT TRIGGERED OUTREACH]\n- My solution: [WHAT YOU SELL]\n- Compliance benefit: [HOW YOU HELP WITH COMPLIANCE]\n\nFinancial Services Rules:\n- Never make claims you can't prove\n- Reference regulatory requirements by name\n- Emphasize security, audit trails, compliance\n- Mention relevant certifications (SOC 2, etc.)\n- Respect their risk-averse culture\n- No urgency tactics (they move slowly for good reasons)\n\nThe email should feel like it's from someone who understands their world.","group":"financialServices"},{"id":"fin-discovery-1","title":"Risk-Focused Discovery Questions","category":"financial-services","subcategory":"discovery","tags":["discovery","risk","compliance"],"difficulty":"intermediate","description":"Discovery questions for risk-averse financial buyers","prompt":"Generate discovery questions for a financial services buyer.\n\nContext:\n- Prospect: [NAME, TITLE at INSTITUTION]\n- Institution type: [TYPE]\n- My product: [WHAT YOU SELL]\n- Likely compliance concerns: [RELEVANT REGULATIONS]\n\nQuestion categories:\n1. Current vendor/process (who, what, how long)\n2. Compliance requirements (audits, reporting, certifications)\n3. Risk assessment (what could go wrong, what keeps them up at night)\n4. Decision process (who else needs to approve, procurement, legal)\n5. Security requirements (data handling, encryption, access controls)\n6. Integration needs (existing systems, IT involvement)\n\nFor each question, note:\n- Why this matters in financial services\n- Red flags to listen for\n- Follow-up questions","group":"financialServices"},{"id":"fin-objection-1","title":"Handle \"We Need to Check with Compliance\"","category":"financial-services","subcategory":"objections","tags":["objection","compliance","legal"],"difficulty":"advanced","description":"Navigate the compliance review objection","prompt":"Help me respond to: \"We need to run this by compliance first.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their institution: [TYPE AND SIZE]\n- Where we are in the deal: [STAGE]\n- Certifications I have: [SOC 2, ISO 27001, etc.]\n\nThis isn't an objection to overcome - it's a buying signal. Help me:\n1. Embrace the compliance review process\n2. Offer to participate in the review\n3. Provide documentation proactively\n4. Ask about their compliance review process\n5. Identify who in compliance I should meet\n\nThe goal is to be seen as a compliance ally, not a vendor trying to skip due diligence.","group":"financialServices"},{"id":"fin-proposal-1","title":"Risk Mitigation Executive Summary","category":"financial-services","subcategory":"proposals","tags":["proposal","risk","executive-summary"],"difficulty":"advanced","description":"Proposal summary that emphasizes risk reduction","prompt":"Write an executive summary for a financial services proposal.\n\nDeal context:\n- Institution: [NAME]\n- Type: [BANK / INSURANCE / WEALTH MGMT]\n- Problem: [WHAT THEY'RE SOLVING]\n- My solution: [YOUR PRODUCT]\n- Key compliance requirements: [REGULATIONS]\n- Risk factors of status quo: [CURRENT RISKS]\n\nFinancial services executive summaries need:\n1. Risk reduction framing (not just benefits)\n2. Compliance alignment (specific regulations)\n3. Security posture (certifications, controls)\n4. Implementation risk mitigation (phased rollout, training)\n5. Reference customers in their sector\n6. Total cost of ownership (they think long-term)\n\nTone: Conservative, thorough, trustworthy. No hype.","group":"financialServices"},{"id":"fin-follow-up-1","title":"Quarterly Review Meeting Request","category":"financial-services","subcategory":"follow-up","tags":["qbr","review","retention"],"difficulty":"beginner","description":"Request a QBR with a financial services client","prompt":"Write an email requesting a quarterly business review with a financial services client.\n\nContext:\n- Client: [INSTITUTION NAME]\n- Main contact: [NAME, TITLE]\n- How long they've been a customer: [TENURE]\n- Key wins this quarter: [RESULTS/METRICS]\n- Upcoming audit or regulatory deadline: [IF ANY]\n- Expansion opportunity: [IF ANY]\n\nQBR request should:\n1. Reference specific value delivered (metrics)\n2. Tie to their regulatory calendar if relevant\n3. Offer to include their compliance team\n4. Propose agenda topics\n5. Be respectful of their busy schedule\n\nFinancial services clients appreciate structure and documentation.","group":"financialServices"},{"id":"founder-first-10","title":"First 10 Customers Playbook","category":"founder","tags":["early-stage","customers","playbook"],"difficulty":"beginner","description":"Strategy for getting your first 10 paying customers","prompt":"Create a playbook for getting my first 10 customers.\n\nContext:\n- My product: [WHAT YOU'RE BUILDING]\n- Target customer: [WHO IT'S FOR]\n- Price point: [WHAT YOU'LL CHARGE]\n- Current stage: [PRE-LAUNCH / BETA / LAUNCHED]\n- My network: [WHO I KNOW IN THE SPACE]\n- Budget for sales: $[BUDGET]\n\nHelp me with:\n1. Where to find my first 10 (specific channels)\n2. How to reach out (templates for warm/cold)\n3. What to say on calls (discovery + pitch)\n4. How to handle \"it's too early\" objection\n5. When to charge vs. give free\n6. How to get referrals from early users\n\nFocus on scrappy, high-touch tactics. No paid ads or scale plays yet.","group":"founder"},{"id":"founder-sales-hire","title":"First Sales Hire Evaluation","category":"founder","tags":["hiring","sales-hire","evaluation"],"difficulty":"advanced","description":"Evaluate and interview your first sales hire","prompt":"Help me hire my first salesperson.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Deal size: [AVERAGE ACV]\n- Sales cycle: [LENGTH]\n- My involvement: [HOW MUCH I'LL STAY INVOLVED]\n- Budget: $[BASE + OTE]\n- What I've learned selling: [WHAT WORKS]\n\nHelp me with:\n1. Should I hire SDR, AE, or hybrid?\n2. What profile to look for (experience, traits)\n3. Interview questions that reveal the truth\n4. Role-play scenario to test their skills\n5. Comp structure recommendations\n6. 30-60-90 day plan for them\n7. Red flags to watch for\n\nI need someone who can figure things out, not just follow a playbook.","group":"founder"},{"id":"founder-investor-pitch","title":"Investor Sales Pitch","category":"founder","tags":["investor","pitch","gtm"],"difficulty":"advanced","description":"Pitch your go-to-market to investors","prompt":"Help me pitch my go-to-market strategy to investors.\n\nCompany context:\n- What we do: [PRODUCT DESCRIPTION]\n- Current ARR: $[ARR]\n- Customers: [NUMBER]\n- Growth rate: [MoM or YoY %]\n- Sales motion: [PLG / SALES-LED / HYBRID]\n- Team: [SALES TEAM SIZE]\n\nInvestors want to know:\n1. Who buys and why (ICP + pain)\n2. How you find them (channels)\n3. How you close them (process)\n4. Unit economics (CAC, LTV, payback)\n5. What changes with more capital\n\nCreate:\n- 3-minute GTM pitch script\n- Key metrics to highlight\n- Answers to tough questions\n- Competitive positioning\n- Scaling plan narrative","group":"founder"},{"id":"gov-cold-email-1","title":"Government Agency Cold Email","category":"government","subcategory":"outreach","tags":["cold-email","government","public-sector"],"difficulty":"intermediate","description":"Cold email for government decision makers","prompt":"Write a cold email to a government or public sector buyer.\n\nContext:\n- Recipient: [NAME, TITLE]\n- Agency/Department: [AGENCY NAME]\n- Level: [FEDERAL / STATE / LOCAL]\n- Mission: [WHAT THE AGENCY DOES]\n- Signal: [BUDGET CYCLE / NEW INITIATIVE / MANDATE]\n- My solution: [WHAT YOU SELL]\n- Contract vehicle: [IF APPLICABLE - GSA, SEWP, etc.]\n\nGovernment Email Rules:\n- Reference their mission and public service\n- Be aware of procurement rules and contract vehicles\n- Understand fiscal year budget cycles\n- Don't be pushy (they can't move fast even if they want to)\n- Reference FedRAMP, StateRAMP, or relevant certifications\n- Know the difference between end user and contracting officer\n\nGovernment buyers care about: mission, compliance, security, taxpayer value.","group":"government"},{"id":"gov-discovery-1","title":"Government Discovery Questions","category":"government","subcategory":"discovery","tags":["discovery","government","procurement"],"difficulty":"intermediate","description":"Discovery for government and public sector","prompt":"Generate discovery questions for a government prospect.\n\nContext:\n- Prospect: [NAME, TITLE at AGENCY]\n- Agency level: [FEDERAL / STATE / LOCAL]\n- My product: [WHAT YOU SELL]\n- Known initiative: [WHAT THEY'RE WORKING ON]\n\nGovernment discovery categories:\n1. Mission alignment (how this supports their mission)\n2. Current solution and pain points\n3. Budget and funding source (appropriated, grant, etc.)\n4. Procurement path (RFP, sole source, contract vehicle)\n5. Timeline and fiscal year considerations\n6. Security and compliance requirements\n7. Decision process (program office vs. IT vs. procurement)\n8. Stakeholders (end users, CIO, CISO, contracting)\n\nGovernment buying is complex - map the process early.","group":"government"},{"id":"gov-objection-1","title":"Handle \"We Need to Go Through Procurement\"","category":"government","subcategory":"objections","tags":["objection","procurement","rfp"],"difficulty":"advanced","description":"Navigate government procurement requirements","prompt":"Help me respond to: \"We'd need to put this out for competitive bid / go through procurement.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Agency: [AGENCY NAME AND LEVEL]\n- Deal size: [APPROXIMATE VALUE]\n- Contract vehicles we're on: [GSA, SEWP, STATE CONTRACTS, etc.]\n\nThis isn't an objection - it's reality. Help me:\n1. Understand their procurement options\n2. Identify applicable contract vehicles we're on\n3. Ask about sole source thresholds\n4. Offer to help with requirements definition\n5. Position for the eventual RFP\n6. Identify the contracting officer to build relationship\n\nNever try to circumvent procurement - help them navigate it.","group":"government"},{"id":"gov-proposal-1","title":"Government RFP Response Framework","category":"government","subcategory":"proposals","tags":["proposal","rfp","government"],"difficulty":"advanced","description":"Framework for responding to government RFPs","prompt":"Help me respond to a government RFP.\n\nContext:\n- Agency: [AGENCY NAME]\n- RFP number: [IF APPLICABLE]\n- Requirement summary: [WHAT THEY'RE BUYING]\n- Evaluation criteria: [HOW THEY'LL SCORE]\n- Page limits: [IF APPLICABLE]\n- Due date: [DEADLINE]\n- My solution: [WHAT YOU SELL]\n- Competitors likely: [WHO ELSE]\n\nGovernment RFP responses need:\n1. Strict compliance with instructions (follow exactly)\n2. Clear response to each requirement\n3. Past performance references (CPARS if federal)\n4. Pricing in required format\n5. Technical approach with specifics\n6. Key personnel and qualifications\n7. Small business participation (if required)\n8. Security certifications and compliance\n\nGovernment evaluators score objectively - make it easy for them.","group":"government"},{"id":"gov-follow-up-1","title":"End-of-Fiscal-Year Follow-Up","category":"government","subcategory":"follow-up","tags":["follow-up","fiscal-year","budget"],"difficulty":"beginner","description":"Re-engage before fiscal year end","prompt":"Write a follow-up email before fiscal year end.\n\nContext:\n- Agency: [AGENCY NAME]\n- Contact: [NAME, TITLE]\n- Fiscal year end: [SEPTEMBER 30 for federal, varies for state/local]\n- Our previous discussion: [CONTEXT]\n- My solution: [WHAT YOU SELL]\n- Deal size: [APPROXIMATE VALUE]\n\nEnd-of-fiscal-year follow-up should:\n1. Reference use-or-lose budget dynamics\n2. Offer expedited procurement options\n3. Mention contract vehicles for quick purchase\n4. Be helpful, not predatory (they know their budget)\n5. Offer to support with paperwork/justification\n\nSeptember is chaos for federal - be a helpful partner, not another vendor.","group":"government"},{"id":"gov-contract-vehicle","title":"Contract Vehicle Positioning","category":"government","subcategory":"proposals","tags":["contract-vehicle","gsa","gwac","bpa"],"difficulty":"intermediate","description":"Position your contract vehicles effectively","prompt":"Position my contract vehicles for this opportunity.\n\nContext:\n- Agency: [AGENCY NAME AND LEVEL]\n- Requirement: [WHAT THEY NEED]\n- Deal size: [ESTIMATED VALUE]\n- Our contract vehicles: [GSA / SEWP / CIO-SP3 / STATE CONTRACTS / ETC]\n- Competitor contract position: [IF KNOWN]\n\nContract vehicle positioning:\n1. Match vehicle to requirement type\n2. Explain acquisition benefits (faster, compliant, pre-competed)\n3. Show pricing and ordering process\n4. Provide contract numbers and contact info\n5. Offer to support with ordering documentation\n\nFor each applicable vehicle:\n- What it covers (scope)\n- Price list or rate card\n- How to order\n- Why it's fastest path\n- What to request from contracting\n\nMake procurement easy - they'll thank you for it.","group":"government"},{"id":"gov-stakeholder-coalition","title":"Government Stakeholder Coalition","category":"government","subcategory":"strategy","tags":["stakeholders","coalition","politics"],"difficulty":"advanced","description":"Build coalition across government stakeholders","prompt":"Build stakeholder coalition for government sale.\n\nContext:\n- Agency: [AGENCY NAME]\n- Initiative: [WHAT THEY'RE BUYING]\n- Known stakeholders: [WHO YOU KNOW]\n- Program office: [WHO OWNS THE REQUIREMENT]\n- IT/CIO office: [WHO APPROVES TECH]\n- Procurement: [WHO BUYS]\n\nMap and engage:\n1. Program Office (owns the mission need)\n2. CIO/IT (technical approval)\n3. CISO (security approval)\n4. Procurement/Contracting (acquisition)\n5. Budget/CFO (funding)\n6. End users (will use it)\n7. Leadership (executives)\n\nFor each stakeholder:\n- What they care about\n- How to approach them\n- What they need to approve\n- Potential blockers\n- How to align their interests\n\nGovernment requires consensus - build the coalition.","group":"government"},{"id":"gov-small-business","title":"Small Business / Set-Aside Positioning","category":"government","subcategory":"proposals","tags":["small-business","set-aside","8a","hubzone"],"difficulty":"intermediate","description":"Position for small business set-aside contracts","prompt":"Position for small business set-aside opportunity.\n\nContext:\n- Agency: [AGENCY NAME]\n- Set-aside type: [8(A) / HUBZONE / SDVOSB / WOSB / SB]\n- My certifications: [WHICH YOU HAVE]\n- Requirement: [WHAT THEY'RE BUYING]\n- Prime or sub: [YOUR ROLE]\n\nIf you're the small business:\n- Highlight certification and NAICS codes\n- Past performance at scale\n- Capability statement\n- Team/subcontractors for capacity\n\nIf you need a small business partner:\n- How to find partners (SAM, SBA, events)\n- Teaming agreement approach\n- Mentor-protégé if applicable\n- Subcontracting plan\n\nPositioning:\n- Meet the socioeconomic goal\n- Demonstrate capability\n- Price competitively\n- Show past performance\n\nSet-asides are opportunities - know the rules.","group":"government"},{"id":"gov-sled-approach","title":"State & Local Government Approach","category":"government","subcategory":"outreach","tags":["sled","state","local","municipal"],"difficulty":"intermediate","description":"Approach for state, county, and municipal sales","prompt":"Create approach for state/local government sales.\n\nContext:\n- Entity: [STATE AGENCY / COUNTY / CITY / SCHOOL DISTRICT]\n- Department: [WHICH DEPARTMENT]\n- My solution: [WHAT YOU SELL]\n- Relevant state contracts: [WHICH ONES YOU'RE ON]\n\nSLED differences from federal:\n1. Shorter procurement cycles (usually)\n2. Cooperative purchasing (NASPO, Sourcewell, TIPS)\n3. More relationship-driven\n4. Budget cycles vary by entity\n5. Often piggyback on existing contracts\n6. Smaller deals, higher volume\n\nEntry strategies:\n- State contract vehicles\n- Cooperative purchasing agreements\n- Piggyback clauses\n- Direct relationships\n- Reseller/partner network\n\nProvide outreach templates and qualification questions.","group":"government"},{"id":"gov-compliance-positioning","title":"Government Compliance Positioning","category":"government","subcategory":"objections","tags":["fedramp","fisma","security","compliance"],"difficulty":"advanced","description":"Position security and compliance certifications","prompt":"Position my compliance certifications for government.\n\nContext:\n- Agency: [AGENCY NAME]\n- Data sensitivity: [PUBLIC / SENSITIVE / CLASSIFIED]\n- Their requirements: [WHAT THEY'VE ASKED FOR]\n- Our certifications: [FEDRAMP / SOC2 / FISMA / IL4/5 / ETC]\n- Gaps: [WHAT WE DON'T HAVE]\n\nCompliance positioning by level:\nFederal Civilian:\n- FedRAMP (Moderate/High)\n- FISMA\n- Section 508\n\nDoD:\n- IL4/IL5\n- CMMC\n- ITAR if applicable\n\nState/Local:\n- StateRAMP\n- SOC 2\n- State-specific requirements\n\nFor each certification:\n- What it means\n- What it covers\n- How to verify\n- If we're pursuing (with timeline)\n\nMake compliance easy - provide documentation proactively.","group":"government"},{"id":"health-cold-email-1","title":"Clinical Stakeholder Cold Email","category":"healthcare","subcategory":"outreach","tags":["cold-email","clinical","healthcare"],"difficulty":"intermediate","description":"Cold email for reaching clinical decision-makers","prompt":"Write a cold email to a clinical stakeholder in healthcare.\n\nContext:\n- Recipient: [NAME, TITLE - e.g., Chief Medical Officer, VP Clinical Operations]\n- Organization: [HOSPITAL SYSTEM / HEALTH PLAN / MEDTECH COMPANY]\n- Size: [# BEDS / MEMBERS / EMPLOYEES]\n- Signal: [WHAT TRIGGERED OUTREACH]\n- My solution: [WHAT YOU SELL]\n- Patient outcome impact: [HOW YOU IMPROVE CARE]\n\nHealthcare Cold Email Rules:\n- Lead with patient outcomes, not features\n- Reference clinical evidence if available\n- Acknowledge HIPAA/PHI handling upfront\n- Respect their mission-driven culture\n- No aggressive sales tactics\n- Be specific about implementation timelines\n\nClinical stakeholders care about: patient safety, clinical workflows, staff burnout, evidence base.","group":"healthcare"},{"id":"health-discovery-1","title":"Healthcare Discovery Questions","category":"healthcare","subcategory":"discovery","tags":["discovery","clinical","hipaa"],"difficulty":"intermediate","description":"Discovery for healthcare with long buying cycles","prompt":"Generate discovery questions for a healthcare prospect.\n\nContext:\n- Prospect: [NAME, TITLE at ORGANIZATION]\n- Organization type: [HOSPITAL / CLINIC / PAYER / PHARMA]\n- My product: [WHAT YOU SELL]\n- Known initiative: [WHAT THEY'RE WORKING ON]\n\nDiscovery categories for healthcare:\n1. Clinical workflow impact (who uses it, when, how often)\n2. Patient outcome metrics (what they measure, targets)\n3. Compliance requirements (HIPAA, HITECH, state regs)\n4. Integration needs (EMR/EHR systems - Epic, Cerner, etc.)\n5. Budget cycle (fiscal year, capital vs. operating)\n6. Decision process (committees, clinical champions, IT, legal)\n7. Implementation concerns (training, change management)\n\nHealthcare buying cycles are long. Understand the full process upfront.","group":"healthcare"},{"id":"health-objection-1","title":"Handle \"We Need Clinical Validation\"","category":"healthcare","subcategory":"objections","tags":["objection","clinical","evidence"],"difficulty":"advanced","description":"Respond when they want clinical evidence","prompt":"Help me respond to: \"We need to see clinical validation / peer-reviewed studies.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Clinical evidence we have: [STUDIES / DATA / CASE STUDIES]\n- Evidence we don't have: [GAPS]\n- Similar products' evidence: [COMPETITOR EVIDENCE]\n\nThis is legitimate in healthcare. Help me:\n1. Present the evidence we do have credibly\n2. Acknowledge gaps honestly\n3. Propose a pilot/study if appropriate\n4. Connect them with reference customers\n5. Understand what level of evidence they actually need\n\nNever oversell clinical claims. It damages trust and can have regulatory implications.","group":"healthcare"},{"id":"health-proposal-1","title":"Healthcare Value Analysis Committee Proposal","category":"healthcare","subcategory":"proposals","tags":["proposal","vac","hospital"],"difficulty":"advanced","description":"Proposal for hospital value analysis committees","prompt":"Write a proposal summary for a hospital Value Analysis Committee.\n\nContext:\n- Hospital: [NAME]\n- Product category: [WHAT YOU'RE PROPOSING]\n- Clinical champion: [NAME, TITLE]\n- Current product/process: [WHAT THEY USE TODAY]\n- Clinical evidence: [STUDIES SUPPORTING YOUR PRODUCT]\n- Cost comparison: [PRICE VS CURRENT]\n- Patient outcome impact: [EXPECTED IMPROVEMENT]\n\nVAC proposals need:\n1. Clinical efficacy summary (evidence-based)\n2. Total cost analysis (not just unit price)\n3. Safety profile\n4. Comparison to current standard\n5. Implementation requirements\n6. Standardization benefits (if applicable)\n7. Staff feedback (if pilots were done)\n\nFormat: Structured for committee review, not narrative.","group":"healthcare"},{"id":"health-follow-up-1","title":"Post-Committee Follow-Up","category":"healthcare","subcategory":"follow-up","tags":["follow-up","committee","decision"],"difficulty":"intermediate","description":"Follow up after a committee review meeting","prompt":"Write a follow-up email after a committee reviewed my proposal.\n\nContext:\n- Organization: [HOSPITAL/HEALTH SYSTEM]\n- Committee: [VAC / P&T / CLINICAL COUNCIL / etc.]\n- My champion: [NAME, TITLE]\n- Meeting outcome: [APPROVED / TABLED / NEED MORE INFO]\n- Questions raised: [WHAT THEY ASKED]\n- Next steps discussed: [WHAT WAS AGREED]\n\nFollow-up should:\n1. Thank them for the thorough review\n2. Address specific questions raised\n3. Provide any additional documentation requested\n4. Confirm next steps and timeline\n5. Offer additional references or site visits\n\nMaintain patience - healthcare committees move deliberately.","group":"healthcare"},{"id":"health-pilot-proposal","title":"Clinical Pilot Proposal","category":"healthcare","subcategory":"proposals","tags":["pilot","clinical","trial"],"difficulty":"advanced","description":"Propose a clinical pilot program","prompt":"Create a clinical pilot proposal for a healthcare organization.\n\nContext:\n- Organization: [HOSPITAL/HEALTH SYSTEM NAME]\n- Department: [UNIT/SERVICE LINE]\n- Clinical sponsor: [NAME, TITLE]\n- Problem we're solving: [CLINICAL CHALLENGE]\n- Pilot duration: [WEEKS/MONTHS]\n- Success metrics: [WHAT WE'LL MEASURE]\n\nPilot proposal needs:\n1. Executive summary (why this pilot, why now)\n2. Clinical hypothesis (expected outcomes)\n3. Pilot design (scope, duration, population)\n4. Resource requirements (staff, systems, training)\n5. Data collection plan (what/how/who)\n6. Success criteria (measurable outcomes)\n7. Risk mitigation (what could go wrong)\n8. Path to full deployment (if pilot succeeds)\n9. Timeline with milestones\n10. Investment required\n\nFormat for clinical leadership review.","group":"healthcare"},{"id":"health-emr-integration","title":"EMR Integration Discussion Guide","category":"healthcare","subcategory":"discovery","tags":["emr","integration","epic","cerner"],"difficulty":"advanced","description":"Navigate EMR/EHR integration conversations","prompt":"Create a guide for discussing EMR integration.\n\nContext:\n- Organization: [HOSPITAL/HEALTH SYSTEM]\n- Their EMR: [EPIC / CERNER / MEDITECH / OTHER]\n- My product: [WHAT YOU SELL]\n- Integration needed: [READ / WRITE / BI-DIRECTIONAL]\n\nDiscussion topics:\n1. Their EMR version and customizations\n2. Integration standards (HL7, FHIR, APIs)\n3. IT team involvement and timeline\n4. Security and compliance requirements\n5. Past integration experiences (successes/failures)\n6. Vendor marketplace status (if Epic/Cerner)\n7. Budget for integration work\n8. Training and workflow impact\n\nQuestions to ask:\n- Technical questions for IT\n- Workflow questions for clinical\n- Timeline questions for project management\n- Budget questions for finance\n\nRed flags and how to address them.","group":"healthcare"},{"id":"health-payer-outreach","title":"Health Plan Cold Outreach","category":"healthcare","subcategory":"outreach","tags":["payer","health-plan","insurance"],"difficulty":"intermediate","description":"Cold email for health plan/payer organizations","prompt":"Write cold outreach for a health plan/payer.\n\nContext:\n- Organization: [HEALTH PLAN NAME]\n- Contact: [NAME, TITLE]\n- Plan type: [COMMERCIAL / MEDICARE / MEDICAID / ALL]\n- Members: [NUMBER]\n- My solution: [WHAT YOU SELL]\n- Value prop: [COST / QUALITY / MEMBER EXPERIENCE]\n\nPayer priorities to address:\n- Medical cost reduction (MLR improvement)\n- Quality scores (HEDIS, Stars)\n- Member experience (CAHPS)\n- Provider network management\n- Care management efficiency\n- Regulatory compliance\n\nEmail should:\n1. Demonstrate understanding of payer economics\n2. Quantify potential savings or quality improvement\n3. Reference similar plan results\n4. Address implementation without disrupting operations\n5. Propose low-commitment first step","group":"healthcare"},{"id":"health-physician-champion","title":"Building a Physician Champion","category":"healthcare","subcategory":"strategy","tags":["champion","physician","clinical"],"difficulty":"advanced","description":"Strategy for cultivating physician advocacy","prompt":"Help me build a physician champion for this deal.\n\nContext:\n- Organization: [HOSPITAL/HEALTH SYSTEM]\n- Product: [WHAT YOU SELL]\n- Physician candidates: [NAMES, SPECIALTIES]\n- Clinical value: [HOW PHYSICIANS BENEFIT]\n- Current status: [INTEREST LEVEL]\n\nChampion development strategy:\n1. Identify the right physician (criteria)\n2. Initial engagement approach\n3. Clinical value messaging for physicians\n4. Addressing \"I don't have time\" concern\n5. Peer influence strategies\n6. Getting them to advocate internally\n7. Supporting their internal presentation\n8. Maintaining relationship post-sale\n\nWhat physicians care about:\n- Patient outcomes\n- Workflow efficiency\n- Evidence and data\n- Peer validation\n- Recognition\n\nWhat turns physicians off:\n- Purely financial pitches\n- Overselling\n- Ignoring clinical concerns","group":"healthcare"},{"id":"health-regulatory-positioning","title":"Regulatory Compliance Positioning","category":"healthcare","subcategory":"objections","tags":["compliance","hipaa","regulatory"],"difficulty":"intermediate","description":"Position product for regulatory requirements","prompt":"Help me position my product for healthcare compliance.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Data handled: [PHI / CLINICAL / CLAIMS / OTHER]\n- Our certifications: [HITRUST / SOC2 / etc.]\n- Their requirements: [WHAT THEY'VE ASKED ABOUT]\n\nCompliance positioning:\n1. HIPAA compliance story\n2. Data security architecture summary\n3. BAA readiness and process\n4. Audit trail capabilities\n5. Data residency options\n6. Incident response process\n7. Staff training on compliance\n8. Third-party assessment results\n\nQuestions they might ask and answers:\n- \"How do you handle PHI?\"\n- \"Are you HITRUST certified?\"\n- \"What's your BAA process?\"\n- \"Where is data stored?\"\n- \"What about HITECH/Meaningful Use?\"\n- \"How do you handle breach notification?\"\n\nFormat as FAQ for their compliance team.","group":"healthcare"},{"id":"hospitality-cold-email-1","title":"Hotel/Travel Executive Cold Email","category":"hospitality","subcategory":"outreach","tags":["cold-email","hospitality","travel"],"difficulty":"intermediate","description":"Cold email for hospitality and travel companies","prompt":"Write a cold email to a hospitality or travel executive.\n\nContext:\n- Recipient: [NAME, TITLE]\n- Company type: [HOTEL / AIRLINE / OTA / RESTAURANT GROUP / CRUISE]\n- Size: [PROPERTIES / LOCATIONS / FLEET]\n- Signal: [EXPANSION / RENOVATION / TECH UPGRADE / LABOR CHALLENGE]\n- My solution: [WHAT YOU SELL]\n- Guest/operational impact: [HOW YOU HELP]\n\nHospitality Email Rules:\n- Understand their guest experience focus\n- Reference RevPAR, occupancy, or relevant metrics\n- Be aware of seasonal patterns\n- Speak to labor challenges and efficiency\n- Mention franchise vs. managed vs. owned dynamics\n- Reference similar brands or properties\n\nHospitality buyers care about: guest experience, RevPAR, operational efficiency, labor.","group":"hospitality"},{"id":"hospitality-discovery-1","title":"Hospitality Discovery Questions","category":"hospitality","subcategory":"discovery","tags":["discovery","hospitality","operations"],"difficulty":"intermediate","description":"Discovery for hospitality and travel sales","prompt":"Generate discovery questions for a hospitality prospect.\n\nContext:\n- Prospect: [NAME, TITLE at COMPANY]\n- Hospitality type: [HOTEL / RESTAURANT / TRAVEL]\n- My product: [WHAT YOU SELL]\n- Known challenge: [GUEST EXPERIENCE / LABOR / REVENUE]\n\nHospitality discovery categories:\n1. Property/portfolio overview\n2. Guest experience priorities\n3. Current technology stack (PMS, POS, CRM)\n4. Labor challenges and costs\n5. Revenue management approach\n6. Brand standards and corporate requirements\n7. Decision process (property vs. corporate)\n8. Seasonality and planning cycles\n\nHospitality is fragmented - understand property vs. corporate dynamics.","group":"hospitality"},{"id":"hospitality-objection-1","title":"Handle \"We Have a Preferred Vendor\"","category":"hospitality","subcategory":"objections","tags":["objection","preferred-vendor","brand"],"difficulty":"advanced","description":"Navigate brand-mandated vendor relationships","prompt":"Help me respond to: \"Our brand has a preferred vendor for that.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their brand: [HOTEL BRAND / CHAIN]\n- Preferred vendor: [WHO IT IS - if known]\n- Our positioning: [WHY WE'RE DIFFERENT]\n\nBrand standards are real in hospitality. Help me:\n1. Understand if it's required or preferred\n2. Ask about exceptions or pilots\n3. Find properties with more autonomy\n4. Position for preferred vendor list\n5. Identify gaps the preferred vendor doesn't cover\n6. Connect with corporate brand technology team\n\nWork with brand standards, not against them.","group":"hospitality"},{"id":"hospitality-proposal-1","title":"Hospitality Technology Proposal","category":"hospitality","subcategory":"proposals","tags":["proposal","hospitality","technology"],"difficulty":"advanced","description":"Build a case for hospitality tech investment","prompt":"Write a proposal for a hospitality technology investment.\n\nContext:\n- Company: [BRAND/PROPERTY NAME]\n- Property count: [NUMBER OF PROPERTIES]\n- Challenge: [WHAT THEY'RE SOLVING]\n- My solution: [WHAT YOU SELL]\n- Investment: [YOUR PRICE]\n- Expected outcomes: [METRICS]\n\nHospitality proposals need:\n1. Guest experience impact\n2. Operational efficiency gains\n3. Revenue impact (RevPAR, ADR, occupancy)\n4. Labor savings (huge in hospitality)\n5. Integration with PMS and other systems\n6. Roll-out plan across properties\n7. Brand standards compliance\n8. Reference properties\n\nHospitality buyers need ROI per property.","group":"hospitality"},{"id":"hospitality-follow-up-1","title":"Post-Peak-Season Follow-Up","category":"hospitality","subcategory":"follow-up","tags":["follow-up","seasonal","planning"],"difficulty":"beginner","description":"Re-engage after busy travel season","prompt":"Write a follow-up email after peak travel season.\n\nContext:\n- Company: [BRAND/PROPERTY]\n- Contact: [NAME, TITLE]\n- Their peak: [SUMMER / HOLIDAY / CONVENTION SEASON]\n- Their results: [IF KNOWN]\n- Our previous discussion: [CONTEXT]\n- My solution: [WHAT YOU SELL]\n\nPost-peak follow-up should:\n1. Acknowledge the peak season push\n2. Congratulate on results if public\n3. Ask about pain points that emerged\n4. Connect to solutions for next season\n5. Propose planning conversation\n\nOff-peak is planning season in hospitality. Strike while they have time.","group":"hospitality"},{"id":"insurance-cold-email-1","title":"Insurance Executive Cold Email","category":"insurance","subcategory":"outreach","tags":["cold-email","insurance","carrier"],"difficulty":"intermediate","description":"Cold email for insurance carriers and agencies","prompt":"Write a cold email to an insurance executive.\n\nContext:\n- Recipient: [NAME, TITLE]\n- Company type: [CARRIER / MGA / AGENCY / BROKER / INSURTECH]\n- Lines of business: [P&C / LIFE / HEALTH / SPECIALTY]\n- Signal: [DIGITAL TRANSFORMATION / LOSS RATIO / NEW PRODUCT]\n- My solution: [WHAT YOU SELL]\n- Underwriting/claims impact: [HOW YOU HELP]\n\nInsurance Email Rules:\n- Understand their role in the value chain\n- Reference loss ratios, combined ratios, or relevant metrics\n- Be aware of regulatory requirements\n- Speak to underwriting, claims, or distribution challenges\n- Mention relevant integrations (policy admin, claims systems)\n- Reference AM Best ratings or market position\n\nInsurance buyers care about: loss ratio, customer retention, operational efficiency, compliance.","group":"insurance"},{"id":"insurance-discovery-1","title":"Insurance Discovery Questions","category":"insurance","subcategory":"discovery","tags":["discovery","insurance","underwriting"],"difficulty":"intermediate","description":"Discovery for insurance technology sales","prompt":"Generate discovery questions for an insurance prospect.\n\nContext:\n- Prospect: [NAME, TITLE at COMPANY]\n- Insurance type: [CARRIER / MGA / AGENCY]\n- Lines of business: [P&C / LIFE / HEALTH]\n- My product: [WHAT YOU SELL]\n- Known challenge: [UNDERWRITING / CLAIMS / DISTRIBUTION]\n\nInsurance discovery categories:\n1. Business model and lines of business\n2. Current pain points by function\n3. Technology stack (policy admin, claims, CRM)\n4. Underwriting and pricing approach\n5. Claims process and efficiency\n6. Distribution strategy (agents, direct, digital)\n7. Regulatory and compliance requirements\n8. Decision process (IT vs. business, long cycles)\n\nInsurance is regulated and risk-averse - understand their constraints.","group":"insurance"},{"id":"insurance-objection-1","title":"Handle \"Our Systems Are Legacy\"","category":"insurance","subcategory":"objections","tags":["objection","legacy","integration"],"difficulty":"advanced","description":"Navigate legacy system concerns in insurance","prompt":"Help me respond to: \"Our core systems are legacy and hard to integrate with.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their systems: [WHAT THEY USE - if known]\n- Our integration approach: [HOW WE CONNECT]\n- Their modernization plans: [IF KNOWN]\n\nLegacy systems are endemic in insurance. Help me:\n1. Acknowledge the reality (insurance has massive technical debt)\n2. Ask about their modernization roadmap\n3. Explain our approach to legacy integration\n4. Reference similar carriers we've integrated with\n5. Propose a phased approach\n6. Position as stepping stone to modernization\n\nNever underestimate the complexity of insurance legacy systems.","group":"insurance"},{"id":"insurance-proposal-1","title":"Insurance Technology Proposal","category":"insurance","subcategory":"proposals","tags":["proposal","insurance","technology"],"difficulty":"advanced","description":"Build a case for insurance tech investment","prompt":"Write a proposal for an insurance technology investment.\n\nContext:\n- Carrier/Company: [NAME]\n- Lines of business: [P&C / LIFE / HEALTH]\n- Challenge: [WHAT THEY'RE SOLVING]\n- My solution: [WHAT YOU SELL]\n- Investment: [YOUR PRICE]\n- Expected outcomes: [METRICS]\n\nInsurance proposals need:\n1. Loss ratio or combined ratio impact\n2. Underwriting efficiency gains\n3. Claims processing improvements\n4. Compliance and regulatory alignment\n5. Integration approach with core systems\n6. Implementation timeline and phases\n7. Security and data requirements\n8. Reference carriers (same lines of business)\n\nInsurance buyers need actuarial-level rigor in business cases.","group":"insurance"},{"id":"insurance-follow-up-1","title":"Post-Renewal-Season Follow-Up","category":"insurance","subcategory":"follow-up","tags":["follow-up","renewal","seasonal"],"difficulty":"beginner","description":"Re-engage after insurance renewal season","prompt":"Write a follow-up email after renewal season.\n\nContext:\n- Company: [CARRIER/AGENCY]\n- Contact: [NAME, TITLE]\n- Renewal season: [1/1, 7/1, or other]\n- Their results: [IF KNOWN]\n- Our previous discussion: [CONTEXT]\n- My solution: [WHAT YOU SELL]\n\nPost-renewal follow-up should:\n1. Acknowledge the intensity of renewal season\n2. Ask how the renewal cycle went\n3. Identify pain points that emerged\n4. Connect to solutions for next cycle\n5. Propose planning conversation\n\nInsurance has seasonal intensity around renewals. Time outreach accordingly.","group":"insurance"},{"id":"logistics-cold-email-1","title":"Supply Chain Executive Cold Email","category":"logistics","subcategory":"outreach","tags":["cold-email","supply-chain","operations"],"difficulty":"intermediate","description":"Cold email for VP Supply Chain or Logistics Director","prompt":"Write a cold email to a supply chain or logistics executive.\n\nContext:\n- Recipient: [NAME, TITLE - VP Supply Chain, Director of Logistics, etc.]\n- Company: [COMPANY NAME]\n- Industry: [THEIR INDUSTRY]\n- Signal: [EXPANSION / DISRUPTION / EFFICIENCY INITIATIVE]\n- My solution: [WHAT YOU SELL]\n- Key metric impact: [ON-TIME DELIVERY / INVENTORY TURNS / FREIGHT COST]\n\nLogistics Email Rules:\n- Lead with operational metrics (OTIF, inventory turns, freight spend)\n- Reference supply chain disruptions or challenges\n- Speak to visibility, efficiency, resilience\n- Understand their network complexity\n- Be practical - logistics leaders are operators\n- Reference similar companies or industries\n\nSupply chain executives care about: reliability, cost, visibility, speed, flexibility.","group":"logistics"},{"id":"logistics-discovery-1","title":"Supply Chain Discovery Questions","category":"logistics","subcategory":"discovery","tags":["discovery","supply-chain","operations"],"difficulty":"intermediate","description":"Discovery for supply chain technology sales","prompt":"Generate discovery questions for a supply chain prospect.\n\nContext:\n- Prospect: [NAME, TITLE at COMPANY]\n- Supply chain type: [MANUFACTURING / RETAIL / 3PL / DISTRIBUTION]\n- My product: [WHAT YOU SELL]\n- Known challenges: [VISIBILITY / COST / SPEED / RELIABILITY]\n\nSupply chain discovery categories:\n1. Network overview (facilities, partners, geography)\n2. Current pain (where things break down)\n3. Technology stack (TMS, WMS, ERP, visibility tools)\n4. Key metrics (OTIF, inventory days, freight cost per unit)\n5. Decision process (ops vs. IT vs. finance)\n6. Integration requirements (EDI, API, ERP connection)\n7. Seasonality and peaks (planning cycles)\n\nSupply chain is complex - map the network before proposing solutions.","group":"logistics"},{"id":"logistics-objection-1","title":"Handle \"We Have Too Many Systems Already\"","category":"logistics","subcategory":"objections","tags":["objection","integration","systems"],"difficulty":"advanced","description":"Navigate integration fatigue in supply chain","prompt":"Help me respond to: \"We have too many systems already. We can't add another one.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their current stack: [SYSTEMS THEY MENTIONED]\n- Integration approach: [HOW WE CONNECT]\n- Our differentiation: [WHAT WE DO BETTER]\n\nThis is common in supply chain (system fatigue is real). Help me:\n1. Acknowledge the integration burden\n2. Ask about specific pain their current systems don't solve\n3. Position as consolidating/simplifying (if true)\n4. Explain our integration approach clearly\n5. Offer to map to their existing architecture\n6. Propose a pilot that proves integration ease\n\nNever dismiss their concern - supply chain integration is genuinely hard.","group":"logistics"},{"id":"logistics-proposal-1","title":"Supply Chain ROI Proposal","category":"logistics","subcategory":"proposals","tags":["proposal","roi","logistics"],"difficulty":"advanced","description":"Build an ROI case for logistics investment","prompt":"Write an ROI-focused proposal for a supply chain investment.\n\nContext:\n- Company: [NAME]\n- Annual freight spend: [IF KNOWN]\n- Current metrics: [OTIF %, INVENTORY DAYS, COST PER ORDER]\n- Pain points: [SPECIFIC ISSUES]\n- My solution: [WHAT YOU SELL]\n- Expected improvements: [TARGET METRICS]\n- Investment: [YOUR PRICE]\n\nSupply chain proposals need:\n1. Baseline metrics (current state)\n2. Industry benchmarks (where they should be)\n3. Hard dollar savings (freight, labor, inventory)\n4. Soft benefits (visibility, speed, customer satisfaction)\n5. Implementation timeline and phases\n6. Integration requirements and effort\n7. Risk factors and mitigation\n8. Reference customers in similar situations\n\nSupply chain buyers want specific, defensible numbers.","group":"logistics"},{"id":"logistics-follow-up-1","title":"Peak Season Follow-Up","category":"logistics","subcategory":"follow-up","tags":["follow-up","peak-season","operations"],"difficulty":"beginner","description":"Re-engage after peak shipping season","prompt":"Write a follow-up email after peak shipping season.\n\nContext:\n- Company: [NAME]\n- Contact: [NAME, TITLE]\n- Their peak: [HOLIDAY / BACK-TO-SCHOOL / SEASONAL]\n- How peak went: [IF KNOWN]\n- Our last conversation: [CONTEXT]\n- My solution: [WHAT YOU SELL]\n\nPost-peak follow-up should:\n1. Acknowledge the intensity of peak season\n2. Ask how it went (genuinely curious)\n3. Connect any problems to your solution\n4. Propose a planning conversation for next year\n5. Reference specific improvements you could have helped with\n\nJanuary-February is planning season for most supply chains. Be present.","group":"logistics"},{"id":"logistics-3pl-pitch","title":"3PL Provider Pitch","category":"logistics","subcategory":"outreach","tags":["3pl","provider","warehouse"],"difficulty":"intermediate","description":"Pitch to third-party logistics providers","prompt":"Create a pitch for a 3PL provider.\n\nContext:\n- 3PL: [COMPANY NAME]\n- Size: [WAREHOUSES / SHIPMENTS]\n- Specialization: [E-COMMERCE / RETAIL / B2B / COLD CHAIN]\n- Their customers: [WHO THEY SERVE]\n- My solution: [WHAT YOU SELL]\n- Operational impact: [HOW YOU HELP]\n\n3PL value drivers:\n1. Margin improvement (their business is thin margins)\n2. Customer stickiness (reduce churn)\n3. New capability for sales team\n4. Operational efficiency (labor, space)\n5. Customer visibility demands\n6. Competitive differentiation\n\nPosition for:\n- Operations team (efficiency)\n- Sales team (new capabilities to sell)\n- Executive team (margin and growth)\n\n3PLs sell your product to their customers - help them sell.","group":"logistics"},{"id":"logistics-shipper-pitch","title":"Shipper Direct Pitch","category":"logistics","subcategory":"outreach","tags":["shipper","brand","retail"],"difficulty":"intermediate","description":"Pitch to companies that ship goods (brands, retailers)","prompt":"Create a pitch for a shipper (brand/retailer).\n\nContext:\n- Company: [BRAND/RETAILER NAME]\n- Industry: [CPG / RETAIL / MANUFACTURING / ETC]\n- Shipping volume: [ANNUAL SHIPMENTS OR FREIGHT SPEND]\n- Current setup: [IN-HOUSE / 3PL / HYBRID]\n- Pain points: [COST / VISIBILITY / SPEED / COMPLEXITY]\n- My solution: [WHAT YOU SELL]\n\nShipper priorities:\n1. Freight cost management\n2. On-time delivery (customer experience)\n3. Inventory optimization\n4. Visibility and control\n5. Carrier performance\n6. Claims and damages\n\nPosition around:\n- Cost savings (freight spend reduction)\n- Service improvement (OTIF, customer satisfaction)\n- Visibility (track and trace, exception management)\n- Operational efficiency (automation, reporting)\n\nShippers are cost-conscious but increasingly service-focused.","group":"logistics"},{"id":"logistics-carrier-pitch","title":"Carrier Sales Pitch","category":"logistics","subcategory":"outreach","tags":["carrier","trucking","transportation"],"difficulty":"intermediate","description":"Pitch to trucking companies and carriers","prompt":"Create a pitch for a trucking/carrier company.\n\nContext:\n- Carrier: [COMPANY NAME]\n- Size: [FLEET SIZE / DRIVERS]\n- Type: [TL / LTL / SPECIALIZED / DRAYAGE]\n- Service area: [REGIONAL / NATIONAL / CROSS-BORDER]\n- My solution: [WHAT YOU SELL]\n- Operational benefit: [DRIVER RETENTION / EFFICIENCY / MARGIN]\n\nCarrier pain points:\n1. Driver recruitment and retention\n2. Asset utilization (empty miles)\n3. Fuel costs\n4. Compliance (ELD, HOS, safety)\n5. Rate pressure from brokers/shippers\n6. Operating ratio\n\nPosition around:\n- Driver satisfaction (reduces turnover)\n- Revenue per truck (better utilization)\n- Compliance simplification\n- Cost reduction (fuel, maintenance)\n- Shipper relationships (service improvement)\n\nCarriers are margin-sensitive. Show clear ROI fast.","group":"logistics"},{"id":"logistics-disruption-outreach","title":"Supply Chain Disruption Outreach","category":"logistics","subcategory":"outreach","tags":["disruption","trigger","timely"],"difficulty":"intermediate","description":"Outreach when supply chain disruption is news","prompt":"Create outreach tied to supply chain disruption news.\n\nDisruption type:\n- Port congestion/strike\n- Weather event\n- Geopolitical issue\n- Carrier bankruptcy\n- Pandemic impact\n- Capacity crisis\n\nContext:\n- Prospect: [COMPANY]\n- How they're affected: [IMPACT]\n- My solution: [WHAT YOU SELL]\n- How we help in crisis: [SPECIFIC VALUE]\n\nOutreach approach:\n1. Acknowledge the disruption (don't exploit tragedy)\n2. Be genuinely helpful (not opportunistic)\n3. Offer insight or assistance first\n4. Connect to prevention/mitigation\n5. Position as long-term resilience\n\nProvide:\n- Email template\n- LinkedIn message\n- Call script\n- Helpful resource to share\n\nBe helpful, not vulture-like.","group":"logistics"},{"id":"logistics-integration-guide","title":"Logistics Integration Discussion Guide","category":"logistics","subcategory":"discovery","tags":["integration","tms","wms","erp"],"difficulty":"advanced","description":"Navigate TMS/WMS/ERP integration conversations","prompt":"Guide for discussing logistics system integration.\n\nContext:\n- Prospect: [COMPANY]\n- Their systems: [TMS / WMS / ERP / OTHER]\n- Integration needed: [API / EDI / FILE / NATIVE]\n- My product: [WHAT YOU SELL]\n- Our integration approach: [HOW WE CONNECT]\n\nDiscussion topics:\n1. Current system landscape\n2. Integration pain points today\n3. IT team involvement and capacity\n4. Standards they use (EDI 204/214/990, API)\n5. Data requirements\n6. Timeline and phasing\n7. Who's done integrations before\n\nQuestions to ask:\n- What's your current integration architecture?\n- What's worked well with past integrations?\n- What's been challenging?\n- Who owns integrations internally?\n- What's your testing process?\n\nRed flags and how to address them.","group":"logistics"},{"id":"mfg-cold-email-1","title":"Plant Manager Cold Email","category":"manufacturing","subcategory":"outreach","tags":["cold-email","plant-manager","operations"],"difficulty":"intermediate","description":"Cold email for reaching plant managers and operations leaders","prompt":"Write a cold email to a plant manager or VP of Operations.\n\nContext:\n- Recipient: [NAME, TITLE]\n- Company: [MANUFACTURER NAME]\n- Industry: [DISCRETE / PROCESS / HYBRID MANUFACTURING]\n- Plant size: [EMPLOYEES / OUTPUT]\n- Signal: [EXPANSION / NEW LINE / EFFICIENCY INITIATIVE]\n- My solution: [WHAT YOU SELL]\n- Metric impact: [OEE / THROUGHPUT / DOWNTIME REDUCTION]\n\nManufacturing Email Rules:\n- Lead with operational metrics (OEE, throughput, yield)\n- Speak their language (downtime, changeover, scrap rate)\n- Reference specific manufacturing challenges\n- Be practical, not theoretical\n- Respect their limited time off the floor\n- Offer plant visit or demo on their turf\n\nPlant managers care about: uptime, safety, quality, efficiency, their team.","group":"manufacturing"},{"id":"mfg-discovery-1","title":"Manufacturing Discovery Questions","category":"manufacturing","subcategory":"discovery","tags":["discovery","oee","operations"],"difficulty":"intermediate","description":"Discovery for manufacturing operations","prompt":"Generate discovery questions for a manufacturing prospect.\n\nContext:\n- Prospect: [NAME, TITLE at COMPANY]\n- Manufacturing type: [DISCRETE / PROCESS / ASSEMBLY]\n- My product: [WHAT YOU SELL]\n- Known pain: [EFFICIENCY / QUALITY / SUPPLY CHAIN]\n\nManufacturing discovery categories:\n1. Current operations (shifts, lines, throughput targets)\n2. Pain quantification (downtime hours, scrap %, OEE)\n3. Existing systems (MES, ERP, SCADA, PLCs)\n4. Decision process (plant vs corporate, capex vs opex)\n5. Implementation reality (production schedules, maintenance windows)\n6. Success metrics (how they measure improvement)\n7. ROI requirements (payback period expectations)\n\nAsk about specific lines or processes - get concrete, not abstract.","group":"manufacturing"},{"id":"mfg-objection-1","title":"Handle \"Can't Disrupt Production\"","category":"manufacturing","subcategory":"objections","tags":["objection","implementation","production"],"difficulty":"advanced","description":"Overcome implementation timing concerns","prompt":"Help me respond to: \"We can't risk disrupting production for implementation.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their operation: [TYPE OF MANUFACTURING]\n- Implementation requirements: [WHAT'S NEEDED]\n- Our approach: [HOW WE MINIMIZE DISRUPTION]\n\nThis is the #1 objection in manufacturing. Help me:\n1. Validate their concern (production uptime is sacred)\n2. Explain phased implementation options\n3. Reference similar implementations that didn't disrupt\n4. Propose implementation during planned downtime\n5. Offer risk mitigation (parallel running, rollback plan)\n6. Quantify cost of waiting vs. implementation risk\n\nNever minimize their concern - show you understand manufacturing realities.","group":"manufacturing"},{"id":"mfg-proposal-1","title":"Manufacturing ROI Proposal","category":"manufacturing","subcategory":"proposals","tags":["proposal","roi","capex"],"difficulty":"advanced","description":"ROI-focused proposal for manufacturing capex","prompt":"Write an ROI-focused proposal for a manufacturing investment.\n\nContext:\n- Company: [MANUFACTURER]\n- Plant/Line: [SPECIFIC AREA]\n- Current state: [METRICS TODAY - OEE, DOWNTIME, SCRAP]\n- Proposed solution: [YOUR PRODUCT]\n- Investment: [TOTAL COST]\n- Expected improvement: [TARGET METRICS]\n- Payback expectation: [THEIR REQUIREMENT - usually 12-24 months]\n\nManufacturing proposals need:\n1. Clear baseline metrics (current state)\n2. Conservative improvement projections\n3. Payback calculation (months)\n4. NPV/IRR if they require it\n5. Risk factors acknowledged\n6. Implementation timeline\n7. Resource requirements (their side)\n8. Reference plants/case studies with actual results\n\nManufacturing buyers want hard numbers, not promises.","group":"manufacturing"},{"id":"mfg-follow-up-1","title":"Post-Plant-Visit Follow-Up","category":"manufacturing","subcategory":"follow-up","tags":["follow-up","plant-visit","operations"],"difficulty":"beginner","description":"Follow up after a manufacturing plant visit","prompt":"Write a follow-up email after visiting a manufacturing plant.\n\nContext:\n- Company: [MANUFACTURER]\n- Plant visited: [LOCATION]\n- People I met: [NAMES, TITLES]\n- What I observed: [SPECIFIC OBSERVATIONS]\n- Pain points discussed: [WHAT THEY SHARED]\n- Next steps agreed: [WHAT WAS DECIDED]\n\nFollow-up should:\n1. Thank them for the plant access (this is a big deal)\n2. Reference specific things you saw/discussed\n3. Connect observations to your solution\n4. Provide any requested information\n5. Confirm next steps\n6. Offer additional technical resources\n\nBe specific - show you paid attention during the visit.","group":"manufacturing"},{"id":"mfg-supply-chain-pain","title":"Supply Chain Pain Discovery","category":"manufacturing","subcategory":"discovery","tags":["supply-chain","discovery","logistics"],"difficulty":"intermediate","description":"Uncover supply chain challenges in manufacturing","prompt":"Generate questions to uncover supply chain pain in manufacturing.\n\nContext:\n- Company: [MANUFACTURER]\n- Industry: [AUTOMOTIVE / AEROSPACE / CONSUMER / INDUSTRIAL]\n- Supply chain complexity: [LOCAL / REGIONAL / GLOBAL]\n- My solution: [HOW YOU HELP SUPPLY CHAIN]\n\nDiscovery areas:\n1. Supplier management (number, quality, reliability)\n2. Inventory challenges (carrying costs, stockouts, obsolescence)\n3. Visibility gaps (where they lose sight of materials)\n4. Planning accuracy (forecast vs. actual)\n5. Lead time pressures (customer expectations vs. reality)\n6. Recent disruptions (what went wrong)\n7. Regulatory/traceability requirements\n\nQuestions should uncover:\n- Quantified pain (dollars, days, units)\n- Who owns the problem\n- Failed solutions they've tried\n- Timeline for addressing it","group":"manufacturing"},{"id":"mfg-quality-pitch","title":"Quality Improvement Positioning","category":"manufacturing","subcategory":"proposals","tags":["quality","six-sigma","defects"],"difficulty":"intermediate","description":"Position solution around quality metrics","prompt":"Create quality-focused positioning for manufacturing.\n\nContext:\n- Company: [MANUFACTURER]\n- Quality challenges: [DEFECT RATE / RECALLS / SCRAP]\n- Current quality metrics: [PPM, COPQ, FIRST PASS YIELD]\n- My solution: [WHAT YOU SELL]\n- Quality impact: [HOW YOU IMPROVE QUALITY]\n\nPosition around:\n1. Cost of Poor Quality (COPQ) calculation\n2. Defect reduction potential\n3. Traceability and root cause analysis\n4. Compliance/audit readiness\n5. Customer quality requirements (OEM scorecards)\n6. Quality certifications (ISO, IATF, AS9100)\n\nBuild a quality-focused value prop:\n- Current state cost (scrap, rework, warranty, recalls)\n- Future state improvement (specific metrics)\n- ROI calculation\n- Risk mitigation (avoid costly recalls)\n- Competitive advantage (quality reputation)","group":"manufacturing"},{"id":"mfg-oem-supplier-approach","title":"OEM Supplier Positioning","category":"manufacturing","subcategory":"outreach","tags":["oem","supplier","automotive","aerospace"],"difficulty":"advanced","description":"Position to Tier 1/2/3 automotive or aerospace suppliers","prompt":"Create outreach for an OEM supplier.\n\nContext:\n- Company: [SUPPLIER NAME]\n- Tier: [TIER 1 / TIER 2 / TIER 3]\n- OEM customers: [WHO THEY SUPPLY - GM, Ford, Boeing, etc.]\n- My solution: [WHAT YOU SELL]\n- Supplier requirements addressed: [QUALITY / DELIVERY / COST]\n\nOEM supplier pressures:\n- Cost-down demands (annual price reductions)\n- Quality scorecards (PPM targets, audits)\n- Delivery performance (JIT, sequencing)\n- Engineering changes (rapid response required)\n- Capacity investments (without guaranteed volume)\n\nPositioning should address:\n1. Meeting OEM requirements more efficiently\n2. Improving scorecard performance\n3. Reducing cost to offset margin pressure\n4. Enabling faster response to changes\n5. Providing audit-ready documentation\n\nInclude references to similar tier suppliers if possible.","group":"manufacturing"},{"id":"mfg-digital-transformation","title":"Industry 4.0 / Digital Transformation Pitch","category":"manufacturing","subcategory":"proposals","tags":["industry-4.0","digital","iot","automation"],"difficulty":"advanced","description":"Position for manufacturing digital transformation initiatives","prompt":"Create positioning for Industry 4.0 / digital transformation.\n\nContext:\n- Company: [MANUFACTURER]\n- Digital maturity: [EARLY / ADVANCING / MATURE]\n- Initiative: [SMART FACTORY / IIoT / AUTOMATION / DATA ANALYTICS]\n- My solution: [WHAT YOU SELL]\n- Digital transformation fit: [HOW YOU ENABLE]\n\nAddress common executive questions:\n1. What's the ROI on digital initiatives?\n2. How does this fit with our existing systems?\n3. What skills do we need on our team?\n4. What's the implementation risk?\n5. How do we scale beyond a pilot?\n\nCreate a digital transformation business case:\n- Current state (manual, disconnected, reactive)\n- Future state (automated, connected, predictive)\n- Journey/roadmap (realistic phases)\n- Investment required vs. value created\n- Risk mitigation approach\n- Success stories from similar manufacturers","group":"manufacturing"},{"id":"mfg-ehs-safety-angle","title":"EHS/Safety Value Positioning","category":"manufacturing","subcategory":"objections","tags":["safety","ehs","compliance","environment"],"difficulty":"intermediate","description":"Position product with safety and environmental benefits","prompt":"Create safety/EHS-focused positioning.\n\nContext:\n- Company: [MANUFACTURER]\n- Industry: [IMPACTS REGULATORY ENVIRONMENT]\n- Safety challenges: [KNOWN ISSUES]\n- My solution: [WHAT YOU SELL]\n- Safety/EHS impact: [HOW YOU IMPROVE SAFETY]\n\nSafety value angles:\n1. Incident reduction (recordable rate, lost time)\n2. Compliance assurance (OSHA, EPA, state regulations)\n3. Risk mitigation (costly accidents, liability)\n4. Insurance implications (lower premiums possible)\n5. Worker satisfaction (safer environment)\n6. Audit readiness (documentation, training records)\n\nPosition for different audiences:\n- Plant manager (operational + liability)\n- EHS manager (compliance + metrics)\n- CFO (cost of incidents + insurance)\n- HR (worker satisfaction + retention)\n\nInclude ROI of safety improvements (cost of incidents avoided).","group":"manufacturing"},{"id":"meddpicc-qualification","title":"MEDDPICC Deal Qualification","category":"meddpicc","tags":["qualification","enterprise","meddpicc"],"difficulty":"intermediate","description":"Qualify a deal using MEDDPICC framework","prompt":"Help me qualify this deal using MEDDPICC.\n\nDeal context:\n- Company: [PROSPECT]\n- Opportunity: [WHAT THEY'RE BUYING]\n- Deal size: [VALUE]\n- Stage: [CURRENT STAGE]\n\nFor each letter, tell me:\n1. What I know\n2. What I need to find out\n3. Questions to ask\n4. Red flags to watch for\n\nM - Metrics: [WHAT BUSINESS OUTCOMES DO THEY EXPECT?]\nE - Economic Buyer: [WHO HAS BUDGET AUTHORITY?]\nD - Decision Criteria: [HOW WILL THEY EVALUATE?]\nD - Decision Process: [WHAT ARE THE STEPS TO PURCHASE?]\nP - Paper Process: [LEGAL/PROCUREMENT REQUIREMENTS?]\nI - Identify Pain: [WHAT'S THE COMPELLING PROBLEM?]\nC - Champion: [WHO'S YOUR INTERNAL ADVOCATE?]\nC - Competition: [WHO ELSE ARE THEY EVALUATING?]\n\nOutput a MEDDPICC scorecard with gaps highlighted.","group":"meddpicc"},{"id":"meddpicc-champion-test","title":"Champion Validation Test","category":"meddpicc","tags":["champion","validation","meddpicc"],"difficulty":"advanced","description":"Test if your champion is a real champion","prompt":"Help me validate if [CONTACT NAME] is a true champion.\n\nContext:\n- Their title: [TITLE]\n- What they've done: [ACTIONS THEY'VE TAKEN]\n- What they've said: [COMMITMENTS THEY'VE MADE]\n- Deal stage: [WHERE WE ARE]\n\nChampion criteria (they must have all 3):\n1. POWER: Can they influence the decision?\n2. ACCESS: Can they get you to the economic buyer?\n3. WILL: Are they actively selling for you internally?\n\nTest questions:\n- Has the champion given you information you couldn't get otherwise?\n- Has the champion coached you on how to win?\n- Has the champion taken personal risk by advocating?\n- Has the champion arranged access to power?\n- Would the champion meet you outside of work hours?\n\nAssess this champion and tell me what to do next.","group":"meddpicc"},{"id":"media-cold-email-1","title":"Media Executive Cold Email","category":"media","subcategory":"outreach","tags":["cold-email","media","entertainment"],"difficulty":"intermediate","description":"Cold email for media and entertainment companies","prompt":"Write a cold email to a media or entertainment executive.\n\nContext:\n- Recipient: [NAME, TITLE]\n- Company type: [STREAMING / BROADCAST / PUBLISHER / AGENCY / STUDIO]\n- Signal: [NEW SHOW / PLATFORM LAUNCH / ADVERTISER PRESSURE]\n- My solution: [WHAT YOU SELL]\n- Content/audience impact: [HOW YOU HELP]\n\nMedia Email Rules:\n- Understand their business model (subscription, ad-supported, hybrid)\n- Reference audience engagement and content performance\n- Speak to their competitive landscape\n- Be aware of content windows and release cycles\n- Mention relevant integrations (CMS, ad tech, analytics)\n- Reference similar media companies\n\nMedia buyers care about: audience, engagement, content ROI, advertiser value.","group":"media"},{"id":"media-discovery-1","title":"Media Discovery Questions","category":"media","subcategory":"discovery","tags":["discovery","media","content"],"difficulty":"intermediate","description":"Discovery for media and entertainment sales","prompt":"Generate discovery questions for a media prospect.\n\nContext:\n- Prospect: [NAME, TITLE at COMPANY]\n- Media type: [STREAMING / BROADCAST / DIGITAL / PRINT]\n- My product: [WHAT YOU SELL]\n- Known challenge: [ENGAGEMENT / MONETIZATION / EFFICIENCY]\n\nMedia discovery categories:\n1. Business model (subscription, ads, hybrid)\n2. Content strategy and priorities\n3. Audience and engagement metrics\n4. Technology stack (CMS, distribution, analytics)\n5. Advertiser/monetization challenges\n6. Competitive differentiation\n7. Decision process (content vs. tech vs. business)\n8. Budget and investment priorities\n\nMedia is fast-moving - understand their content calendar and priorities.","group":"media"},{"id":"media-objection-1","title":"Handle \"Content is Our Priority, Not Tech\"","category":"media","subcategory":"objections","tags":["objection","content","technology"],"difficulty":"advanced","description":"Connect technology to content outcomes","prompt":"Help me respond to: \"We're focused on content right now, not technology investments.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their company: [MEDIA TYPE]\n- How we impact content: [CONNECTION TO CONTENT OUTCOMES]\n\nContent is king in media - but tech enables it. Help me:\n1. Validate content as the priority (it should be)\n2. Connect my solution to content outcomes\n3. Show how tech improves content performance\n4. Reference content companies that use us successfully\n5. Position as enabling their content strategy\n6. Find the technology champion who sees the connection\n\nNever compete with content - show how you serve it.","group":"media"},{"id":"media-proposal-1","title":"Media Technology Proposal","category":"media","subcategory":"proposals","tags":["proposal","media","technology"],"difficulty":"advanced","description":"Build a case for media technology investment","prompt":"Write a proposal for a media technology investment.\n\nContext:\n- Company: [MEDIA COMPANY NAME]\n- Business model: [HOW THEY MAKE MONEY]\n- Challenge: [WHAT THEY'RE SOLVING]\n- My solution: [WHAT YOU SELL]\n- Investment: [YOUR PRICE]\n- Expected outcomes: [METRICS - ENGAGEMENT, REVENUE, EFFICIENCY]\n\nMedia proposals need:\n1. Clear connection to content/audience outcomes\n2. Engagement and performance metrics\n3. Revenue impact (subs, ads, or both)\n4. Integration with existing workflow\n5. Time-to-value (media moves fast)\n6. Reference media companies\n7. Flexibility for evolving needs\n\nMedia buyers think in content cycles - show quick wins.","group":"media"},{"id":"media-follow-up-1","title":"Post-Upfronts Follow-Up","category":"media","subcategory":"follow-up","tags":["follow-up","upfronts","advertising"],"difficulty":"beginner","description":"Re-engage after upfronts or ad sales season","prompt":"Write a follow-up email after upfronts/ad sales season.\n\nContext:\n- Company: [MEDIA COMPANY]\n- Contact: [NAME, TITLE]\n- Their upfronts results: [IF KNOWN]\n- Our previous discussion: [CONTEXT]\n- My solution: [WHAT YOU SELL]\n\nPost-upfronts follow-up should:\n1. Acknowledge the intensity of upfronts season\n2. Reference their ad sales performance if public\n3. Connect to advertiser value proposition\n4. Propose planning for next cycle\n5. Identify opportunities to improve performance\n\nMedia has seasonal intensity - time your outreach appropriately.","group":"media"},{"id":"wf-negotiation-prep","title":"Negotiation Preparation Checklist","category":"negotiation","tags":["negotiation","preparation","close"],"difficulty":"advanced","description":"Prepare for a deal negotiation","prompt":"Help me prepare for a negotiation on this deal.\n\nDeal context:\n- Company: [PROSPECT]\n- Deal size: [VALUE]\n- Competition: [WHO ELSE]\n- Champion: [YOUR ALLY]\n- Economic buyer: [DECISION MAKER]\n- Their timeline: [URGENCY]\n- What they've pushed back on: [OBJECTIONS]\n\nPreparation needed:\n1. BATNA analysis (theirs and ours)\n2. Zone of possible agreement (ZOPA)\n3. Our walk-away point\n4. Concessions we can offer\n5. What we want in return for each concession\n6. Anchoring strategy\n7. Objection responses\n\nOutput a negotiation prep sheet I can use in the meeting.","group":"negotiation"},{"id":"wf-procurement-nav","title":"Procurement Navigation Guide","category":"negotiation","tags":["procurement","legal","redlines"],"difficulty":"advanced","description":"Navigate procurement and legal review","prompt":"Help me navigate procurement/legal review on this deal.\n\nContext:\n- Company: [PROSPECT]\n- Deal size: [VALUE]\n- Their procurement process: [WHAT YOU KNOW]\n- Contract redlines: [ISSUES THEY RAISED]\n- Timeline pressure: [WHEN THEY NEED TO CLOSE]\n- Our flexibility: [WHAT WE CAN/CAN'T CHANGE]\n\nHelp me with:\n1. Common procurement tactics and how to handle\n2. Response to their redlines\n3. When to escalate vs. concede\n4. How to maintain deal momentum\n5. Language for \"this is standard\" pushback\n6. Mutual value trade-offs\n\nGenerate a procurement navigation plan with specific responses.","group":"negotiation"},{"id":"wf-discount-response","title":"Discount Request Response","category":"negotiation","tags":["discount","pricing","negotiation"],"difficulty":"intermediate","description":"Respond to discount requests strategically","prompt":"Help me respond to this discount request.\n\nContext:\n- Our price: [LIST PRICE]\n- Their ask: [WHAT THEY WANT - % OFF OR SPECIFIC NUMBER]\n- Deal size: [TOTAL VALUE]\n- Our authority: [WHAT I CAN OFFER]\n- Their leverage: [WHY THEY THINK THEY DESERVE IT]\n- Our leverage: [WHY THEY NEED US]\n\nGenerate responses for different scenarios:\n1. Hard no (we don't discount)\n2. Trade for something (what we want in return)\n3. Structure differently (annual vs. monthly, longer term)\n4. Remove scope (reduce what they get)\n5. Delay discount (first year full, then discount)\n6. Value-add instead (give more, not cheaper)\n\nFor each approach:\n- Script for how to say it\n- What to ask for in return\n- How to frame it as a win for them\n- When to use this approach vs. others","group":"negotiation"},{"id":"wf-closing-techniques","title":"Closing Technique Scripts","category":"negotiation","tags":["closing","techniques","scripts"],"difficulty":"advanced","description":"Scripts for different closing techniques","prompt":"Generate closing technique scripts for this deal.\n\nContext:\n- Deal: [DESCRIBE THE OPPORTUNITY]\n- Stage: [WHERE WE ARE]\n- Sticking points: [WHAT'S HOLDING THEM BACK]\n- Timeline: [WHEN THEY NEED TO DECIDE]\n\nGenerate scripts for these closes:\n\n1. Summary Close\n   \"Based on everything we discussed...\"\n\n2. Assumptive Close\n   Assume the sale, discuss implementation\n\n3. Timeline Close\n   Work backwards from their go-live\n\n4. Options Close\n   Give them two ways to say yes\n\n5. Value Summary Close\n   Recap ROI before asking\n\n6. Scarcity Close\n   Pricing valid until, limited slots, etc.\n\n7. Trial Close\n   \"If we could... would you...\"\n\n8. Direct Ask\n   Simply ask for the business\n\nFor each technique:\n- Exact words to use\n- When this works best\n- Warning signs not to use it\n- How to recover if they say no","group":"negotiation"},{"id":"wf-stakeholder-negotiation","title":"Multi-Stakeholder Negotiation","category":"negotiation","tags":["stakeholders","negotiation","complex-deals"],"difficulty":"advanced","description":"Navigate negotiations with multiple stakeholders","prompt":"Help me navigate a multi-stakeholder negotiation.\n\nContext:\n- Company: [PROSPECT]\n- Stakeholders involved:\n  * [NAME 1, TITLE]: [THEIR INTEREST]\n  * [NAME 2, TITLE]: [THEIR INTEREST]\n  * [NAME 3, TITLE]: [THEIR INTEREST]\n- Deal size: [VALUE]\n- Current issues: [WHAT EACH STAKEHOLDER WANTS]\n\nFor each stakeholder:\n1. What they care about (priorities)\n2. What they might block on\n3. How to align your solution to their needs\n4. Language that resonates with them\n\nThen create:\n- Meeting strategy (who to meet, in what order)\n- How to create consensus\n- How to handle conflicting stakeholder needs\n- Escalation path if stuck\n- Coalition building strategy","group":"negotiation"},{"id":"wf-contract-redline-responses","title":"Contract Redline Responses","category":"negotiation","tags":["contract","legal","redlines"],"difficulty":"advanced","description":"Respond to common contract redlines","prompt":"Help me respond to these contract redlines.\n\nContext:\n- Deal size: [VALUE]\n- Prospect company: [NAME AND SIZE]\n- Our standard flexibility: [WHAT WE CAN TYPICALLY ADJUST]\n\nGenerate responses for common redlines:\n\n1. Unlimited liability ask\n2. Indemnification expansion\n3. Termination for convenience\n4. SLA with financial penalties\n5. Data deletion on termination\n6. Audit rights\n7. Most favored nation pricing\n8. Auto-renewal removal\n9. Cap on price increases\n10. Escrow requirements\n\nFor each redline:\n- Why they're asking (their concern)\n- Our position (what's reasonable)\n- Counter-proposal language\n- When to escalate vs. concede\n- Trade we could ask for in exchange","group":"negotiation"},{"id":"wf-multi-channel-sequence","title":"Multi-Channel Sequence","category":"outreach","tags":["sequence","multi-channel","cadence"],"difficulty":"intermediate","description":"Build a sequence across email, phone, and LinkedIn","prompt":"Create a multi-channel outreach sequence.\n\nContext:\n- Target persona: [TITLE at COMPANY TYPE]\n- My product: [WHAT YOU SELL]\n- Key pain point: [MAIN PROBLEM YOU SOLVE]\n- Best case study: [PROOF POINT]\n- Sequence length: [2-3 WEEKS]\n\nChannels to use:\n- Email (primary)\n- LinkedIn (connection + messages)\n- Phone (calls + voicemails)\n\nCreate a 12-touch sequence that:\n1. Starts with email (low friction)\n2. Adds LinkedIn on Day 2\n3. Introduces phone on Day 4\n4. Varies the angle each week\n5. Ends with a clear breakup\n\nFor each touch:\n- Channel and timing\n- Subject/hook\n- Key message\n- CTA","group":"outreach"},{"id":"wf-personalization-framework","title":"Email Personalization at Scale","category":"outreach","tags":["personalization","email","scale"],"difficulty":"intermediate","description":"Framework for personalizing outreach at scale","prompt":"Help me personalize outreach at scale.\n\nContext:\n- Volume goal: [EMAILS PER DAY/WEEK]\n- Team size: [NUMBER OF SDRs]\n- Current personalization: [WHAT YOU DO TODAY]\n- Data available: [WHAT YOU KNOW ABOUT PROSPECTS]\n\nCreate a tiered personalization framework:\n1. Tier 1 (Top accounts): Full custom research\n2. Tier 2 (Good fit): Industry/role customization\n3. Tier 3 (Volume): Segment-based variables\n\nFor each tier:\n- Time investment per email\n- Personalization elements to include\n- Templates and snippets\n- Quality checks\n\nGoal: Maximum relevance per minute invested.","group":"outreach"},{"id":"wf-subject-line-test","title":"Email Subject Line Generator","category":"outreach","tags":["email","subject-line","testing"],"difficulty":"beginner","description":"Generate and test email subject lines","prompt":"Generate email subject lines for this campaign.\n\nContext:\n- Target persona: [TITLE]\n- Industry: [INDUSTRY]\n- Pain point: [WHAT YOU SOLVE]\n- Tone: [PROFESSIONAL / CASUAL / DIRECT]\n\nGenerate 10 subject lines in these styles:\n1. Curiosity gap (opens a loop)\n2. Benefit-driven (what they get)\n3. Pain-driven (what they avoid)\n4. Question format (engages them)\n5. Personalized (uses their name/company)\n6. Number/stat (specific and concrete)\n7. Social proof (reference customers)\n8. Urgency (time-sensitive)\n9. Direct ask (no games)\n10. Pattern interrupt (unexpected)\n\nFor each subject line:\n- Why it might work\n- When to use it\n- A/B test suggestion","group":"outreach"},{"id":"wf-follow-up-templates","title":"Follow-Up Email Templates","category":"outreach","tags":["follow-up","templates","email"],"difficulty":"beginner","description":"Templates for different follow-up scenarios","prompt":"Create follow-up email templates for these scenarios.\n\nContext:\n- My product: [WHAT YOU SELL]\n- My value prop: [KEY BENEFIT]\n\nGenerate templates for:\n1. After no response to first email (Day 3)\n2. After meeting request ignored (Day 5)\n3. After they opened but didn't reply (Day 7)\n4. After they clicked a link (same day)\n5. After voicemail left (next day)\n6. After LinkedIn connection (Day 2)\n7. After referral introduction (Day 1)\n8. After trade show/event (Day 1)\n9. After their competitor news (same day)\n10. Final breakup email (Day 14)\n\nEach template should:\n- Be under 75 words\n- Have a clear subject line\n- Reference the previous touch\n- Add new value (not just \"following up\")\n- Have a specific CTA","group":"outreach"},{"id":"wf-cold-call-scripts","title":"Cold Call Script Library","category":"outreach","tags":["cold-call","phone","scripts"],"difficulty":"intermediate","description":"Scripts for different cold call scenarios","prompt":"Create cold call scripts for different scenarios.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Target title: [WHO I'M CALLING]\n- Average call goal: [BOOK MEETING / QUALIFY / INFO GATHER]\n\nGenerate scripts for:\n1. Gatekeeper navigation (getting past the EA)\n2. Direct connect opener (they picked up)\n3. Referral-based call (someone recommended)\n4. Follow-up to email call (they received your email)\n5. Event-triggered call (after their news/announcement)\n6. Competitor displacement call (they use competitor)\n\nEach script includes:\n- Opening line (first 10 seconds)\n- Value statement (next 20 seconds)\n- Interest gauge question\n- Common objection responses\n- Meeting ask\n- Voicemail version (if they don't answer)","group":"outreach"},{"id":"wf-linkedin-sequences","title":"LinkedIn Outreach Sequences","category":"outreach","tags":["linkedin","social-selling","sequence"],"difficulty":"intermediate","description":"Multi-touch LinkedIn message sequences","prompt":"Create LinkedIn outreach sequences.\n\nContext:\n- Target persona: [TITLE at COMPANY TYPE]\n- My product: [WHAT YOU SELL]\n- LinkedIn activity level: [ACTIVE / OCCASIONAL / RARE POSTER]\n- Mutual connections: [YES/NO]\n\nCreate 3 different sequences:\n\nSequence 1: Connection + Message (for active LinkedIn users)\n- Connection request\n- Day 1 message\n- Day 3 follow-up\n- Day 7 value add\n\nSequence 2: Content-First (for thought leader types)\n- Engage with their content (comment strategy)\n- Connection request after engagement\n- Message referencing their content\n\nSequence 3: Mutual Connection Path\n- Identify mutual connection angle\n- Soft introduction request\n- Direct follow-up\n\nFor each message:\n- Character count (must be under LinkedIn limits)\n- Why it works\n- Common responses and how to handle","group":"outreach"},{"id":"wf-objection-response-bank","title":"Outreach Objection Response Bank","category":"outreach","tags":["objections","responses","outreach"],"difficulty":"intermediate","description":"Responses to common outreach objections","prompt":"Create an objection response bank for outreach.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Price range: [BALLPARK]\n- Main competitor: [PRIMARY COMPETITOR]\n\nGenerate responses for these common objections:\n\n1. \"Not interested\"\n2. \"Send me some info\"\n3. \"We already have a solution\"\n4. \"No budget\"\n5. \"Call me next quarter\"\n6. \"How did you get my info?\"\n7. \"I'm not the right person\"\n8. \"We're too small/big for this\"\n9. \"Just email me\"\n10. \"I don't take cold calls\"\n\nFor each objection:\n- Phone response (real-time)\n- Email response (written)\n- The psychology behind their objection\n- Red flag that means stop vs. just pushback","group":"outreach"},{"id":"proserv-cold-email-1","title":"Partner-Level Cold Email","category":"professional-services","subcategory":"outreach","tags":["cold-email","partner","consulting"],"difficulty":"intermediate","description":"Cold email for reaching partners at consulting/law/accounting firms","prompt":"Write a cold email to a partner at a professional services firm.\n\nContext:\n- Recipient: [NAME, TITLE at FIRM]\n- Firm type: [CONSULTING / LAW / ACCOUNTING / ARCHITECTURE]\n- Firm size: [TIER - Big 4, Am Law 100, Regional, Boutique]\n- Signal: [NEW PRACTICE AREA / GROWTH / EFFICIENCY INITIATIVE]\n- My solution: [WHAT YOU SELL]\n- Utilization/efficiency impact: [HOW YOU HELP]\n\nProfessional Services Email Rules:\n- Respect the partnership structure\n- Speak to utilization, realization, leverage\n- Reference peer firms if possible\n- Understand billable hour economics\n- Be concise (partners bill by the minute mentally)\n- Appeal to competitive differentiation\n\nPartners care about: client service, utilization, talent retention, firm growth.","group":"professionalServices"},{"id":"proserv-discovery-1","title":"Professional Services Discovery","category":"professional-services","subcategory":"discovery","tags":["discovery","utilization","partners"],"difficulty":"intermediate","description":"Discovery questions for consulting/law/accounting","prompt":"Generate discovery questions for a professional services firm.\n\nContext:\n- Prospect: [NAME, TITLE at FIRM]\n- Firm type: [CONSULTING / LAW / ACCOUNTING]\n- My product: [WHAT YOU SELL]\n- Known initiative: [WHAT THEY'RE WORKING ON]\n\nProfessional services discovery categories:\n1. Practice economics (utilization, realization, leverage ratios)\n2. Current tools/processes (what they use today)\n3. Pain points (efficiency, knowledge management, collaboration)\n4. Decision process (partnership approval, practice vs. firm-wide)\n5. Implementation reality (partner adoption, change management)\n6. Client impact (how this affects client service)\n7. Competitive landscape (what other firms are doing)\n\nRemember: Every hour of implementation is an hour not billed to a client.","group":"professionalServices"},{"id":"proserv-objection-1","title":"Handle \"Partners Won't Adopt It\"","category":"professional-services","subcategory":"objections","tags":["objection","adoption","change-management"],"difficulty":"advanced","description":"Address partner adoption concerns","prompt":"Help me respond to: \"We've tried tools like this before - partners won't use them.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their firm: [FIRM TYPE AND SIZE]\n- Past failures: [WHAT THEY'VE TRIED - if mentioned]\n- Our adoption approach: [HOW WE DRIVE ADOPTION]\n\nPartner adoption is the #1 challenge. Help me:\n1. Acknowledge the pattern (professional services is a graveyard of failed tools)\n2. Ask about what specifically failed before\n3. Explain how our approach differs\n4. Reference firms that succeeded with adoption\n5. Propose a pilot with willing partners first\n6. Discuss change management support we provide\n\nPartners are creatures of habit. Changing workflow is hard when you bill $1,000/hour.","group":"professionalServices"},{"id":"proserv-proposal-1","title":"Professional Services Business Case","category":"professional-services","subcategory":"proposals","tags":["proposal","partnership","business-case"],"difficulty":"advanced","description":"Business case for partnership approval","prompt":"Write a business case for partnership approval.\n\nContext:\n- Firm: [FIRM NAME]\n- Practice area: [IF SPECIFIC TO ONE PRACTICE]\n- Investment: [TOTAL COST]\n- Expected impact: [METRICS]\n- Champion: [PARTNER CHAMPIONING THIS]\n- Concerns raised: [OBJECTIONS FROM OTHER PARTNERS]\n\nPartnership proposals need:\n1. Utilization/efficiency ROI (in their metrics)\n2. Competitive positioning (what peer firms do)\n3. Client service impact\n4. Implementation approach (minimal disruption)\n5. Risk mitigation\n6. Phased rollout option\n7. Reference firms (similar size/type)\n8. Support and training included\n\nFormat for busy partners: Executive summary first, details as appendix.","group":"professionalServices"},{"id":"proserv-follow-up-1","title":"Partnership Meeting Follow-Up","category":"professional-services","subcategory":"follow-up","tags":["follow-up","partnership","decision"],"difficulty":"intermediate","description":"Follow up after presenting to partners","prompt":"Write a follow-up email after presenting to the partnership.\n\nContext:\n- Firm: [FIRM NAME]\n- Meeting type: [PRACTICE GROUP / PARTNERSHIP / COMMITTEE]\n- Outcome: [APPROVED / NEEDS MORE INFO / TABLED]\n- Questions raised: [KEY CONCERNS]\n- Champion: [YOUR INTERNAL ALLY]\n- Timeline: [NEXT STEPS]\n\nFollow-up should:\n1. Thank them for the time (partners' time is expensive)\n2. Summarize the key points discussed\n3. Address specific questions raised\n4. Provide any requested documentation\n5. Confirm next steps and who owns what\n6. Offer to present to individual skeptics\n\nPartnership decisions can take time - maintain patience and provide support to your champion.","group":"professionalServices"},{"id":"wf-icp-definition","title":"ICP Definition Framework","category":"prospecting","tags":["icp","targeting","segmentation"],"difficulty":"intermediate","description":"Define your ideal customer profile","prompt":"Help me define my Ideal Customer Profile (ICP).\n\nContext:\n- My product: [WHAT YOU SELL]\n- Best customers today: [DESCRIBE YOUR TOP 3-5]\n- Worst customers: [WHO CHURNED OR WAS A BAD FIT]\n- Deal size target: [ACV RANGE]\n- Sales cycle goal: [LENGTH]\n\nICP needs to define:\n1. Firmographics (size, industry, geography, growth stage)\n2. Technographics (tech stack, tools they use)\n3. Buying triggers (events that create need)\n4. Stakeholders (titles involved in buying)\n5. Pain indicators (signals they have the problem)\n6. Disqualifiers (red flags that mean bad fit)\n\nOutput a one-page ICP doc I can share with my team.","group":"prospecting"},{"id":"wf-account-research","title":"Account Research Template","category":"prospecting","tags":["research","account","intel"],"difficulty":"beginner","description":"Research a target account before outreach","prompt":"Research [COMPANY NAME] and give me a briefing for sales outreach.\n\nI need:\n1. Company overview (what they do, size, funding, growth)\n2. Recent news (last 6 months)\n3. Key executives (names, backgrounds, LinkedIn)\n4. Tech stack (what tools they likely use)\n5. Potential pain points (based on their stage/industry)\n6. Competitors they might use\n7. Trigger events (why now might be good timing)\n8. Conversation starters (hooks for outreach)\n\nMy product: [WHAT YOU SELL]\nTarget persona: [TITLE I'M REACHING]\n\nFormat as a one-pager I can reference before calling.","group":"prospecting"},{"id":"wf-lead-scoring","title":"Lead Scoring Model","category":"prospecting","tags":["scoring","prioritization","qualification"],"difficulty":"advanced","description":"Build a lead scoring model for prioritization","prompt":"Help me build a lead scoring model.\n\nContext:\n- Lead sources: [INBOUND / OUTBOUND / EVENTS / etc.]\n- Current volume: [LEADS PER MONTH]\n- Conversion rate: [MQL TO SQL / SQL TO OPP]\n- Sales team capacity: [REPS AND BANDWIDTH]\n- What makes a good lead: [YOUR BEST LEADS]\n\nScoring model needs:\n1. Demographic score (firmographic fit)\n2. Behavioral score (engagement and intent signals)\n3. Score thresholds (hot/warm/cold or MQL/SQL)\n4. Routing rules (who gets which leads)\n5. Score decay (how scores change over time)\n\nOutput:\n- Scoring rubric with points per criteria\n- Threshold definitions\n- Routing logic\n- Process for score calibration","group":"prospecting"},{"id":"re-cold-email-1","title":"Commercial Real Estate Cold Email","category":"real-estate","subcategory":"outreach","tags":["cold-email","cre","brokerage"],"difficulty":"intermediate","description":"Cold email for commercial real estate professionals","prompt":"Write a cold email to a commercial real estate professional.\n\nContext:\n- Recipient: [NAME, TITLE at FIRM]\n- CRE role: [BROKER / OWNER / DEVELOPER / PROPERTY MANAGER]\n- Asset class: [OFFICE / RETAIL / INDUSTRIAL / MULTIFAMILY]\n- Market: [GEOGRAPHIC MARKET]\n- Signal: [RECENT DEAL / NEW LISTING / MARKET TREND]\n- My solution: [WHAT YOU SELL]\n- Deal impact: [HOW YOU HELP THEM WIN/CLOSE]\n\nReal Estate Email Rules:\n- Reference specific deals or properties if possible\n- Speak to their commission/fee structure\n- Understand the competitive brokerage landscape\n- Respect relationship-based nature of the business\n- Timing matters - be aware of deal cycles\n- Offer to help them win their next listing or close their current deal\n\nReal estate is relationship-driven. Position as a tool to strengthen their relationships.","group":"realEstate"},{"id":"re-discovery-1","title":"Real Estate Discovery Questions","category":"real-estate","subcategory":"discovery","tags":["discovery","proptech","deals"],"difficulty":"intermediate","description":"Discovery for real estate tech sales","prompt":"Generate discovery questions for a real estate prospect.\n\nContext:\n- Prospect: [NAME, TITLE at FIRM/COMPANY]\n- CRE segment: [BROKERAGE / OWNERSHIP / DEVELOPMENT / MANAGEMENT]\n- My product: [WHAT YOU SELL]\n- Their likely pain: [DEAL FLOW / EFFICIENCY / DATA]\n\nReal estate discovery categories:\n1. Current deal flow (volume, average deal size, close rate)\n2. Tech stack (CRM, marketing tools, data sources)\n3. Team structure and workflow\n4. Competitive landscape (who they compete against)\n5. Decision process (individual broker vs. firm-wide)\n6. Budget (tech budget often limited)\n7. Success metrics (deals closed, volume, commissions)\n\nReal estate is fragmented. Understand if you're selling to individuals or firms.","group":"realEstate"},{"id":"re-objection-1","title":"Handle \"I Have My Own System\"","category":"real-estate","subcategory":"objections","tags":["objection","workflow","individual"],"difficulty":"advanced","description":"When brokers have personal workflows","prompt":"Help me respond to: \"I've got my own system that works for me.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Their role: [BROKER / AGENT / MANAGER]\n- Their \"system\": [WHAT THEY LIKELY USE - spreadsheets, notes, etc.]\n- Our differentiation: [WHAT WE DO BETTER]\n\nThis is common with independent brokers. Help me:\n1. Respect their success with current system\n2. Ask about specific friction points (not general)\n3. Understand their actual workflow\n4. Find the wedge (scaling, team growth, efficiency)\n5. Position as enhancing, not replacing their system\n6. Offer a trial tied to their next active deal\n\nTop brokers are protective of their process. Show value without threatening their identity.","group":"realEstate"},{"id":"re-proposal-1","title":"Brokerage Firm Proposal","category":"real-estate","subcategory":"proposals","tags":["proposal","brokerage","firm-wide"],"difficulty":"advanced","description":"Proposal for firm-wide real estate technology","prompt":"Write a proposal for a real estate brokerage firm.\n\nContext:\n- Firm: [BROKERAGE NAME]\n- Size: [NUMBER OF BROKERS/AGENTS]\n- Markets: [GEOGRAPHIC COVERAGE]\n- Asset focus: [OFFICE / RETAIL / INDUSTRIAL / etc.]\n- Champion: [YOUR INTERNAL ALLY]\n- Investment: [YOUR PRICE]\n- Key pain: [WHAT THEY WANT TO SOLVE]\n\nBrokerage proposals need:\n1. Individual broker value prop (what's in it for each agent)\n2. Firm-level value (recruiting, retention, brand)\n3. Adoption plan (brokers are independent)\n4. Integration with existing tools\n5. Support and training\n6. Reference firms (similar size/market)\n7. Flexible pricing (per broker vs. firm)\n\nThe challenge: Firm leadership buys, but brokers decide to use it.","group":"realEstate"},{"id":"re-follow-up-1","title":"Post-Deal Follow-Up","category":"real-estate","subcategory":"follow-up","tags":["follow-up","deal","relationship"],"difficulty":"beginner","description":"Follow up after they close a deal","prompt":"Write a follow-up email after a prospect closes a deal.\n\nContext:\n- Contact: [NAME, TITLE at FIRM]\n- Deal they closed: [PROPERTY / TRANSACTION]\n- Our relationship: [PROSPECT / CUSTOMER / CHURNED]\n- My solution: [WHAT YOU SELL]\n- How we could have helped: [VALUE WE BRING]\n\nPost-deal follow-up should:\n1. Congratulate them on the deal (be specific about the property)\n2. Don't make it about you (celebrate their win)\n3. Gentle plant for next deal\n4. Offer value (market data, insights, etc.)\n5. Keep door open\n\nReal estate is cyclical. Stay visible for their next deal.","group":"realEstate"},{"id":"revops-territory-plan","title":"Territory Planning Framework","category":"revops","tags":["territory","planning","segmentation"],"difficulty":"advanced","description":"Design equitable and effective sales territories","prompt":"Help me design sales territories for my team.\n\nContext:\n- Total addressable accounts: [NUMBER]\n- Number of reps: [NUMBER]\n- Current territory structure: [GEOGRAPHIC / VERTICAL / NAMED / ROUND ROBIN]\n- Average deal size: [ACV]\n- Sales cycle length: [MONTHS]\n- Historical performance data: [WHAT YOU HAVE]\n\nTerritory design needs to balance:\n1. Equal opportunity (similar total TAM per rep)\n2. Travel efficiency (if field sales)\n3. Specialization benefits (vertical expertise)\n4. Account relationships (don't disrupt existing)\n5. Growth potential (not just current revenue)\n\nOutput:\n- Recommended territory model\n- Criteria for account assignment\n- Transition plan for existing relationships\n- Quota implications\n- Metrics to track territory health","group":"revops"},{"id":"revops-forecast-model","title":"Forecast Accuracy Analysis","category":"revops","tags":["forecast","accuracy","metrics"],"difficulty":"advanced","description":"Analyze and improve forecast accuracy","prompt":"Help me analyze and improve our sales forecast accuracy.\n\nCurrent state:\n- Forecast method: [BOTTOM-UP / TOP-DOWN / WEIGHTED PIPELINE]\n- Historical accuracy: [LAST 4 QUARTERS]\n- Common misses: [OVER-FORECAST / UNDER-FORECAST / TIMING]\n- Pipeline stages: [LIST YOUR STAGES]\n- Stage conversion rates: [IF KNOWN]\n\nAnalysis needed:\n1. Identify where forecast breaks down (stage, rep, segment)\n2. Calculate optimal stage weights\n3. Recommend forecast categories (commit/best case/upside)\n4. Design inspection criteria per category\n5. Build manager review cadence\n\nOutput a forecast methodology doc with:\n- Stage definitions with exit criteria\n- Weighting by stage and probability\n- Commit criteria checklist\n- Forecast hygiene scorecard","group":"revops"},{"id":"revops-process-audit","title":"Sales Process Audit","category":"revops","tags":["process","audit","efficiency"],"difficulty":"intermediate","description":"Audit your sales process for leaks and inefficiencies","prompt":"Help me audit our sales process for inefficiencies.\n\nCurrent process:\n- Stages: [LIST YOUR PIPELINE STAGES]\n- Tools: [CRM, ENGAGEMENT PLATFORM, etc.]\n- Team size: [REPS, MANAGERS]\n- Average sales cycle: [DAYS]\n- Win rate: [%]\n\nAudit areas:\n1. Stage conversion rates (where do deals die?)\n2. Time in stage (where do deals stall?)\n3. Activity metrics (are reps doing the right things?)\n4. Data quality (what's missing or wrong?)\n5. Tool utilization (what's not being used?)\n6. Handoff points (SDR to AE, AE to CS)\n\nOutput:\n- Leakage report by stage\n- Recommended process changes\n- Automation opportunities\n- Training needs identified\n- Quick wins vs. longer-term fixes","group":"revops"},{"id":"revops-dashboard-design","title":"Sales Dashboard Design","category":"revops","tags":["dashboard","metrics","reporting"],"difficulty":"intermediate","description":"Design dashboards for reps, managers, and execs","prompt":"Help me design sales dashboards for different audiences.\n\nContext:\n- Sales motion: [INBOUND / OUTBOUND / HYBRID]\n- Team structure: [SDR → AE / FULL CYCLE / POD]\n- Key business metrics: [ARR / BOOKINGS / etc.]\n- Current reporting gaps: [WHAT'S MISSING]\n\nDesign dashboards for:\n1. Rep Dashboard (daily driver)\n2. Manager Dashboard (team health)\n3. Exec Dashboard (business health)\n\nFor each dashboard:\n- 5-7 key metrics\n- Why each metric matters\n- How to calculate it\n- Target/benchmark\n- Drill-down options\n\nKeep it focused - more metrics = less focus.","group":"revops"},{"id":"saas-cold-email-1","title":"Technical Founder Cold Email","category":"saas","subcategory":"outreach","tags":["cold-email","founder","technical"],"difficulty":"beginner","description":"Cold email for reaching technical founders at early-stage startups","prompt":"Write a cold email to [FOUNDER NAME], technical founder of [COMPANY].\n\nContext:\n- They recently [SIGNAL: launched on Product Hunt / raised seed funding / posted on HN]\n- Company stage: [STAGE: pre-seed / seed / Series A]\n- Their product: [WHAT THEY BUILD]\n- I help [TYPE OF COMPANIES] with [PROBLEM I SOLVE]\n\nTone: Technical peer, not salesy. Respect their time.\n\nRules:\n- Subject line: 5 words max, no clickbait\n- Opening: Reference the signal, show you did research\n- Body: One specific way you could help, tied to their stage\n- CTA: Low commitment (15-min call or async)\n- Total length: Under 100 words\n- No \"hope this finds you well\" or \"I'm reaching out because\"","group":"saas"},{"id":"saas-cold-email-2","title":"VP Engineering Cold Email","category":"saas","subcategory":"outreach","tags":["cold-email","engineering","growth-stage"],"difficulty":"intermediate","description":"Cold email targeting VP/Director of Engineering at growth-stage companies","prompt":"Write a cold email to [NAME], VP of Engineering at [COMPANY].\n\nContext:\n- Company size: [EMPLOYEE COUNT]\n- Their stack: [TECHNOLOGIES THEY USE]\n- Signal: [SIGNAL: hiring engineers / scaling infrastructure / tech debt mentions]\n- We help engineering teams with [PROBLEM]\n\nTone: Peer-to-peer, technical credibility matters.\n\nStructure:\n1. Hook: Reference something specific about their engineering challenges\n2. Problem: One sentence on the pain they likely feel\n3. Credibility: One proof point (customer result, not features)\n4. CTA: Specific and low-friction\n\nRules:\n- No buzzwords (leverage, synergy, cutting-edge)\n- Mention specific tech if relevant\n- Under 80 words","group":"saas"},{"id":"saas-discovery-1","title":"Technical Discovery Questions","category":"saas","subcategory":"discovery","tags":["discovery","technical","questions"],"difficulty":"intermediate","description":"Discovery questions for technical buyers evaluating your SaaS product","prompt":"Generate discovery questions for a technical buyer evaluating [YOUR PRODUCT TYPE].\n\nContext:\n- Buyer role: [TITLE: VP Eng / CTO / Tech Lead]\n- Company stage: [STAGE]\n- Known pain points: [WHAT YOU KNOW]\n- Competitors they might be evaluating: [COMPETITORS]\n\nQuestion categories needed:\n1. Current state (how they do it today)\n2. Pain quantification (time/cost/risk of current approach)\n3. Decision process (who else is involved, timeline)\n4. Technical requirements (integration, security, scale)\n5. Success criteria (how they'll measure if it worked)\n\nFormat: 3 questions per category, ordered from easy to probing.\nInclude follow-up prompts for each question.","group":"saas"},{"id":"saas-objection-1","title":"Handle \"We Built It In-House\"","category":"saas","subcategory":"objections","tags":["objection","build-vs-buy","technical"],"difficulty":"advanced","description":"Response framework for the build vs buy objection","prompt":"Help me respond to this objection from a technical buyer:\n\n\"We've already built something in-house that does this.\"\n\nContext:\n- My product: [YOUR PRODUCT]\n- Their company size: [SIZE]\n- Their likely in-house solution: [WHAT YOU THINK THEY BUILT]\n- My key differentiator: [WHAT MAKES YOU BETTER]\n\nResponse framework needed:\n1. Acknowledge their investment (don't dismiss it)\n2. Curious questions to understand their solution's scope\n3. Subtle wedge questions (maintenance burden, opportunity cost, feature gaps)\n4. Bridge to your value (only if there's a real gap)\n\nTone: Respect their engineering effort. Never trash their work.\nGoal: Understand if there's a real opportunity, not to \"win\" the objection.","group":"saas"},{"id":"saas-proposal-1","title":"Executive Summary for SaaS Proposal","category":"saas","subcategory":"proposals","tags":["proposal","executive-summary","enterprise"],"difficulty":"advanced","description":"Write a compelling executive summary for a SaaS proposal","prompt":"Write an executive summary for a SaaS proposal.\n\nDeal context:\n- Prospect: [COMPANY NAME]\n- Champion: [NAME, TITLE]\n- Economic buyer: [NAME, TITLE]\n- Problem they're solving: [PROBLEM]\n- Our solution: [YOUR PRODUCT]\n- Deal size: [ACV]\n- Competition: [WHO ELSE THEY'RE EVALUATING]\n\nKey wins from discovery:\n- [PAIN POINT 1 + QUANTIFIED IMPACT]\n- [PAIN POINT 2 + QUANTIFIED IMPACT]\n- [PAIN POINT 3 + QUANTIFIED IMPACT]\n\nSuccess metrics they mentioned:\n- [METRIC 1]\n- [METRIC 2]\n\nWrite a 200-word executive summary that:\n1. Opens with their goal, not your product\n2. Summarizes the problems you'll solve (in their words)\n3. Previews the ROI case\n4. Creates urgency without being pushy\n5. Ends with a clear next step","group":"saas"},{"id":"saas-cold-email-3","title":"Product Manager Cold Email","category":"saas","subcategory":"outreach","tags":["cold-email","product-manager","tools"],"difficulty":"beginner","description":"Cold email for product managers evaluating tools","prompt":"Write a cold email to [NAME], Product Manager at [COMPANY].\n\nContext:\n- They recently [SIGNAL: launched a new feature / posted about product challenges / hiring for PM role]\n- Product area: [THEIR PRODUCT AREA]\n- We help PMs with [YOUR VALUE PROP]\n- Team size: [THEIR TEAM SIZE]\n\nTone: Fellow product person, empathetic to PM struggles.\n\nStructure:\n1. Hook: Something specific about their product work\n2. Pain: One PM-specific challenge you solve\n3. Proof: Quick metric from similar PM\n4. CTA: \"See how [Similar Company] did it?\"\n\nRules:\n- Under 75 words\n- No feature lists\n- Speak their language (roadmap, velocity, stakeholders)","group":"saas"},{"id":"saas-cold-email-4","title":"CFO Budget Season Email","category":"saas","subcategory":"outreach","tags":["cold-email","cfo","budget","timing"],"difficulty":"intermediate","description":"Cold email timed for budget planning season","prompt":"Write a cold email to [NAME], CFO at [COMPANY] during budget planning season.\n\nContext:\n- Company revenue: [REVENUE RANGE]\n- Fiscal year end: [MONTH]\n- Signal: [SIGNAL: earnings call mention / LinkedIn post / job posting]\n- We help finance teams [YOUR VALUE PROP]\n- ROI we typically deliver: [ROI METRIC]\n\nTone: Financially literate, respect their time, data-driven.\n\nKey angles to consider:\n1. Budget planning = open to new line items\n2. Show clear ROI timeline\n3. Align with their fiscal planning cycle\n\nRules:\n- Lead with a financial insight, not product pitch\n- Include one specific number\n- CTA tied to their planning timeline","group":"saas"},{"id":"saas-cold-email-5","title":"Competitive Displacement Email","category":"saas","subcategory":"outreach","tags":["cold-email","competitive","displacement"],"difficulty":"advanced","description":"Cold email when prospect uses competitor","prompt":"Write a cold email to [NAME] at [COMPANY] who currently uses [COMPETITOR].\n\nContext:\n- Their current solution: [COMPETITOR NAME]\n- How long they've used it: [IF KNOWN]\n- Known pain points with competitor: [GAPS/ISSUES]\n- Our key differentiator: [YOUR ADVANTAGE]\n- Similar customer who switched: [REFERENCE CUSTOMER]\n\nTone: Respectful of their choice, not trash-talking competitor.\n\nStrategy:\n1. Acknowledge they have a solution (validates their decision)\n2. Plant a seed about one specific limitation\n3. Offer comparison value, not hard pitch\n4. Make it safe to explore options\n\nRules:\n- Never badmouth competitor directly\n- Focus on what they might be missing\n- Low-commitment CTA","group":"saas"},{"id":"saas-discovery-2","title":"Budget and Timeline Discovery","category":"saas","subcategory":"discovery","tags":["discovery","budget","timeline","qualification"],"difficulty":"intermediate","description":"Questions to qualify budget and buying timeline","prompt":"Generate discovery questions to qualify budget and timeline.\n\nContext:\n- Prospect company: [COMPANY]\n- Your ACV: [DEAL SIZE]\n- Typical sales cycle: [LENGTH]\n- Champion role: [THEIR TITLE]\n\nGenerate questions for:\n1. Budget discovery (without asking \"what's your budget?\")\n2. Decision timeline reality check\n3. Competing priorities that could delay\n4. Approval process and stakeholders\n5. Past purchase experiences (how they bought last tool)\n\nFormat each question with:\n- The question itself\n- Why you're asking (the intel you need)\n- Follow-up if they're vague\n- Red flag answers to watch for","group":"saas"},{"id":"saas-discovery-3","title":"Stakeholder Mapping Questions","category":"saas","subcategory":"discovery","tags":["discovery","stakeholders","buying-committee"],"difficulty":"advanced","description":"Questions to understand the buying committee","prompt":"Generate questions to map the buying committee.\n\nContext:\n- Deal size: [ACV]\n- Prospect: [COMPANY NAME]\n- Current contact: [NAME, TITLE]\n- Your product affects: [DEPARTMENTS/ROLES IMPACTED]\n\nQuestion categories:\n1. Who else will be involved in this decision?\n2. Who needs to approve budget at this level?\n3. Who might block this internally? (IT, legal, procurement)\n4. Who will be the day-to-day users?\n5. Who has failed to buy something like this before? Why?\n\nFor each answer, provide:\n- Natural way to ask without seeming interrogative\n- How to position as helping them navigate internally\n- When in the conversation to ask this","group":"saas"},{"id":"saas-objection-2","title":"Handle \"No Budget Right Now\"","category":"saas","subcategory":"objections","tags":["objection","budget","timing"],"difficulty":"intermediate","description":"Response when prospect has budget constraints","prompt":"Help me respond to: \"We don't have budget for this right now.\"\n\nContext:\n- My product: [YOUR PRODUCT]\n- Deal size: [ACV]\n- Their company stage: [STAGE/SIZE]\n- Value I provide: [KEY BENEFIT]\n- Their fiscal year: [IF KNOWN]\n\nExplore these angles:\n1. Is this a priority problem? (If so, budget finds a way)\n2. Reframe as cost of inaction (what's the cost of waiting?)\n3. Creative pricing options (if applicable)\n4. Plant seeds for next budget cycle\n5. Find smaller entry point\n\nProvide:\n- 3 diagnostic questions to understand the real blocker\n- 2 reframe responses\n- 1 graceful exit that keeps door open\n- Follow-up timing recommendation","group":"saas"},{"id":"saas-objection-3","title":"Handle \"Need to Think About It\"","category":"saas","subcategory":"objections","tags":["objection","stall","closing"],"difficulty":"advanced","description":"Response when prospect stalls with vague objection","prompt":"Help me respond to: \"Let me think about it and get back to you.\"\n\nContext:\n- Deal stage: [STAGE: post-demo / post-proposal / post-trial]\n- What we covered: [LAST INTERACTION SUMMARY]\n- Their apparent concerns: [IF ANY SURFACED]\n- Their timeline mentioned: [IF ANY]\n- Competition: [IF YOU KNOW]\n\nThis objection often masks:\n- Unspoken concern they didn't raise\n- Need to socialize internally\n- Evaluating competitor\n- Not a real priority\n- You haven't earned the next step\n\nProvide:\n- 3 ways to gently probe what's really happening\n- Questions to surface hidden objections\n- How to offer help without being pushy\n- Clear mutual action plan suggestion","group":"saas"},{"id":"saas-proposal-2","title":"ROI Business Case Section","category":"saas","subcategory":"proposals","tags":["proposal","roi","business-case"],"difficulty":"advanced","description":"Create the ROI section of a proposal","prompt":"Create the ROI/business case section for a SaaS proposal.\n\nDeal context:\n- Prospect: [COMPANY]\n- Annual deal value: [ACV]\n- Contract length: [MONTHS/YEARS]\n- Implementation cost: [IF ANY]\n\nValue drivers discovered:\n- Time savings: [HOURS/FTEs SAVED]\n- Revenue impact: [GROWTH/RETENTION IMPROVEMENT]\n- Risk reduction: [COMPLIANCE/SECURITY BENEFITS]\n- Cost reduction: [TOOLS CONSOLIDATED/COSTS AVOIDED]\n\nTheir current costs:\n- Current solution cost: [IF KNOWN]\n- Manual process cost: [TIME × SALARY]\n- Opportunity cost: [DEALS LOST/DELAYED]\n\nBuild a business case that shows:\n1. Year 1 ROI calculation\n2. 3-year TCO comparison\n3. Payback period\n4. Risk-adjusted projections\n5. Soft benefits (harder to quantify)\n\nFormat: Clear table + narrative explanation.","group":"saas"},{"id":"saas-follow-up-1","title":"Post-Demo Follow-Up Email","category":"saas","subcategory":"follow-up","tags":["follow-up","demo","next-steps"],"difficulty":"beginner","description":"Follow-up email after a product demo","prompt":"Write a follow-up email after a product demo.\n\nDemo context:\n- Attendees: [NAMES AND TITLES]\n- Key features shown: [FEATURES DEMOED]\n- Their biggest reactions: [WHAT EXCITED THEM]\n- Questions they asked: [KEY QUESTIONS]\n- Concerns raised: [OBJECTIONS/HESITATIONS]\n- Agreed next step: [WHAT YOU SAID YOU'D DO]\n\nStructure:\n1. Thank + personalized observation (not generic)\n2. Recap what resonated (in their words)\n3. Address any open questions\n4. Attach relevant resources\n5. Clear CTA with specific date/time\n\nRules:\n- Send within 2 hours of demo\n- Under 150 words\n- Include mutual action plan\n- Don't re-pitch—you already demoed","group":"saas"},{"id":"saas-follow-up-2","title":"Break-Up Email Sequence","category":"saas","subcategory":"follow-up","tags":["follow-up","break-up","gone-dark"],"difficulty":"intermediate","description":"Final follow-up when prospect goes dark","prompt":"Write a \"break-up\" email for a prospect who's gone dark.\n\nContext:\n- Last contact: [DATE]\n- Previous touchpoints: [# OF FOLLOW-UPS SENT]\n- Stage when they went dark: [STAGE]\n- Last topic discussed: [TOPIC]\n- Value they acknowledged: [WHAT THEY SAID THEY LIKED]\n\nWrite 3 versions:\n1. Soft break-up (assumes they're busy)\n2. Value-add break-up (shares useful resource)\n3. Direct break-up (asks for a no)\n\nFor each version include:\n- Subject line\n- Body (under 50 words)\n- The psychology behind why it works\n\nGoal: Get a response (even if it's no) or permission to follow up later.","group":"saas"},{"id":"sm-pipeline-review","title":"Pipeline Review Framework","category":"sales-manager","tags":["pipeline","coaching","forecast"],"difficulty":"intermediate","description":"Run an effective pipeline review with your team","prompt":"Create a pipeline review framework for my team.\n\nTeam context:\n- Team size: [NUMBER OF REPS]\n- Average deal size: [ACV]\n- Sales cycle: [LENGTH]\n- Current quarter: [Q# YYYY]\n- Quota attainment so far: [%]\n- Pipeline coverage: [X]x\n\nFor each deal reviewed, I want to assess:\n1. Is this deal real? (BANT/MEDDPICC check)\n2. Are we winning? (competitive position)\n3. What's the next step? (clear action)\n4. Is the close date accurate? (commit vs. upside)\n\nGenerate:\n- Questions to ask for each deal stage\n- Red flags to look for\n- How to categorize (commit/upside/push)\n- Coaching prompts for stuck deals\n- Format for a 30-minute team review","group":"salesManager"},{"id":"sm-rep-coaching","title":"Rep Coaching Session","category":"sales-manager","tags":["coaching","1:1","development"],"difficulty":"intermediate","description":"Structure a 1:1 coaching session with a rep","prompt":"Help me prepare for a coaching 1:1 with one of my reps.\n\nRep context:\n- Name: [REP NAME]\n- Tenure: [TIME ON TEAM]\n- Current performance: [% TO QUOTA]\n- Strength: [WHAT THEY'RE GOOD AT]\n- Development area: [WHERE THEY NEED HELP]\n- Recent deal: [DEAL TO DISCUSS - WON OR LOST]\n\nCreate a 1:1 agenda that:\n1. Opens with their wins (recognition)\n2. Reviews a specific deal (learning moment)\n3. Addresses the development area (skill building)\n4. Sets clear action items (accountability)\n5. Ends with their input (two-way dialogue)\n\nInclude:\n- Specific questions to ask\n- How to give feedback (situation-behavior-impact)\n- Role-play scenario for skill practice\n- Metrics to track improvement","group":"salesManager"},{"id":"sm-forecast-call","title":"Forecast Call Preparation","category":"sales-manager","tags":["forecast","leadership","reporting"],"difficulty":"advanced","description":"Prepare for your forecast call with leadership","prompt":"Help me prepare for my forecast call with leadership.\n\nCurrent state:\n- Quota: $[QUOTA]\n- Closed so far: $[CLOSED]\n- Pipeline: $[PIPELINE VALUE]\n- Days left in quarter: [DAYS]\n- Commit: $[COMMIT DEALS]\n- Upside: $[UPSIDE DEALS]\n\nDeals at risk:\n- [DEAL 1]: [RISK REASON]\n- [DEAL 2]: [RISK REASON]\n\nCreate:\n1. Executive summary (where we are, where we'll land)\n2. Commit vs. upside breakdown with confidence levels\n3. Risk mitigation plan for at-risk deals\n4. Upside scenarios (what could go right)\n5. Ask for leadership (what I need from them)\n6. Answers to likely questions they'll ask","group":"salesManager"},{"id":"sdr-cold-email-sequence","title":"Cold Email Sequence Builder","category":"sdr","tags":["cold-email","sequence","outbound"],"difficulty":"beginner","description":"Generate a 5-touch email sequence for outbound prospecting","prompt":"Create a 5-email sequence for cold outbound prospecting.\n\nContext:\n- My company: [YOUR COMPANY]\n- What we sell: [YOUR PRODUCT/SERVICE]\n- Target persona: [TITLE at COMPANY TYPE]\n- Key pain point we solve: [MAIN PAIN POINT]\n- Best customer result: [SPECIFIC OUTCOME/METRIC]\n\nSequence structure:\n1. Email 1 (Day 1): Hook with pain point or signal\n2. Email 2 (Day 3): Social proof / case study\n3. Email 3 (Day 7): Different angle / new value prop\n4. Email 4 (Day 10): Breakup tease\n5. Email 5 (Day 14): Actual breakup\n\nRules for each email:\n- Subject line: 5 words max\n- Body: Under 75 words\n- One clear CTA\n- No \"I hope this finds you well\"\n- Reference previous emails in follow-ups","group":"sdr"},{"id":"sdr-linkedin-connection","title":"LinkedIn Connection Request","category":"sdr","tags":["linkedin","connection","prospecting"],"difficulty":"beginner","description":"Write a connection request that gets accepted","prompt":"Write a LinkedIn connection request that gets accepted.\n\nTarget:\n- Name: [NAME]\n- Title: [TITLE]\n- Company: [COMPANY]\n- Something notable: [RECENT POST / COMPANY NEWS / MUTUAL CONNECTION]\n\nRules:\n- Under 300 characters (LinkedIn limit)\n- Reference something specific about them\n- No pitch in the connection request\n- Give a reason to connect\n- Be a human, not a sales robot\n\nGenerate 3 variations with different approaches.","group":"sdr"},{"id":"sdr-objection-voicemail","title":"Voicemail Script","category":"sdr","tags":["voicemail","cold-call","phone"],"difficulty":"intermediate","description":"Leave a voicemail that gets callbacks","prompt":"Write a voicemail script that gets callbacks.\n\nContext:\n- Prospect: [NAME, TITLE at COMPANY]\n- Why I'm calling: [TRIGGER/SIGNAL]\n- What I'm selling: [YOUR SOLUTION]\n- Key pain point: [THEIR LIKELY PAIN]\n\nVoicemail rules:\n- Under 30 seconds when spoken\n- Lead with something about THEM, not you\n- One specific reason to call back\n- Your phone number twice (beginning and end)\n- Create curiosity without being clickbaity\n\nAlso provide:\n1. A \"pattern interrupt\" version\n2. A \"referral\" version (if you have a mutual connection)","group":"sdr"},{"id":"sdr-meeting-confirmation","title":"Meeting Confirmation Email","category":"sdr","tags":["meeting","confirmation","no-show"],"difficulty":"beginner","description":"Confirm a booked meeting and reduce no-shows","prompt":"Write a meeting confirmation email that reduces no-shows.\n\nMeeting details:\n- Prospect: [NAME, TITLE at COMPANY]\n- Meeting time: [DATE/TIME]\n- Meeting type: [INTRO CALL / DISCOVERY / DEMO]\n- What was promised: [WHAT YOU SAID YOU'D COVER]\n- AE joining: [YES/NO - IF YES, THEIR NAME]\n\nEmail should:\n1. Confirm the time and add calendar context\n2. Set expectations for what you'll cover\n3. Ask a pre-meeting question to get them engaged\n4. Provide easy reschedule option (but make it slightly harder than confirming)\n5. Include your Calendly/booking link for rescheduling\n\nKeep it under 100 words.","group":"sdr"},{"id":"sdr-research-prompt","title":"Account Research Framework","category":"sdr","tags":["research","account","preparation"],"difficulty":"intermediate","description":"Research a prospect account before outreach","prompt":"Help me research [COMPANY] before I reach out to them.\n\nWhat I need to find:\n1. Company basics (size, funding, growth stage)\n2. Recent news/signals (funding, hiring, product launches)\n3. Key stakeholders in [DEPARTMENT]\n4. Tech stack (if relevant)\n5. Likely pain points based on their stage/industry\n6. Competitors they might be using\n7. Trigger events I can reference\n\nMy product: [WHAT YOU SELL]\nMy ICP: [IDEAL CUSTOMER PROFILE]\n\nFormat the research as a one-pager I can reference during outreach.\nHighlight the top 3 angles I should use in my first touch.","group":"sdr"},{"id":"sdr-linkedin-connection","title":"LinkedIn Connection Request","category":"sdr","tags":["linkedin","connection","social-selling"],"difficulty":"beginner","description":"Connection request messages that get accepted","prompt":"Write a LinkedIn connection request for [NAME, TITLE at COMPANY].\n\nContext:\n- Signal I found: [RECENT POST / JOB CHANGE / MUTUAL CONNECTION]\n- My goal: [WHAT YOU WANT TO DISCUSS]\n- Common ground: [SHARED INDUSTRY / INTEREST / BACKGROUND]\n\nConstraints:\n- 300 character limit (LinkedIn's max)\n- Must NOT pitch in the connection request\n- Reference something specific about them\n- Give a reason for connecting that benefits them\n\nWrite 3 versions:\n1. Shared interest approach\n2. Mutual connection approach\n3. Industry peer approach","group":"sdr"},{"id":"sdr-linkedin-followup","title":"LinkedIn Message After Connect","category":"sdr","tags":["linkedin","messaging","social-selling"],"difficulty":"intermediate","description":"First message after LinkedIn connection accepted","prompt":"Write my first LinkedIn message after [NAME] accepted my connection.\n\nContext:\n- Their role: [TITLE at COMPANY]\n- Why I connected: [ORIGINAL REASON]\n- Time since acceptance: [DAYS]\n- My goal: [BOOK MEETING / START CONVERSATION / SHARE CONTENT]\n\nRules:\n- Don't immediately pitch\n- Reference why you connected\n- Provide value first (insight, content, intro)\n- Soft CTA (not \"Let's jump on a call\")\n- Under 100 words\n\nWrite a 3-message sequence:\n1. Value-first opener (Day 1)\n2. Engagement touch (Day 4)\n3. Soft meeting ask (Day 7)","group":"sdr"},{"id":"sdr-video-prospecting","title":"Video Prospecting Script","category":"sdr","tags":["video","prospecting","loom","personalization"],"difficulty":"intermediate","description":"Script for personalized video outreach","prompt":"Create a video prospecting script for [NAME, TITLE at COMPANY].\n\nContext:\n- Personalization hook: [SPECIFIC THING ABOUT THEM/COMPANY]\n- Their likely pain: [PROBLEM YOU SOLVE]\n- Proof point: [SIMILAR CUSTOMER RESULT]\n- Video length: 45-60 seconds max\n\nScript structure:\n1. Pattern interrupt (first 3 seconds are critical)\n2. Why them specifically (prove you researched)\n3. One-sentence value prop\n4. Quick proof point\n5. Clear CTA\n\nInclude:\n- What to show on screen at each moment\n- Thumbnail text suggestion\n- Subject line for video email\n- Text to include in email body\n\nPlatform: [LOOM / VIDYARD / SENDSPARK]","group":"sdr"},{"id":"sdr-multi-thread","title":"Multi-Threading Strategy","category":"sdr","tags":["multi-threading","account-based","stakeholders"],"difficulty":"advanced","description":"Reach multiple stakeholders at one account","prompt":"Create a multi-threading strategy for [COMPANY].\n\nTarget account context:\n- Company size: [EMPLOYEES]\n- Primary contact: [NAME, TITLE] - [STATUS: responded / meeting booked / ghosted]\n- My product: [WHAT YOU SELL]\n- Departments affected: [WHO USES/BUYS YOUR PRODUCT]\n\nIdentify and create outreach for:\n1. Champion candidate (end user who feels pain)\n2. Economic buyer (controls budget)\n3. Technical evaluator (if relevant)\n4. Coach (someone who can give you inside info)\n\nFor each persona, provide:\n- How to find them (title search, LinkedIn, etc.)\n- Unique angle based on their role\n- Whether to reference the primary contact\n- Sequence timing relative to other threads","group":"sdr"},{"id":"sdr-objection-no-time","title":"Handle \"Too Busy Right Now\"","category":"sdr","tags":["objection","busy","timing"],"difficulty":"intermediate","description":"Response when prospects say they have no time","prompt":"Help me respond to: \"I'm too busy right now, reach out next quarter.\"\n\nContext:\n- Prospect: [NAME, TITLE]\n- How they said it: [PHONE / EMAIL / LINKEDIN]\n- What I was asking for: [15 MIN CALL / DEMO / MEETING]\n- Urgency factor: [WHY WAITING COSTS THEM]\n\nGenerate responses for each scenario:\n1. If this is a real timing issue (legitimate)\n2. If this is a brush-off (they're not interested)\n3. If they're evaluating competitor (stalling)\n\nEach response should:\n- Acknowledge their time constraint\n- Probe gently for the real reason\n- Either lock in future time OR qualify out gracefully\n\nInclude a 3-touch nurture sequence if they truly want to wait.","group":"sdr"},{"id":"sdr-referral-request","title":"Internal Referral Request","category":"sdr","tags":["referral","navigation","internal"],"difficulty":"intermediate","description":"Ask contact to refer you to right person","prompt":"Write a message asking [NAME] to refer me to the right person.\n\nSituation:\n- Current contact: [NAME, TITLE]\n- Why they're not the right person: [REASON: different department / too junior / wrong function]\n- Who I think I need: [TARGET ROLE/DEPARTMENT]\n- Relationship with current contact: [COLD / WARM / HAD CONVERSATION]\n\nMessage should:\n1. Acknowledge their role (don't make them feel bypassed)\n2. Explain why someone else might be better fit\n3. Make it easy for them to help (provide intro template)\n4. Give them an out if they can't help\n\nWrite versions for:\n1. Email request\n2. LinkedIn message\n3. End-of-call verbal ask","group":"sdr"},{"id":"sdr-event-followup","title":"Event/Webinar Follow-Up","category":"sdr","tags":["event","webinar","follow-up","conference"],"difficulty":"beginner","description":"Follow up with event attendees or registrants","prompt":"Write follow-up outreach for [EVENT TYPE] attendees.\n\nEvent details:\n- Event name: [EVENT/WEBINAR NAME]\n- Topic covered: [WHAT WAS DISCUSSED]\n- Their engagement: [ATTENDED / REGISTERED BUT NO-SHOW / ASKED QUESTION]\n- Days since event: [NUMBER]\n\nMy angle:\n- Relevant pain point from event topic: [PAIN]\n- How my product relates: [CONNECTION]\n- Specific CTA: [WHAT I WANT THEM TO DO]\n\nWrite sequences for:\n1. Engaged attendees (asked questions, stayed till end)\n2. Passive attendees (watched but no interaction)\n3. No-shows (registered but didn't attend)\n\nEach sequence: 3 touches over 10 days.","group":"sdr"},{"id":"sdr-trigger-event","title":"Trigger Event Outreach","category":"sdr","tags":["trigger","signal","timing","relevance"],"difficulty":"intermediate","description":"Outreach based on specific trigger events","prompt":"Create trigger-based outreach for this signal.\n\nTrigger event: [SELECT ONE]\n- New funding round\n- New executive hire\n- Job posting in relevant area\n- Product launch\n- Company acquisition\n- Office expansion\n- Tech stack change\n- Earnings report mention\n- Industry regulation change\n- Competitor news\n\nProspect details:\n- Company: [COMPANY NAME]\n- Target contact: [NAME, TITLE]\n- My product: [WHAT YOU SELL]\n\nFor this trigger, provide:\n1. Why this trigger matters (what it signals)\n2. Best timing window to reach out\n3. Subject line that references the trigger\n4. Email body that connects trigger → pain → solution\n5. Alternative channels to use (LinkedIn, phone)","group":"sdr"},{"id":"sdr-cold-call-opener","title":"Cold Call Opener Scripts","category":"sdr","tags":["cold-call","opener","phone","pattern-interrupt"],"difficulty":"intermediate","description":"Opening lines for cold calls that get conversations","prompt":"Create cold call opener scripts for [TARGET PERSONA].\n\nContext:\n- Target title: [TITLE]\n- Industry: [INDUSTRY]\n- My company: [YOUR COMPANY]\n- What I sell: [PRODUCT/SERVICE]\n- Time I need: [30 SEC OPENER / ASK FOR 5 MIN]\n\nGenerate 5 different opener styles:\n1. Permission-based (\"Did I catch you at a bad time?\")\n2. Referral/trigger-based (if you have one)\n3. Pattern interrupt (unexpected opening)\n4. Direct approach (straight to the point)\n5. Curiosity-based (open loop)\n\nFor each opener include:\n- The exact words to say\n- Expected response handling (if they say \"who is this?\")\n- Transition to value prop\n- Handling \"not interested\" within first 10 seconds","group":"sdr"},{"id":"sdr-voicemail-script","title":"Voicemail Script Templates","category":"sdr","tags":["voicemail","phone","callback"],"difficulty":"beginner","description":"Voicemail scripts that get callbacks","prompt":"Create voicemail scripts for different scenarios.\n\nTarget: [NAME, TITLE at COMPANY]\nMy value prop: [ONE SENTENCE]\nMy callback number: [NUMBER]\n\nCreate voicemails for:\n1. First touch (they don't know you)\n2. Follow-up to email (you've sent something)\n3. After no-show (they missed meeting)\n4. Trigger-based (reference something timely)\n5. Break-up voicemail (final attempt)\n\nEach voicemail must be:\n- Under 20 seconds when spoken\n- Have ONE clear message\n- End with your name and number (spoken slowly)\n- Include a reason to call back\n\nPro tip: Leave phone number twice—once at beginning, once at end.","group":"sdr"},{"id":"spin-question-generator","title":"SPIN Question Generator","category":"spin","tags":["spin","questions","discovery"],"difficulty":"intermediate","description":"Generate SPIN questions for your product","prompt":"Generate SPIN questions for my sales conversations.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Target persona: [WHO YOU SELL TO]\n- Main problems we solve: [TOP 3 PAIN POINTS]\n- Typical objections: [COMMON PUSHBACK]\n\nGenerate 5 questions for each category:\n\nSITUATION (establish context):\n- Questions about their current state\n- Non-threatening, fact-finding\n\nPROBLEM (uncover difficulties):\n- Questions that surface pain\n- Focus on challenges and frustrations\n\nIMPLICATION (develop seriousness):\n- Questions that expand the problem\n- Connect to business impact\n\nNEED-PAYOFF (envision solution):\n- Questions that make them articulate benefits\n- Let them sell themselves\n\nInclude transitions between each phase.","group":"spin"},{"id":"telecom-cold-email-1","title":"Telecom Executive Cold Email","category":"telecom","subcategory":"outreach","tags":["cold-email","telecom","carrier"],"difficulty":"intermediate","description":"Cold email for telecom carriers and service providers","prompt":"Write a cold email to a telecommunications executive.\n\nContext:\n- Recipient: [NAME, TITLE]\n- Company type: [CARRIER / MSO / MVNO / ENTERPRISE TELECOM]\n- Signal: [5G ROLLOUT / FIBER EXPANSION / COST REDUCTION]\n- My solution: [WHAT YOU SELL]\n- Network impact: [HOW YOU HELP THEIR NETWORK/OPERATIONS]\n\nTelecom Email Rules:\n- Understand their network infrastructure\n- Reference industry trends (5G, fiber, edge, convergence)\n- Speak to ARPU, churn, network efficiency\n- Be aware of CapEx vs. OpEx dynamics\n- Mention relevant integrations (OSS/BSS, network elements)\n- Reference similar carriers or use cases\n\nTelecom buyers care about: network performance, subscriber experience, cost per bit, competitive differentiation.","group":"telecom"},{"id":"telecom-discovery-1","title":"Telecom Discovery Questions","category":"telecom","subcategory":"discovery","tags":["discovery","telecom","network"],"difficulty":"intermediate","description":"Discovery for telecom and carrier sales","prompt":"Generate discovery questions for a telecom prospect.\n\nContext:\n- Prospect: [NAME, TITLE at COMPANY]\n- Telecom type: [CARRIER / CABLE / ENTERPRISE]\n- My product: [WHAT YOU SELL]\n- Network area: [ACCESS / CORE / OSS/BSS / CUSTOMER EXPERIENCE]\n\nTelecom discovery categories:\n1. Network architecture and evolution plans\n2. Current pain points (cost, performance, scale)\n3. Technology stack (vendors, platforms, standards)\n4. Integration requirements (APIs, protocols, legacy)\n5. Decision process (network engineering vs. IT vs. product)\n6. Budget cycles and CapEx planning\n7. Competitive landscape and differentiation needs\n8. Regulatory considerations\n\nTelecom is technical - understand their architecture before proposing.","group":"telecom"},{"id":"telecom-objection-1","title":"Handle \"We're Locked Into Vendor X\"","category":"telecom","subcategory":"objections","tags":["objection","incumbent","vendor"],"difficulty":"advanced","description":"Navigate incumbent vendor relationships","prompt":"Help me respond to: \"We're locked into [INCUMBENT VENDOR] for the next X years.\"\n\nContext:\n- My product: [WHAT YOU SELL]\n- Incumbent: [WHO THEY'RE LOCKED INTO]\n- Contract timeline: [WHEN IT ENDS]\n- Our differentiation: [WHY WE'RE BETTER]\n\nVendor lock-in is real in telecom. Help me:\n1. Understand the scope of the contract\n2. Find gaps the incumbent doesn't cover\n3. Position for co-existence or complement\n4. Plant seeds for contract renewal timing\n5. Identify pain points that could accelerate change\n6. Offer a pilot in a non-contracted area\n\nNever trash the incumbent - just find the gaps.","group":"telecom"},{"id":"telecom-proposal-1","title":"Telecom Network Investment Proposal","category":"telecom","subcategory":"proposals","tags":["proposal","network","infrastructure"],"difficulty":"advanced","description":"Build a business case for network infrastructure","prompt":"Write a proposal for a telecom network investment.\n\nContext:\n- Carrier: [NAME]\n- Network area: [ACCESS / CORE / OSS/BSS]\n- Current challenge: [WHAT THEY'RE SOLVING]\n- My solution: [WHAT YOU SELL]\n- Investment: [YOUR PRICE]\n- Expected outcomes: [METRICS]\n\nTelecom proposals need:\n1. Technical architecture alignment\n2. Network performance improvements (latency, capacity, reliability)\n3. Cost analysis (CapEx, OpEx, TCO)\n4. Integration approach and effort\n5. Migration/implementation plan\n6. Reference carriers and results\n7. Standards and interoperability\n8. Roadmap alignment\n\nTelecom buyers are technical - be precise and specific.","group":"telecom"},{"id":"telecom-follow-up-1","title":"Post-Technology-Trial Follow-Up","category":"telecom","subcategory":"follow-up","tags":["follow-up","trial","poc"],"difficulty":"intermediate","description":"Follow up after a network trial or POC","prompt":"Write a follow-up email after a network technology trial.\n\nContext:\n- Carrier: [NAME]\n- Contact: [NAME, TITLE]\n- Trial scope: [WHAT WAS TESTED]\n- Trial results: [OUTCOMES]\n- Next steps discussed: [WHAT WAS AGREED]\n- Blockers: [IF ANY]\n\nPost-trial follow-up should:\n1. Summarize trial results objectively\n2. Reference specific performance data\n3. Connect results to their business goals\n4. Address any issues that arose\n5. Propose clear path to production\n6. Identify remaining technical validation needs\n\nTelecom trials are extensive - document everything for their internal process.","group":"telecom"},{"id":"uni-meeting-prep","title":"Meeting Preparation Checklist","category":"universal","tags":["preparation","meeting","research"],"difficulty":"beginner","description":"Prepare for any sales meeting","prompt":"Help me prepare for a sales meeting.\n\nMeeting details:\n- Prospect: [NAME, TITLE at COMPANY]\n- Meeting type: [INTRO / DISCOVERY / DEMO / NEGOTIATION]\n- Duration: [MINUTES]\n- Virtual or in-person: [FORMAT]\n- Other attendees: [WHO ELSE]\n- Previous interactions: [HISTORY]\n\nPrepare:\n1. Research briefing (company news, their role, mutual connections)\n2. Meeting objectives (what I want to accomplish)\n3. Key questions to ask (prioritized)\n4. Anticipated objections and responses\n5. Value props most relevant to them\n6. Success metrics for the meeting\n7. Clear next step to propose\n8. Backup plan if main approach doesn't work\n\nAlso: Calendar items to send, materials to prepare, tech to test.","group":"universal"},{"id":"uni-email-reply-busy","title":"Reply to \"Too Busy\" Email","category":"universal","tags":["email","objection","follow-up"],"difficulty":"beginner","description":"Craft a response when prospect says they are too busy","prompt":"Write a reply to a prospect who said they're too busy.\n\nContext:\n- Their response: [EXACT TEXT OF THEIR REPLY]\n- What I originally asked for: [MY ASK]\n- My product: [WHAT I SELL]\n- Their likely priorities: [WHAT'S ON THEIR PLATE]\n\nResponse strategies:\n1. Acknowledge and offer smaller ask\n2. Propose specific future time\n3. Offer async option (video, doc, etc.)\n4. Connect my ask to reducing their busyness\n5. Give them an easy out with follow-up timing\n\nWrite 3 response options with different approaches.\nKeep each under 50 words.","group":"universal"},{"id":"uni-recap-email","title":"Meeting Recap Email","category":"universal","tags":["email","recap","follow-up"],"difficulty":"beginner","description":"Summarize a meeting and confirm next steps","prompt":"Write a meeting recap email.\n\nMeeting details:\n- Attendees: [WHO WAS THERE]\n- Meeting type: [TYPE]\n- Key topics discussed: [MAIN POINTS]\n- Problems they mentioned: [PAIN POINTS]\n- Their questions: [QUESTIONS THEY ASKED]\n- Action items agreed: [WHAT'S NEXT]\n- Timeline discussed: [DATES]\n\nRecap email should:\n1. Thank them (brief)\n2. Summarize what we heard (shows we listened)\n3. List action items with owners\n4. Confirm next meeting/step\n5. Attach relevant resources\n6. Keep it scannable\n\nUnder 200 words. Send within 2 hours of meeting.","group":"universal"},{"id":"uni-no-show-follow-up","title":"No-Show Follow-Up","category":"universal","tags":["no-show","follow-up","reschedule"],"difficulty":"beginner","description":"Follow up after a prospect misses a meeting","prompt":"Write a follow-up after a prospect no-showed.\n\nContext:\n- Prospect: [NAME, TITLE]\n- Meeting type: [WHAT IT WAS]\n- How they booked: [INBOUND / OUTBOUND / REFERRAL]\n- Attempts to reach: [NONE / CALLED / TEXTED]\n- First no-show or repeat: [FREQUENCY]\n\nWrite 3 versions:\n1. Benefit-of-doubt (same day, assumes conflict)\n2. Gentle check-in (next day)\n3. Last attempt (3 days later)\n\nEach version should:\n- Not guilt them\n- Make it easy to reschedule\n- Include your calendar link\n- Be under 50 words\n- Have a subject line\n\nNever be passive aggressive. Things happen.","group":"universal"},{"id":"uni-objection-price","title":"Handle Price Objections","category":"universal","tags":["objection","pricing","negotiation"],"difficulty":"intermediate","description":"Respond to various price objections","prompt":"Help me respond to a price objection.\n\nContext:\n- What they said: [EXACT OBJECTION]\n- My price: [WHAT I QUOTED]\n- Their budget (if known): [THEIR NUMBER]\n- Value I provide: [KEY BENEFITS]\n- Flexibility I have: [WHAT I CAN ADJUST]\n- Competition: [WHAT ALTERNATIVES COST]\n\nGenerate responses for these price objection types:\n1. \"It's too expensive\" (general sticker shock)\n2. \"We only have $X budget\" (specific number)\n3. \"Competitor is cheaper\" (competitive pressure)\n4. \"Can't justify the ROI\" (value question)\n5. \"Need discount to close\" (negotiation tactic)\n\nFor each, provide:\n- Questions to ask first\n- Reframe language\n- When to hold firm\n- When to negotiate\n- Creative alternatives to discounting","group":"universal"},{"id":"uni-internal-champion-email","title":"Champion Enablement Email","category":"universal","tags":["champion","internal-selling","enablement"],"difficulty":"intermediate","description":"Arm your champion to sell internally","prompt":"Create content to help my champion sell internally.\n\nContext:\n- Champion: [NAME, TITLE]\n- Decision maker they need to convince: [WHO]\n- What they need to justify: [THE ASK]\n- Internal objections they'll face: [CONCERNS]\n- Our value prop: [KEY BENEFITS]\n- ROI case: [NUMBERS]\n\nCreate:\n1. One-pager they can share (bullet points)\n2. Email they can forward to their boss\n3. Talk track for their internal meeting\n4. Responses to likely internal pushback\n5. Quick ROI summary\n\nMake everything easy to copy-paste. Use their company's language.","group":"universal"},{"id":"uni-referral-request","title":"Ask for Referral","category":"universal","tags":["referral","customer","growth"],"difficulty":"beginner","description":"Request referrals from happy customers","prompt":"Write a referral request message.\n\nContext:\n- Customer: [NAME at COMPANY]\n- Relationship length: [HOW LONG]\n- Value delivered: [RESULTS/OUTCOMES]\n- Target referral type: [WHO YOU WANT TO MEET]\n- How to ask: [EMAIL / CALL / IN QBR]\n\nWrite versions for:\n1. Direct ask (strong relationship)\n2. Soft ask (newer relationship)\n3. Specific person ask (you know who)\n4. Event-based (after success milestone)\n5. Quid pro quo (you're offering something)\n\nEach version should:\n- Lead with their success\n- Make the ask specific\n- Make it easy to say yes\n- Include language they can use for intro\n- Not be pushy","group":"universal"},{"id":"uni-competitor-mention","title":"Handle Competitor Mention","category":"universal","tags":["competitive","positioning","objection"],"difficulty":"intermediate","description":"Respond when prospect mentions competitor","prompt":"Help me respond when a prospect mentions a competitor.\n\nContext:\n- What they said: [EXACT QUOTE]\n- Competitor mentioned: [NAME]\n- Where we're strong vs. them: [ADVANTAGES]\n- Where they're strong vs. us: [THEIR ADVANTAGES]\n- Prospect's priorities: [WHAT THEY CARE ABOUT]\n\nCreate responses for these scenarios:\n1. \"We're also looking at X\" (evaluation)\n2. \"We currently use X\" (displacement)\n3. \"X is cheaper\" (price comparison)\n4. \"X has feature Y\" (feature gap)\n5. \"We heard X is better at Z\" (reputation)\n\nRules:\n- Never badmouth competitor\n- Ask questions first\n- Focus on fit, not features\n- Acknowledge where they're strong\n- Tie differentiators to their priorities","group":"universal"},{"id":"uni-linkedin-post-ideas","title":"LinkedIn Content Ideas for Sales","category":"universal","tags":["linkedin","content","social-selling"],"difficulty":"beginner","description":"Generate LinkedIn post ideas for social selling","prompt":"Generate LinkedIn post ideas for sales content.\n\nContext:\n- My industry: [INDUSTRY]\n- My target buyer: [PERSONA]\n- My expertise: [TOPICS I KNOW]\n- My goal: [BRAND / LEADS / ENGAGEMENT]\n\nGenerate 10 post ideas in these formats:\n1. Contrarian take (challenge conventional wisdom)\n2. Lesson learned (personal story)\n3. Quick tip (tactical advice)\n4. Myth busting (common misconception)\n5. Framework share (process I use)\n6. Question post (spark discussion)\n7. Observation (industry trend)\n8. Celebration (customer success, without naming)\n9. Behind the scenes (authentic look)\n10. Poll (engagement driver)\n\nFor each idea:\n- Hook (first line)\n- Key points (3-5 bullets)\n- CTA (if any)\n- Best time to post","group":"universal"},{"id":"uni-case-study-structure","title":"Case Study Builder","category":"universal","tags":["case-study","proof","content"],"difficulty":"intermediate","description":"Structure a customer success story","prompt":"Help me structure a customer case study.\n\nCustomer details:\n- Company: [NAME]\n- Industry: [INDUSTRY]\n- Size: [SIZE]\n- Their challenge: [PROBLEM THEY HAD]\n- Our solution: [WHAT WE PROVIDED]\n- Results: [OUTCOMES/METRICS]\n- Timeline: [HOW LONG TO RESULTS]\n\nCreate structure for:\n1. One-paragraph summary (for emails)\n2. One-pager (for sales)\n3. Full case study (for website)\n4. Quote for social proof\n5. Slide for presentations\n\nEach format should include:\n- The challenge (pain)\n- The solution (how we helped)\n- The results (outcomes)\n- A quotable quote\n\nIdentify gaps where I need more info from the customer.","group":"universal"},{"id":"uni-cold-call-voicemail","title":"Voicemail That Gets Callbacks","category":"universal","tags":["cold-call","voicemail","phone"],"difficulty":"beginner","description":"Leave effective cold call voicemails","prompt":"Write cold call voicemail scripts.\n\nContext:\n- Target: [TITLE at COMPANY TYPE]\n- My company: [NAME]\n- My value prop: [ONE SENTENCE]\n- Why them specifically: [PERSONALIZATION ANGLE]\n- My callback number: [NUMBER]\n\nWrite voicemails for:\n1. First touch (they don't know me)\n2. Follow-up to email (they got my email)\n3. Trigger event (timely reason)\n4. Referral mention (someone suggested)\n5. Break-up voicemail (final attempt)\n\nEach voicemail must be:\n- Under 20 seconds when spoken\n- Have ONE clear point\n- Say name and number slowly\n- Give a reason to call back\n- End with number again","group":"universal"},{"id":"uni-deal-update-internal","title":"Internal Deal Update","category":"universal","tags":["internal","deal","update","leadership"],"difficulty":"intermediate","description":"Update leadership on deal status","prompt":"Write an internal deal update for leadership.\n\nDeal context:\n- Account: [COMPANY]\n- Deal size: [VALUE]\n- Stage: [CURRENT STAGE]\n- Close date: [TARGET]\n- Champion: [NAME, STRENGTH]\n- Competition: [WHO ELSE]\n- Blockers: [WHAT'S IN THE WAY]\n- Support needed: [WHAT I NEED FROM LEADERSHIP]\n\nStructure the update:\n1. One-line status (green/yellow/red + why)\n2. Progress since last update\n3. Key milestones hit\n4. Current blockers and plan\n5. Specific ask (if any)\n6. Next steps with dates\n\nKeep it scannable. Executives skim.\nFlag where you need help early.","group":"universal"},{"id":"uni-demo-agenda","title":"Demo Agenda Template","category":"universal","tags":["demo","presentation","agenda"],"difficulty":"intermediate","description":"Structure an effective product demo","prompt":"Create a demo agenda based on discovery.\n\nDiscovery findings:\n- Main pain: [PRIMARY PROBLEM]\n- Secondary pain: [SECONDARY PROBLEM]\n- Current tools: [WHAT THEY USE TODAY]\n- Decision criteria: [HOW THEY'LL EVALUATE]\n- Attendees: [WHO'S IN THE DEMO]\n- Time: [MINUTES AVAILABLE]\n\nCreate an agenda that:\n1. Opens with their situation (show you listened)\n2. Maps agenda to their priorities\n3. Shows most relevant features only\n4. Includes a \"wow moment\"\n5. Leaves time for questions\n6. Ends with clear next step\n\nAlso provide:\n- Talking points for each section\n- Questions to ask during demo\n- How to handle \"can you show feature X?\"\n- Recovery if demo breaks","group":"universal"},{"id":"uni-qualification-questions","title":"Universal Qualification Questions","category":"universal","tags":["qualification","discovery","questions"],"difficulty":"intermediate","description":"Questions to qualify any opportunity","prompt":"Generate qualification questions for any sales conversation.\n\nContext:\n- My product: [WHAT YOU SELL]\n- My typical deal size: [ACV RANGE]\n- My sales cycle: [TYPICAL LENGTH]\n\nGenerate questions for:\nBANT:\n- Budget (without asking \"what's your budget?\")\n- Authority (who makes the decision?)\n- Need (what problem are they solving?)\n- Timeline (when do they need this?)\n\nMEDDPICC (for enterprise):\n- Metrics (how will they measure success?)\n- Economic Buyer (who controls budget?)\n- Decision Criteria (how will they evaluate?)\n- Decision Process (what are the steps?)\n- Paper Process (procurement/legal?)\n- Identify Pain (what's the compelling event?)\n- Champion (who's advocating internally?)\n- Competition (who else are they looking at?)\n\nFor each question:\n- Natural way to ask\n- Follow-up if answer is vague\n- Red flag answers","group":"universal"},{"id":"uni-trial-check-in","title":"Trial Check-In Messages","category":"universal","tags":["trial","check-in","adoption"],"difficulty":"beginner","description":"Check in with trial users to drive adoption","prompt":"Create trial check-in messages.\n\nContext:\n- Product: [WHAT YOU SELL]\n- Trial length: [DAYS]\n- Key activation event: [WHAT SHOWS THEY'RE ENGAGED]\n- Customer persona: [WHO'S USING IT]\n\nCreate check-ins for:\nDay 1: Welcome + quick start\nDay 3: First milestone check\nDay 7: Engagement check (are they using it?)\nDay 10: Value conversation\nDay [X-2]: Trial ending soon\nDay [X]: Final ask\n\nFor each check-in:\n- Subject line\n- Body (under 100 words)\n- Goal of the touchpoint\n- If low engagement, alternative message\n- CTA\n\nInclude both email and in-app message versions.","group":"universal"},{"id":"uni-proposal-structure","title":"Proposal Document Structure","category":"universal","tags":["proposal","document","closing"],"difficulty":"advanced","description":"Structure a winning proposal document","prompt":"Structure a proposal document.\n\nDeal context:\n- Prospect: [COMPANY]\n- Deal size: [VALUE]\n- Decision timeline: [WHEN]\n- Key stakeholders: [WHO'S READING]\n- Main problems we solve: [TOP 3 PAINS]\n- Competition: [WHO ELSE]\n\nProposal structure:\n1. Executive Summary (1 page)\n2. Understanding Your Situation\n3. Proposed Solution\n4. Implementation Approach\n5. Investment & ROI\n6. About Us (brief)\n7. Next Steps\n\nFor each section provide:\n- What to include\n- What to avoid\n- Length guidance\n- Visuals to consider\n\nAlso include:\n- Email to send with proposal\n- How to present vs. just send\n- Follow-up cadence if no response","group":"universal"},{"id":"uni-territory-planning","title":"Territory Planning Prompt","category":"universal","tags":["territory","planning","strategy"],"difficulty":"advanced","description":"Plan coverage for your territory","prompt":"Help me plan my sales territory.\n\nTerritory details:\n- Geographic/vertical scope: [WHAT I OWN]\n- Account list: [NUMBER OF ACCOUNTS]\n- Quota: [TARGET]\n- My product: [WHAT I SELL]\n- Average deal size: [TYPICAL ACV]\n- Sales cycle: [LENGTH]\n\nCreate a territory plan that includes:\n1. Account tiering (A/B/C criteria)\n2. Time allocation by tier\n3. Weekly/monthly activity targets\n4. Pipeline math (what I need to hit quota)\n5. Account prioritization framework\n6. Coverage gaps to address\n7. Quick wins vs. long-term plays\n8. Metrics to track\n\nOutput:\n- Account tier definitions\n- Weekly activity template\n- Pipeline goals by month\n- Top 10 accounts to focus on and why","group":"universal"},{"id":"uni-renewal-outreach","title":"Renewal Outreach Sequence","category":"universal","tags":["renewal","retention","customer"],"difficulty":"intermediate","description":"Outreach for upcoming renewals","prompt":"Create a renewal outreach sequence.\n\nCustomer context:\n- Company: [NAME]\n- Current ARR: [VALUE]\n- Renewal date: [DATE]\n- Days until renewal: [DAYS]\n- Usage level: [HIGH / MEDIUM / LOW]\n- NPS/satisfaction: [IF KNOWN]\n- Expansion opportunity: [IF ANY]\n- Risk level: [LOW / MEDIUM / HIGH]\n\nCreate outreach for:\n- 90 days out: Health check\n- 60 days out: Renewal preview\n- 45 days out: Formal renewal conversation\n- 30 days out: Proposal/quote\n- 14 days out: Close push\n- 7 days out: Final ask\n\nFor each touchpoint:\n- Email template\n- Call script key points\n- What to achieve\n- If at-risk, alternative approach\n\nInclude executive sponsor escalation if needed.","group":"universal"},{"id":"uni-objection-bank","title":"Common Objection Response Bank","category":"universal","tags":["objections","responses","handling"],"difficulty":"intermediate","description":"Responses to the most common sales objections","prompt":"Create responses for common sales objections.\n\nContext:\n- My product: [WHAT YOU SELL]\n- My typical buyer: [PERSONA]\n- My price point: [RANGE]\n\nGenerate responses for:\n1. \"We're happy with our current solution\"\n2. \"It's not a priority right now\"\n3. \"Send me some information\"\n4. \"I need to talk to my team/boss\"\n5. \"Let me think about it\"\n6. \"We tried something like this before and it didn't work\"\n7. \"We're too busy to implement anything new\"\n8. \"Call me back in [future date]\"\n9. \"We don't have budget allocated for this\"\n10. \"I'm not the decision maker\"\n\nFor each objection:\n- Empathetic acknowledgment\n- Probing question\n- Reframe response\n- Exit gracefully if real\n- Red flag that means stop","group":"universal"},{"id":"uni-email-subject-ab-test","title":"A/B Test Email Subject Lines","category":"universal","tags":["email","subject-line","ab-test"],"difficulty":"beginner","description":"Generate subject line variations for testing","prompt":"Generate A/B test subject line variations.\n\nContext:\n- Original subject: [CURRENT SUBJECT LINE]\n- Email purpose: [COLD / FOLLOW-UP / NURTURE / PROMO]\n- Target persona: [WHO'S RECEIVING]\n- Tone: [PROFESSIONAL / CASUAL / URGENT]\n\nGenerate 10 variations using different psychological triggers:\n1. Curiosity (opens a loop)\n2. Benefit (what they get)\n3. Pain point (what they avoid)\n4. Social proof (others doing it)\n5. Scarcity (limited availability)\n6. Specificity (exact numbers)\n7. Question (engages them)\n8. Personal (uses their name/company)\n9. News hook (timely/relevant)\n10. Direct ask (no games)\n\nFor each variation:\n- The subject line\n- Character count\n- Why it might work\n- Who it works best for","group":"universal"},{"id":"uni-intro-email-new-contact","title":"Introduction to New Contact","category":"universal","tags":["email","introduction","stakeholder"],"difficulty":"beginner","description":"Introduce yourself to a new stakeholder","prompt":"Write an introduction email to a new contact at an existing account.\n\nContext:\n- New contact: [NAME, TITLE]\n- How you learned about them: [REFERRAL / ORG CHART / LINKEDIN]\n- Your existing contact: [NAME, TITLE]\n- Your relationship: [PROSPECT / CUSTOMER / PARTNER]\n- Why you want to connect: [REASON]\n\nIntroduction approaches:\n1. Referral from existing contact\n2. Org chart discovery (direct)\n3. LinkedIn connection first then email\n4. Through shared meeting invite\n5. Value-first (share something useful)\n\nFor each approach:\n- Email template\n- Subject line\n- When to use it\n- How to handle if no response","group":"universal"},{"id":"uni-reactivation-email","title":"Lead Reactivation Campaign","category":"universal","tags":["reactivation","nurture","closed-lost"],"difficulty":"intermediate","description":"Re-engage old leads and closed-lost opps","prompt":"Create a reactivation campaign for old leads.\n\nContext:\n- Lead status: [COLD / CLOSED-LOST / NURTURE]\n- How long since contact: [MONTHS]\n- Original reason for no-deal: [WHY THEY DIDN'T BUY]\n- What's changed since then: [NEW FEATURES / PRICING / POSITIONING]\n- Total leads to reactivate: [NUMBER]\n\nCreate:\n1. Re-engagement email sequence (3 touches)\n2. Phone script for warm calls\n3. LinkedIn message approach\n4. Value-add content to share\n5. Segmentation criteria (who to prioritize)\n\nFor each touch:\n- Acknowledge the time gap\n- Reference previous conversation\n- Lead with new value\n- Make it easy to re-engage\n- Have a clear, low-commitment ask","group":"universal"},{"id":"uni-exec-intro-email","title":"Executive Introduction Email","category":"universal","tags":["executive","cold-email","c-level"],"difficulty":"advanced","description":"Cold email to C-level executives","prompt":"Write a cold email to a C-level executive.\n\nContext:\n- Executive: [NAME, TITLE at COMPANY]\n- Company size: [REVENUE/EMPLOYEES]\n- Signal/trigger: [WHY NOW]\n- Business outcome we drive: [TOP-LINE IMPACT]\n- Exec-level proof point: [SIMILAR EXEC/COMPANY RESULT]\n\nExecutive email rules:\n- Lead with business impact, not product\n- One specific insight they might not have\n- Shorter is better (under 75 words)\n- No fluff or empty compliments\n- Peer credibility matters\n- Ask for direction, not their time\n\nStructure:\n1. Pattern interrupt (first line matters)\n2. One insight or observation\n3. Credibility marker\n4. Soft CTA (who should I speak with?)\n\nWrite 3 versions with different hooks.","group":"universal"},{"id":"uni-persona-research","title":"Buyer Persona Research","category":"universal","tags":["persona","research","icp"],"difficulty":"intermediate","description":"Research a buyer persona for better messaging","prompt":"Help me research and understand a buyer persona.\n\nPersona to research:\n- Title/Role: [TITLE]\n- Industry: [INDUSTRY]\n- Company size: [SEGMENT]\n\nI need to understand:\n1. What's in their job description?\n2. How are they measured (KPIs)?\n3. What do they worry about (3 AM problems)?\n4. What's their boss asking them for?\n5. What would make them a hero internally?\n6. What have they tried before that failed?\n7. Who influences their decisions?\n8. How do they prefer to buy?\n9. What content do they consume?\n10. What language do they use?\n\nAlso provide:\n- Day in the life\n- Goals vs. obstacles\n- Buying triggers\n- Objections I'll hear\n- Best way to reach them","group":"universal"},{"id":"uni-power-questions","title":"Power Questions for Sales","category":"universal","tags":["questions","discovery","power-questions"],"difficulty":"intermediate","description":"High-impact questions for any sales conversation","prompt":"Generate power questions for sales conversations.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Conversation type: [COLD CALL / DISCOVERY / DEMO / CLOSE]\n- Buyer persona: [WHO I'M TALKING TO]\n\nGenerate questions in these categories:\n\nOpening Power Questions:\n- To grab attention\n- To understand their world\n- To earn the right to continue\n\nPain Discovery Questions:\n- To find problems\n- To quantify impact\n- To create urgency\n\nProcess Questions:\n- To understand how they buy\n- To identify stakeholders\n- To map timeline\n\nCommitment Questions:\n- To test interest\n- To identify blockers\n- To advance the deal\n\nFor each question:\n- The exact question\n- When to use it\n- What you're really learning\n- Follow-up if they're vague","group":"universal"},{"id":"uni-value-proposition","title":"Value Proposition Builder","category":"universal","tags":["value-prop","messaging","positioning"],"difficulty":"intermediate","description":"Craft value propositions for different audiences","prompt":"Build value propositions for my product.\n\nContext:\n- My product: [WHAT YOU SELL]\n- What it does: [FUNCTIONALITY]\n- Who uses it: [END USERS]\n- Problems it solves: [TOP 3 PAIN POINTS]\n- Outcomes it delivers: [RESULTS]\n- Differentiators: [WHY US VS ALTERNATIVES]\n\nCreate value propositions for:\n1. One-liner (10 words max)\n2. Elevator pitch (30 seconds)\n3. Email opener (one sentence)\n4. Website headline\n5. Cold call opener\n6. Exec summary intro\n\nThen adapt for different personas:\n- Economic buyer (ROI focused)\n- Technical evaluator (capability focused)\n- End user (ease of use focused)\n- Champion (internal justification)\n\nTest each against: \"So what?\" and \"Why you?\"","group":"universal"},{"id":"uni-social-proof-bank","title":"Social Proof Library","category":"universal","tags":["social-proof","testimonials","references"],"difficulty":"beginner","description":"Organize and use social proof effectively","prompt":"Help me build a social proof library.\n\nCurrent proof points:\n- Customer quotes: [LIST WHAT YOU HAVE]\n- Case studies: [LIST TITLES]\n- Metrics/results: [KEY NUMBERS]\n- Logos: [RECOGNIZABLE BRANDS]\n- Awards/recognition: [ACCOLADES]\n- Industry validation: [ANALYSTS, PRESS]\n\nHelp me organize this for different uses:\n\nEmail Proof Points:\n- One-liners to drop in\n- Specific results to cite\n\nCall Talk Tracks:\n- How to weave in naturally\n- \"Companies like X are using this to...\"\n\nProposal Proof:\n- Which proof for which objection\n- Industry-specific references\n\nPresentation Slides:\n- Logo slides\n- Quote slides\n- Results slides\n\nFor each situation, show me how to use what I have.","group":"universal"},{"id":"uni-urgency-creation","title":"Urgency Creation Techniques","category":"universal","tags":["urgency","closing","motivation"],"difficulty":"advanced","description":"Create genuine urgency without being pushy","prompt":"Help me create urgency in this deal.\n\nContext:\n- Prospect: [COMPANY]\n- Deal stage: [STAGE]\n- Their stated timeline: [WHAT THEY SAID]\n- Actual buying signals: [WHAT YOU'VE SEEN]\n- What's causing delay: [BLOCKER]\n- Our leverage: [WHY THEY NEED US]\n\nGenerate ethical urgency angles:\n1. Cost of delay (what waiting costs them)\n2. Competitive risk (what others are doing)\n3. Implementation timeline (start now to hit goal)\n4. Resource availability (our capacity)\n5. Pricing (legitimate expiration)\n6. Business cycle (their fiscal year/quarter)\n7. External event (industry change, regulation)\n\nFor each angle:\n- How to position it\n- Language to use\n- When it's appropriate\n- When to NOT use it\n- How to avoid being sleazy","group":"universal"},{"id":"uni-negotiation-prep","title":"Negotiation Preparation Framework","category":"universal","tags":["negotiation","preparation","strategy"],"difficulty":"advanced","description":"Prepare for any negotiation conversation","prompt":"Prepare me for a negotiation.\n\nDeal context:\n- Prospect: [COMPANY]\n- Our ask: [PRICE/TERMS]\n- Their position: [WHAT THEY WANT]\n- History: [NEGOTIATION SO FAR]\n- Stakeholders: [WHO'S INVOLVED]\n- Competition: [ALTERNATIVES THEY HAVE]\n- Timeline pressure: [THEIR DEADLINE / OURS]\n\nPrepare:\n1. BATNA Analysis\n   - Our best alternative if this fails\n   - Their best alternative if this fails\n\n2. Zone of Possible Agreement\n   - Our walkaway point\n   - Their likely walkaway\n   - Target outcome\n\n3. Concession Strategy\n   - What we can give\n   - What we want in return\n   - Order of concessions\n\n4. Objection Responses\n   - Anticipated pushback\n   - How to respond\n\n5. Closing Approach\n   - How to ask for the close\n   - How to handle \"no\"\n   - How to leave door open","group":"universal"},{"id":"uni-weekly-planning","title":"Sales Week Planning","category":"universal","tags":["planning","productivity","time-management"],"difficulty":"beginner","description":"Plan your sales activities for the week","prompt":"Help me plan my sales week.\n\nCurrent state:\n- Open pipeline: [TOTAL VALUE]\n- Deals closing this month: [NUMBER AND VALUE]\n- Meetings booked this week: [NUMBER]\n- Prospecting target: [CALLS/EMAILS]\n- Admin tasks due: [WHAT'S NEEDED]\n\nHelp me plan:\n1. Priority deals to advance (top 3-5)\n2. Prospecting blocks (when and how much)\n3. Follow-up tasks (who needs what)\n4. Meeting preparation time\n5. Admin time (CRM, forecasting)\n\nWeekly cadence template:\n- Monday: Week planning + top deals\n- Tuesday-Thursday: Prospecting + meetings\n- Friday: Follow-up + forecast\n\nTime blocking suggestions:\n- Deep work windows\n- Call blocks\n- Email processing\n- CRM updates","group":"universal"},{"id":"uni-lost-deal-analysis","title":"Lost Deal Post-Mortem","category":"universal","tags":["lost-deal","analysis","learning"],"difficulty":"intermediate","description":"Analyze why a deal was lost","prompt":"Analyze this lost deal for learnings.\n\nDeal details:\n- Company: [PROSPECT]\n- Deal value: [AMOUNT]\n- Sales cycle length: [DAYS]\n- Stage reached: [HIGHEST STAGE]\n- Competition: [WHO ELSE]\n- Who won: [COMPETITOR / NO DECISION / INTERNAL]\n- Reason given: [WHAT THEY SAID]\n\nAnalyze:\n1. Where did we lose it? (which stage)\n2. Was it winnable? (qualification check)\n3. What did competition do better?\n4. What would we do differently?\n5. Red flags we missed?\n6. Good things we did?\n\nCategories of loss:\n- Timing (not ready to buy)\n- Budget (couldn't afford)\n- Competition (chose someone else)\n- No decision (did nothing)\n- Bad fit (should have disqualified)\n\nAction items:\n- What to improve for next time\n- How to stay in touch (maybe future opportunity)","group":"universal"},{"id":"uni-champion-checklist","title":"Champion Validation Checklist","category":"universal","tags":["champion","validation","qualification"],"difficulty":"advanced","description":"Validate if your champion is real","prompt":"Validate if my contact is a true champion.\n\nContact details:\n- Name and title: [WHO]\n- Time in role: [TENURE]\n- Relationship with EB: [CONNECTION]\n- What they've done for us: [ACTIONS]\n- What they've said: [COMMITMENTS]\n\nChampion criteria (must have all 3):\n1. POWER: Can influence the decision\n2. ACCESS: Can get you to decision makers\n3. WILL: Actively selling for you internally\n\nValidation tests:\n1. Will they give you info others won't?\n2. Will they coach you on internal dynamics?\n3. Will they introduce you to power?\n4. Will they tell you the truth about your position?\n5. Will they fight for you when you're not there?\n\nIf they fail:\n- How to build a real champion\n- Where else to look\n- Questions to find hidden champions","group":"universal"},{"id":"uni-competitive-landmine","title":"Competitive Landmines","category":"universal","tags":["competitive","differentiation","questions"],"difficulty":"advanced","description":"Plant questions that expose competitor weaknesses","prompt":"Create competitive landmines for my evaluation.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Main competitor: [WHO]\n- Where we're strong: [OUR ADVANTAGES]\n- Where they're weak: [THEIR GAPS]\n- Buyer's likely criteria: [WHAT THEY CARE ABOUT]\n\nCreate landmines (questions for buyer to ask competitor):\n1. Technical landmines (expose capability gaps)\n2. Process landmines (expose complexity)\n3. Support landmines (expose service gaps)\n4. Pricing landmines (expose hidden costs)\n5. Roadmap landmines (expose direction)\n\nFor each landmine:\n- The question to plant\n- Why it hurts competitor\n- Natural way to bring it up\n- What answer exposes the weakness\n\nRules:\n- Don't lie or exaggerate\n- Focus on real differences\n- Make questions reasonable\n- Be ready if they flip it on you","group":"universal"},{"id":"uni-deal-review-prep","title":"Deal Review Preparation","category":"universal","tags":["deal-review","coaching","preparation"],"difficulty":"intermediate","description":"Prepare for a deal review with your manager","prompt":"Prepare for a deal review with my manager.\n\nDeal details:\n- Account: [COMPANY]\n- Deal size: [VALUE]\n- Close date: [TARGET]\n- Current stage: [STAGE]\n- Days in stage: [NUMBER]\n\nPrepare to answer:\n1. SITUATION: What's the deal? (one paragraph)\n2. QUALIFICATION: Is this real? (MEDDPICC/BANT)\n3. COMPETITION: Are we winning?\n4. NEXT STEPS: What happens next?\n5. HELP NEEDED: What support do I need?\n\nAnticipate manager questions:\n- Why will they buy?\n- Why us vs. competition?\n- Is the close date realistic?\n- What could go wrong?\n- What are you doing to advance it?\n\nCome with specific asks, not vague \"I need help.\"","group":"universal"},{"id":"uni-email-writing-polish","title":"Email Polish and Improvement","category":"universal","tags":["email","writing","improvement"],"difficulty":"beginner","description":"Improve an existing sales email","prompt":"Improve this sales email.\n\nCurrent email:\n[PASTE YOUR EMAIL HERE]\n\nContext:\n- Purpose: [WHAT YOU'RE TRYING TO ACHIEVE]\n- Recipient: [WHO]\n- Stage: [COLD / WARM / FOLLOW-UP]\n\nCheck and improve:\n1. Subject line (is it compelling?)\n2. Opening line (does it hook?)\n3. Length (too long?)\n4. Clarity (is the ask clear?)\n5. Value (what's in it for them?)\n6. CTA (is it specific?)\n7. Tone (right for the reader?)\n8. Personalization (is it generic?)\n9. Grammar/typos\n10. Mobile readability\n\nProvide:\n- Rewritten version\n- What I changed and why\n- Alternative subject lines\n- Shorter version if too long","group":"universal"},{"id":"uni-buying-committee-map","title":"Buying Committee Mapping","category":"universal","tags":["stakeholders","mapping","enterprise"],"difficulty":"advanced","description":"Map all stakeholders in a complex deal","prompt":"Map the buying committee for this deal.\n\nDeal context:\n- Company: [PROSPECT]\n- Deal size: [VALUE]\n- What we sell: [PRODUCT]\n- Known contacts: [WHO YOU KNOW]\n\nFor each stakeholder type, identify:\n1. Economic Buyer (budget authority)\n2. Technical Buyer (evaluates capabilities)\n3. User Buyer (will use daily)\n4. Champion (wants you to win)\n5. Coach (gives inside info)\n6. Blocker (might say no)\n7. Influencer (shapes opinion)\n8. Legal/Procurement (contract authority)\n\nFor each person found:\n- Name and title\n- Their agenda (what they care about)\n- How to win them\n- Risk they pose\n- Engagement strategy\n\nCreate a visual org chart with relationships.","group":"universal"},{"id":"uni-discovery-debrief","title":"Discovery Call Debrief","category":"universal","tags":["discovery","debrief","notes"],"difficulty":"intermediate","description":"Debrief and extract insights from discovery","prompt":"Debrief my discovery call and extract key insights.\n\nCall details:\n- Prospect: [NAME, TITLE at COMPANY]\n- Call duration: [MINUTES]\n- Raw notes: [PASTE YOUR NOTES]\n\nExtract and organize:\n1. SITUATION (current state)\n   - How they do it today\n   - Tools/processes in place\n   - Team structure\n\n2. PAIN (problems)\n   - Problems mentioned\n   - Impact of problems\n   - Urgency level\n\n3. IMPACT (quantified)\n   - Time wasted\n   - Money lost\n   - Risk exposure\n\n4. DECISION (process)\n   - Who else involved\n   - Timeline\n   - Budget\n\n5. NEXT STEPS\n   - What was agreed\n   - Follow-up actions\n\nAlso flag: Red flags, positive signals, info gaps to fill.","group":"universal"},{"id":"uni-sales-deck-outline","title":"Sales Presentation Outline","category":"universal","tags":["presentation","deck","pitch"],"difficulty":"intermediate","description":"Structure a compelling sales presentation","prompt":"Create a sales presentation outline.\n\nContext:\n- Audience: [WHO'S ATTENDING]\n- Meeting purpose: [INTRO / DEEP DIVE / EXEC]\n- Time available: [MINUTES]\n- What they know: [BACKGROUND]\n- My product: [WHAT YOU SELL]\n- Key message: [MAIN POINT]\n\nCreate outline for:\n1. Opening (grab attention)\n2. Agenda (set expectations)\n3. Their situation (show you understand)\n4. The problem (pain amplification)\n5. The solution (your approach)\n6. How it works (demo/walkthrough)\n7. Results/proof (social proof)\n8. Investment (pricing)\n9. Next steps (CTA)\n\nFor each section:\n- Key points to make\n- Time allocation\n- Visuals needed\n- Questions to ask audience\n- Transitions between sections","group":"universal"},{"id":"uni-crm-notes","title":"CRM Notes Template","category":"universal","tags":["crm","notes","documentation"],"difficulty":"beginner","description":"Write effective CRM notes for any interaction","prompt":"Write CRM notes for this interaction.\n\nInteraction details:\n- Type: [CALL / EMAIL / MEETING / DEMO]\n- Prospect: [NAME, TITLE]\n- Date: [WHEN]\n- Duration: [HOW LONG]\n- What happened: [RAW NOTES OR MEMORY]\n\nStructure notes as:\n1. SUMMARY (2-3 sentences)\n2. KEY POINTS\n   - What they said about pain\n   - What they said about timeline\n   - What they said about budget\n   - What they said about competition\n3. STAKEHOLDERS (mentioned or involved)\n4. OBJECTIONS (raised concerns)\n5. NEXT STEPS (specific with dates)\n6. FOLLOW-UP ITEMS (what you owe them)\n\nKeep it scannable. Future you (or your manager) needs to understand this deal in 30 seconds.","group":"universal"},{"id":"uni-pricing-presentation","title":"Pricing Conversation Framework","category":"universal","tags":["pricing","presentation","value"],"difficulty":"intermediate","description":"Present pricing effectively","prompt":"Prepare to present pricing for this deal.\n\nContext:\n- Prospect: [COMPANY]\n- Our price: [AMOUNT]\n- Their likely budget: [IF KNOWN]\n- Value we deliver: [KEY OUTCOMES]\n- Competition pricing: [IF KNOWN]\n- Decision timeline: [WHEN]\n\nCreate pricing presentation approach:\n1. Before revealing price:\n   - Value summary (what they get)\n   - ROI preview (what it's worth)\n   - Comparison to alternatives\n\n2. The reveal:\n   - How to frame the number\n   - Anchoring strategy\n   - Package/option presentation\n\n3. After revealing:\n   - Silence (let them respond)\n   - Handle initial reaction\n   - Objection responses ready\n\n4. Negotiation prep:\n   - What you can flex on\n   - What you can't\n   - Trade-offs to offer","group":"universal"},{"id":"uni-email-sequence-audit","title":"Email Sequence Audit","category":"universal","tags":["email","sequence","audit","optimization"],"difficulty":"intermediate","description":"Audit and improve an existing email sequence","prompt":"Audit my email sequence and suggest improvements.\n\nCurrent sequence:\n[PASTE YOUR SEQUENCE - SUBJECT LINES AND BODIES]\n\nSequence context:\n- Target persona: [WHO]\n- Goal: [BOOK MEETING / DEMO / ETC]\n- Current performance: [OPEN/REPLY RATES IF KNOWN]\n\nAudit each email for:\n1. Subject line (compelling? right length?)\n2. Opening line (personalized? relevant?)\n3. Value prop (clear? specific?)\n4. Length (too long? too short?)\n5. CTA (clear? low friction?)\n6. Tone (appropriate for persona?)\n\nAudit the sequence as a whole:\n- Pacing (timing between emails)\n- Angle variation (different approaches)\n- Escalation (appropriate progression)\n- Breakup (effective closing)\n\nProvide rewritten versions of weak emails.","group":"universal"},{"id":"uni-account-plan","title":"Strategic Account Plan","category":"universal","tags":["account-plan","strategy","enterprise"],"difficulty":"advanced","description":"Create a plan for a strategic account","prompt":"Create a strategic account plan.\n\nAccount details:\n- Company: [NAME]\n- Industry: [INDUSTRY]\n- Size: [REVENUE/EMPLOYEES]\n- Current relationship: [PROSPECT / CUSTOMER / VALUE]\n- Key contacts: [WHO YOU KNOW]\n- My product: [WHAT YOU SELL]\n\nBuild an account plan covering:\n1. ACCOUNT OVERVIEW\n   - Business summary\n   - Strategic initiatives\n   - Key challenges\n   - Decision makers\n\n2. OPPORTUNITY ANALYSIS\n   - Current state with us\n   - Whitespace opportunities\n   - Total addressable value\n   - Competition present\n\n3. RELATIONSHIP MAP\n   - Org chart\n   - Power dynamics\n   - Champion status\n   - Coverage gaps\n\n4. ACTION PLAN\n   - 30-day priorities\n   - 90-day goals\n   - Key meetings needed\n   - Resources required\n\n5. SUCCESS METRICS\n   - How we'll measure progress","group":"universal"},{"id":"uni-win-story","title":"Customer Win Story","category":"universal","tags":["win-story","case-study","documentation"],"difficulty":"beginner","description":"Document a customer win for future reference","prompt":"Document this customer win.\n\nWin details:\n- Customer: [COMPANY]\n- Deal size: [VALUE]\n- Sales cycle: [LENGTH]\n- Key stakeholders: [WHO]\n- Competition: [WHO ELSE]\n- Why they chose us: [REASONS]\n- Close date: [WHEN]\n\nDocument:\n1. DEAL SUMMARY\n   - What they bought\n   - Deal value and terms\n   - Timeline\n\n2. WIN FACTORS\n   - What we did well\n   - Why they chose us over alternatives\n   - Key moments that won it\n\n3. LESSONS LEARNED\n   - What would we repeat\n   - What would we do differently\n   - Surprises along the way\n\n4. REUSABLE ELEMENTS\n   - Talk tracks that worked\n   - Materials that resonated\n   - Proof points to cite\n\n5. REFERENCE POTENTIAL\n   - Can they be a reference?\n   - Quote for marketing?\n   - Case study candidate?","group":"universal"},{"id":"uni-sales-manager-update","title":"Pipeline Update for Manager","category":"universal","tags":["pipeline","manager","update","1:1"],"difficulty":"intermediate","description":"Prepare pipeline update for 1:1","prompt":"Prepare my pipeline update for manager 1:1.\n\nCurrent state:\n- Quota: $[AMOUNT]\n- Closed this month/quarter: $[CLOSED]\n- Pipeline: $[TOTAL]\n- Coverage ratio: [X]x\n\nTop deals to discuss:\n[LIST YOUR TOP 5 DEALS WITH STAGE AND VALUE]\n\nPrepare update covering:\n1. DEALS TO CLOSE\n   - Commit deals (high confidence)\n   - Upside deals (possible)\n   - At-risk deals (needs help)\n\n2. PIPELINE HEALTH\n   - New pipeline added\n   - Pipeline velocity\n   - Stage distribution\n   - Aging deals\n\n3. HELP NEEDED\n   - Specific asks\n   - Resources required\n   - Escalations needed\n\n4. FOCUS AREAS\n   - What I'm prioritizing\n   - Why those priorities\n   - Expected outcomes\n\nCome with answers, not just updates.","group":"universal"},{"id":"uni-prospect-research","title":"Pre-Call Prospect Research","category":"universal","tags":["research","preparation","prospecting"],"difficulty":"beginner","description":"Research a prospect before reaching out","prompt":"Research this prospect before I reach out.\n\nProspect:\n- Name: [NAME]\n- Title: [TITLE]\n- Company: [COMPANY]\n\nResearch and compile:\n1. COMPANY INFO\n   - What they do\n   - Company size\n   - Recent news\n   - Funding/financials\n   - Growth trajectory\n\n2. PERSONAL INFO\n   - Background\n   - Previous companies\n   - LinkedIn activity\n   - Recent posts/shares\n   - Mutual connections\n\n3. PAIN INDICATORS\n   - Job postings (what they're hiring for)\n   - Tech stack (what tools they use)\n   - Initiatives mentioned\n   - Challenges in their industry\n\n4. CONVERSATION STARTERS\n   - Personalization hooks\n   - Relevant triggers\n   - Common ground\n\n5. OUTREACH ANGLE\n   - Best channel to reach\n   - Best time to reach\n   - Opening line suggestion","group":"universal"},{"id":"uni-poc-planning","title":"POC/Pilot Planning","category":"universal","tags":["poc","pilot","trial","planning"],"difficulty":"advanced","description":"Plan a proof of concept or pilot","prompt":"Plan a POC/pilot for this prospect.\n\nContext:\n- Prospect: [COMPANY]\n- What they want to test: [SCOPE]\n- Their success criteria: [WHAT THEY SAID]\n- Timeline: [HOW LONG]\n- Who's involved: [STAKEHOLDERS]\n- What's at stake: [DEAL VALUE IF POC SUCCEEDS]\n\nPOC plan should include:\n1. OBJECTIVES\n   - Clear success criteria\n   - Metrics to measure\n   - Decision point\n\n2. SCOPE\n   - What's included\n   - What's excluded\n   - Users/volume\n\n3. TIMELINE\n   - Setup phase\n   - Active testing\n   - Evaluation\n   - Decision meeting\n\n4. RESOURCES\n   - Their commitments\n   - Our commitments\n   - Support model\n\n5. RISK MITIGATION\n   - What could go wrong\n   - How to prevent\n   - Exit criteria\n\n6. CONVERSION PLAN\n   - What happens if successful\n   - Next steps already agreed","group":"universal"},{"id":"uni-competitive-intel","title":"Competitive Intelligence Gathering","category":"universal","tags":["competitive","intelligence","research"],"difficulty":"intermediate","description":"Gather intel on competitor activity","prompt":"Help me gather competitive intelligence.\n\nCompetitor: [COMPETITOR NAME]\nMy product: [WHAT YOU SELL]\n\nResearch and organize:\n1. PRODUCT INTEL\n   - Features and capabilities\n   - Recent releases\n   - Roadmap (if public)\n   - Known limitations\n\n2. PRICING INTEL\n   - Pricing model\n   - Price points (if known)\n   - Discount behavior\n   - Contract terms\n\n3. SALES INTEL\n   - Sales process\n   - Common tactics\n   - Strengths to counter\n   - Weaknesses to exploit\n\n4. CUSTOMER INTEL\n   - Who they sell to\n   - Reference customers\n   - Win/loss patterns\n   - Customer complaints\n\n5. POSITIONING\n   - How they position vs. us\n   - Messaging themes\n   - Claims they make\n\nSources to check:\n- G2/Capterra reviews\n- LinkedIn posts\n- Job postings\n- Press releases\n- Customer testimonials","group":"universal"},{"id":"uni-multi-thread-strategy","title":"Multi-Threading Strategy","category":"universal","tags":["multi-threading","relationships","account"],"difficulty":"advanced","description":"Build relationships across the account","prompt":"Create a multi-threading strategy for this account.\n\nCurrent state:\n- Account: [COMPANY]\n- Current contact: [NAME, TITLE]\n- Contact status: [ENGAGED / STALLED / RESPONSIVE]\n- Other people identified: [WHO ELSE YOU KNOW ABOUT]\n- Deal stage: [WHERE YOU ARE]\n\nMulti-thread plan:\n1. STAKEHOLDER MAP\n   - Who else should we know\n   - Their role in the decision\n   - How to identify them\n\n2. ENTRY STRATEGY\n   - For each new contact\n   - How to get introduced\n   - Value prop for their role\n\n3. MESSAGING\n   - Different messages for different personas\n   - How to coordinate outreach\n   - When to reference other conversations\n\n4. RISK MITIGATION\n   - Don't step on champion's toes\n   - Coordinate internal messaging\n   - Avoid appearing desperate\n\n5. EXECUTION\n   - Sequence of outreach\n   - Timing between touches\n   - Escalation path if blocked","group":"universal"},{"id":"uni-objection-prevention","title":"Objection Prevention Strategy","category":"universal","tags":["objections","prevention","proactive"],"difficulty":"advanced","description":"Prevent objections before they arise","prompt":"Create an objection prevention strategy.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Common objections I hear: [LIST THEM]\n- Typical buyer: [PERSONA]\n- Sales stage: [WHERE OBJECTIONS ARISE]\n\nFor each common objection:\n1. PRICE TOO HIGH\n   - How to prevent: Build value before revealing\n   - Pre-emptive messaging\n   - When to address proactively\n\n2. NOT A PRIORITY\n   - How to prevent: Establish urgency early\n   - Questions to ask\n   - How to quantify cost of delay\n\n3. NEED TO THINK ABOUT IT\n   - How to prevent: Surface concerns early\n   - Trial close questions\n   - How to earn commitment\n\n4. HAPPY WITH CURRENT SOLUTION\n   - How to prevent: Find dissatisfaction early\n   - Questions that expose gaps\n   - How to plant seeds of doubt\n\nFor each prevention strategy:\n- When in the process to deploy\n- What to say\n- Questions to ask\n- Signs it's working","group":"universal"},{"id":"uni-sales-email-templates","title":"Essential Sales Email Templates","category":"universal","tags":["email","templates","essentials"],"difficulty":"beginner","description":"Core email templates every rep needs","prompt":"Create essential sales email templates.\n\nContext:\n- My product: [WHAT YOU SELL]\n- My target buyer: [PERSONA]\n- My value prop: [KEY BENEFIT]\n\nCreate templates for:\n1. First Touch (cold outreach)\n2. Follow-Up #1 (no response)\n3. Follow-Up #2 (still no response)\n4. Breakup Email (final attempt)\n5. Meeting Confirmation\n6. Meeting Reminder (day before)\n7. Post-Meeting Recap\n8. Proposal Delivery\n9. Proposal Follow-Up\n10. Contract Sent\n11. Thank You (after close)\n12. Referral Request\n\nFor each template:\n- Subject line\n- Body (under 100 words)\n- Variables to personalize [BRACKETS]\n- When to send\n- What makes it effective","group":"universal"},{"id":"uni-quota-planning","title":"Quota Achievement Planning","category":"universal","tags":["quota","planning","goals"],"difficulty":"intermediate","description":"Plan how to hit your number","prompt":"Help me plan to hit my quota.\n\nMy numbers:\n- Annual quota: $[AMOUNT]\n- Quota this quarter: $[AMOUNT]\n- Closed so far: $[CLOSED]\n- Current pipeline: $[PIPELINE]\n- Average deal size: $[ACV]\n- Win rate: [%]\n- Average sales cycle: [DAYS]\n\nCalculate and plan:\n1. THE MATH\n   - Gap to quota\n   - Pipeline needed (at my win rate)\n   - Deals needed to close\n   - New opportunities needed\n\n2. PIPELINE ANALYSIS\n   - What will close this quarter\n   - What's at risk\n   - What's missing\n\n3. ACTIVITY REQUIREMENTS\n   - Meetings needed\n   - Calls/emails needed\n   - To generate enough pipeline\n\n4. WEEKLY PLAN\n   - Activity targets\n   - Pipeline milestones\n   - Check-in points\n\n5. RISK FACTORS\n   - What could go wrong\n   - Contingency plans\n   - Help needed from manager","group":"universal"}];

const INDUSTRY_ALIAS = {"saas":"saas","fintech":"financial-services","financial-services":"financial-services","healthcare":"healthcare","manufacturing":"manufacturing","professional-services":"professional-services","ecommerce":"ecommerce","real-estate":"real-estate","realestate":"real-estate","education":"education","logistics":"logistics","energy":"energy","government":"government","telecom":"telecom","media":"media","hospitality":"hospitality","construction":"construction","insurance":"insurance"};
const ROLE_ALIAS = {"sdr":"sdr","ae":"ae","sales-manager":"sales-manager","salesmanager":"sales-manager","revops":"revops","csm":"csm","founder":"founder"};
const METH_ALIAS = {"meddpicc":"meddpicc","spin":"spin","challenger":"challenger","sandler":"sandler","value-selling":"value-selling","gap-selling":"gap-selling"};
const UNIVERSAL = [{"id":"uni-meeting-prep","title":"Meeting Preparation Checklist","category":"universal","tags":["preparation","meeting","research"],"difficulty":"beginner","description":"Prepare for any sales meeting","prompt":"Help me prepare for a sales meeting.\n\nMeeting details:\n- Prospect: [NAME, TITLE at COMPANY]\n- Meeting type: [INTRO / DISCOVERY / DEMO / NEGOTIATION]\n- Duration: [MINUTES]\n- Virtual or in-person: [FORMAT]\n- Other attendees: [WHO ELSE]\n- Previous interactions: [HISTORY]\n\nPrepare:\n1. Research briefing (company news, their role, mutual connections)\n2. Meeting objectives (what I want to accomplish)\n3. Key questions to ask (prioritized)\n4. Anticipated objections and responses\n5. Value props most relevant to them\n6. Success metrics for the meeting\n7. Clear next step to propose\n8. Backup plan if main approach doesn't work\n\nAlso: Calendar items to send, materials to prepare, tech to test."},{"id":"uni-email-reply-busy","title":"Reply to \"Too Busy\" Email","category":"universal","tags":["email","objection","follow-up"],"difficulty":"beginner","description":"Craft a response when prospect says they are too busy","prompt":"Write a reply to a prospect who said they're too busy.\n\nContext:\n- Their response: [EXACT TEXT OF THEIR REPLY]\n- What I originally asked for: [MY ASK]\n- My product: [WHAT I SELL]\n- Their likely priorities: [WHAT'S ON THEIR PLATE]\n\nResponse strategies:\n1. Acknowledge and offer smaller ask\n2. Propose specific future time\n3. Offer async option (video, doc, etc.)\n4. Connect my ask to reducing their busyness\n5. Give them an easy out with follow-up timing\n\nWrite 3 response options with different approaches.\nKeep each under 50 words."},{"id":"uni-recap-email","title":"Meeting Recap Email","category":"universal","tags":["email","recap","follow-up"],"difficulty":"beginner","description":"Summarize a meeting and confirm next steps","prompt":"Write a meeting recap email.\n\nMeeting details:\n- Attendees: [WHO WAS THERE]\n- Meeting type: [TYPE]\n- Key topics discussed: [MAIN POINTS]\n- Problems they mentioned: [PAIN POINTS]\n- Their questions: [QUESTIONS THEY ASKED]\n- Action items agreed: [WHAT'S NEXT]\n- Timeline discussed: [DATES]\n\nRecap email should:\n1. Thank them (brief)\n2. Summarize what we heard (shows we listened)\n3. List action items with owners\n4. Confirm next meeting/step\n5. Attach relevant resources\n6. Keep it scannable\n\nUnder 200 words. Send within 2 hours of meeting."},{"id":"uni-no-show-follow-up","title":"No-Show Follow-Up","category":"universal","tags":["no-show","follow-up","reschedule"],"difficulty":"beginner","description":"Follow up after a prospect misses a meeting","prompt":"Write a follow-up after a prospect no-showed.\n\nContext:\n- Prospect: [NAME, TITLE]\n- Meeting type: [WHAT IT WAS]\n- How they booked: [INBOUND / OUTBOUND / REFERRAL]\n- Attempts to reach: [NONE / CALLED / TEXTED]\n- First no-show or repeat: [FREQUENCY]\n\nWrite 3 versions:\n1. Benefit-of-doubt (same day, assumes conflict)\n2. Gentle check-in (next day)\n3. Last attempt (3 days later)\n\nEach version should:\n- Not guilt them\n- Make it easy to reschedule\n- Include your calendar link\n- Be under 50 words\n- Have a subject line\n\nNever be passive aggressive. Things happen."},{"id":"uni-objection-price","title":"Handle Price Objections","category":"universal","tags":["objection","pricing","negotiation"],"difficulty":"intermediate","description":"Respond to various price objections","prompt":"Help me respond to a price objection.\n\nContext:\n- What they said: [EXACT OBJECTION]\n- My price: [WHAT I QUOTED]\n- Their budget (if known): [THEIR NUMBER]\n- Value I provide: [KEY BENEFITS]\n- Flexibility I have: [WHAT I CAN ADJUST]\n- Competition: [WHAT ALTERNATIVES COST]\n\nGenerate responses for these price objection types:\n1. \"It's too expensive\" (general sticker shock)\n2. \"We only have $X budget\" (specific number)\n3. \"Competitor is cheaper\" (competitive pressure)\n4. \"Can't justify the ROI\" (value question)\n5. \"Need discount to close\" (negotiation tactic)\n\nFor each, provide:\n- Questions to ask first\n- Reframe language\n- When to hold firm\n- When to negotiate\n- Creative alternatives to discounting"},{"id":"uni-internal-champion-email","title":"Champion Enablement Email","category":"universal","tags":["champion","internal-selling","enablement"],"difficulty":"intermediate","description":"Arm your champion to sell internally","prompt":"Create content to help my champion sell internally.\n\nContext:\n- Champion: [NAME, TITLE]\n- Decision maker they need to convince: [WHO]\n- What they need to justify: [THE ASK]\n- Internal objections they'll face: [CONCERNS]\n- Our value prop: [KEY BENEFITS]\n- ROI case: [NUMBERS]\n\nCreate:\n1. One-pager they can share (bullet points)\n2. Email they can forward to their boss\n3. Talk track for their internal meeting\n4. Responses to likely internal pushback\n5. Quick ROI summary\n\nMake everything easy to copy-paste. Use their company's language."},{"id":"uni-referral-request","title":"Ask for Referral","category":"universal","tags":["referral","customer","growth"],"difficulty":"beginner","description":"Request referrals from happy customers","prompt":"Write a referral request message.\n\nContext:\n- Customer: [NAME at COMPANY]\n- Relationship length: [HOW LONG]\n- Value delivered: [RESULTS/OUTCOMES]\n- Target referral type: [WHO YOU WANT TO MEET]\n- How to ask: [EMAIL / CALL / IN QBR]\n\nWrite versions for:\n1. Direct ask (strong relationship)\n2. Soft ask (newer relationship)\n3. Specific person ask (you know who)\n4. Event-based (after success milestone)\n5. Quid pro quo (you're offering something)\n\nEach version should:\n- Lead with their success\n- Make the ask specific\n- Make it easy to say yes\n- Include language they can use for intro\n- Not be pushy"},{"id":"uni-competitor-mention","title":"Handle Competitor Mention","category":"universal","tags":["competitive","positioning","objection"],"difficulty":"intermediate","description":"Respond when prospect mentions competitor","prompt":"Help me respond when a prospect mentions a competitor.\n\nContext:\n- What they said: [EXACT QUOTE]\n- Competitor mentioned: [NAME]\n- Where we're strong vs. them: [ADVANTAGES]\n- Where they're strong vs. us: [THEIR ADVANTAGES]\n- Prospect's priorities: [WHAT THEY CARE ABOUT]\n\nCreate responses for these scenarios:\n1. \"We're also looking at X\" (evaluation)\n2. \"We currently use X\" (displacement)\n3. \"X is cheaper\" (price comparison)\n4. \"X has feature Y\" (feature gap)\n5. \"We heard X is better at Z\" (reputation)\n\nRules:\n- Never badmouth competitor\n- Ask questions first\n- Focus on fit, not features\n- Acknowledge where they're strong\n- Tie differentiators to their priorities"},{"id":"uni-linkedin-post-ideas","title":"LinkedIn Content Ideas for Sales","category":"universal","tags":["linkedin","content","social-selling"],"difficulty":"beginner","description":"Generate LinkedIn post ideas for social selling","prompt":"Generate LinkedIn post ideas for sales content.\n\nContext:\n- My industry: [INDUSTRY]\n- My target buyer: [PERSONA]\n- My expertise: [TOPICS I KNOW]\n- My goal: [BRAND / LEADS / ENGAGEMENT]\n\nGenerate 10 post ideas in these formats:\n1. Contrarian take (challenge conventional wisdom)\n2. Lesson learned (personal story)\n3. Quick tip (tactical advice)\n4. Myth busting (common misconception)\n5. Framework share (process I use)\n6. Question post (spark discussion)\n7. Observation (industry trend)\n8. Celebration (customer success, without naming)\n9. Behind the scenes (authentic look)\n10. Poll (engagement driver)\n\nFor each idea:\n- Hook (first line)\n- Key points (3-5 bullets)\n- CTA (if any)\n- Best time to post"},{"id":"uni-case-study-structure","title":"Case Study Builder","category":"universal","tags":["case-study","proof","content"],"difficulty":"intermediate","description":"Structure a customer success story","prompt":"Help me structure a customer case study.\n\nCustomer details:\n- Company: [NAME]\n- Industry: [INDUSTRY]\n- Size: [SIZE]\n- Their challenge: [PROBLEM THEY HAD]\n- Our solution: [WHAT WE PROVIDED]\n- Results: [OUTCOMES/METRICS]\n- Timeline: [HOW LONG TO RESULTS]\n\nCreate structure for:\n1. One-paragraph summary (for emails)\n2. One-pager (for sales)\n3. Full case study (for website)\n4. Quote for social proof\n5. Slide for presentations\n\nEach format should include:\n- The challenge (pain)\n- The solution (how we helped)\n- The results (outcomes)\n- A quotable quote\n\nIdentify gaps where I need more info from the customer."},{"id":"uni-cold-call-voicemail","title":"Voicemail That Gets Callbacks","category":"universal","tags":["cold-call","voicemail","phone"],"difficulty":"beginner","description":"Leave effective cold call voicemails","prompt":"Write cold call voicemail scripts.\n\nContext:\n- Target: [TITLE at COMPANY TYPE]\n- My company: [NAME]\n- My value prop: [ONE SENTENCE]\n- Why them specifically: [PERSONALIZATION ANGLE]\n- My callback number: [NUMBER]\n\nWrite voicemails for:\n1. First touch (they don't know me)\n2. Follow-up to email (they got my email)\n3. Trigger event (timely reason)\n4. Referral mention (someone suggested)\n5. Break-up voicemail (final attempt)\n\nEach voicemail must be:\n- Under 20 seconds when spoken\n- Have ONE clear point\n- Say name and number slowly\n- Give a reason to call back\n- End with number again"},{"id":"uni-deal-update-internal","title":"Internal Deal Update","category":"universal","tags":["internal","deal","update","leadership"],"difficulty":"intermediate","description":"Update leadership on deal status","prompt":"Write an internal deal update for leadership.\n\nDeal context:\n- Account: [COMPANY]\n- Deal size: [VALUE]\n- Stage: [CURRENT STAGE]\n- Close date: [TARGET]\n- Champion: [NAME, STRENGTH]\n- Competition: [WHO ELSE]\n- Blockers: [WHAT'S IN THE WAY]\n- Support needed: [WHAT I NEED FROM LEADERSHIP]\n\nStructure the update:\n1. One-line status (green/yellow/red + why)\n2. Progress since last update\n3. Key milestones hit\n4. Current blockers and plan\n5. Specific ask (if any)\n6. Next steps with dates\n\nKeep it scannable. Executives skim.\nFlag where you need help early."},{"id":"uni-demo-agenda","title":"Demo Agenda Template","category":"universal","tags":["demo","presentation","agenda"],"difficulty":"intermediate","description":"Structure an effective product demo","prompt":"Create a demo agenda based on discovery.\n\nDiscovery findings:\n- Main pain: [PRIMARY PROBLEM]\n- Secondary pain: [SECONDARY PROBLEM]\n- Current tools: [WHAT THEY USE TODAY]\n- Decision criteria: [HOW THEY'LL EVALUATE]\n- Attendees: [WHO'S IN THE DEMO]\n- Time: [MINUTES AVAILABLE]\n\nCreate an agenda that:\n1. Opens with their situation (show you listened)\n2. Maps agenda to their priorities\n3. Shows most relevant features only\n4. Includes a \"wow moment\"\n5. Leaves time for questions\n6. Ends with clear next step\n\nAlso provide:\n- Talking points for each section\n- Questions to ask during demo\n- How to handle \"can you show feature X?\"\n- Recovery if demo breaks"},{"id":"uni-qualification-questions","title":"Universal Qualification Questions","category":"universal","tags":["qualification","discovery","questions"],"difficulty":"intermediate","description":"Questions to qualify any opportunity","prompt":"Generate qualification questions for any sales conversation.\n\nContext:\n- My product: [WHAT YOU SELL]\n- My typical deal size: [ACV RANGE]\n- My sales cycle: [TYPICAL LENGTH]\n\nGenerate questions for:\nBANT:\n- Budget (without asking \"what's your budget?\")\n- Authority (who makes the decision?)\n- Need (what problem are they solving?)\n- Timeline (when do they need this?)\n\nMEDDPICC (for enterprise):\n- Metrics (how will they measure success?)\n- Economic Buyer (who controls budget?)\n- Decision Criteria (how will they evaluate?)\n- Decision Process (what are the steps?)\n- Paper Process (procurement/legal?)\n- Identify Pain (what's the compelling event?)\n- Champion (who's advocating internally?)\n- Competition (who else are they looking at?)\n\nFor each question:\n- Natural way to ask\n- Follow-up if answer is vague\n- Red flag answers"},{"id":"uni-trial-check-in","title":"Trial Check-In Messages","category":"universal","tags":["trial","check-in","adoption"],"difficulty":"beginner","description":"Check in with trial users to drive adoption","prompt":"Create trial check-in messages.\n\nContext:\n- Product: [WHAT YOU SELL]\n- Trial length: [DAYS]\n- Key activation event: [WHAT SHOWS THEY'RE ENGAGED]\n- Customer persona: [WHO'S USING IT]\n\nCreate check-ins for:\nDay 1: Welcome + quick start\nDay 3: First milestone check\nDay 7: Engagement check (are they using it?)\nDay 10: Value conversation\nDay [X-2]: Trial ending soon\nDay [X]: Final ask\n\nFor each check-in:\n- Subject line\n- Body (under 100 words)\n- Goal of the touchpoint\n- If low engagement, alternative message\n- CTA\n\nInclude both email and in-app message versions."},{"id":"uni-proposal-structure","title":"Proposal Document Structure","category":"universal","tags":["proposal","document","closing"],"difficulty":"advanced","description":"Structure a winning proposal document","prompt":"Structure a proposal document.\n\nDeal context:\n- Prospect: [COMPANY]\n- Deal size: [VALUE]\n- Decision timeline: [WHEN]\n- Key stakeholders: [WHO'S READING]\n- Main problems we solve: [TOP 3 PAINS]\n- Competition: [WHO ELSE]\n\nProposal structure:\n1. Executive Summary (1 page)\n2. Understanding Your Situation\n3. Proposed Solution\n4. Implementation Approach\n5. Investment & ROI\n6. About Us (brief)\n7. Next Steps\n\nFor each section provide:\n- What to include\n- What to avoid\n- Length guidance\n- Visuals to consider\n\nAlso include:\n- Email to send with proposal\n- How to present vs. just send\n- Follow-up cadence if no response"},{"id":"uni-territory-planning","title":"Territory Planning Prompt","category":"universal","tags":["territory","planning","strategy"],"difficulty":"advanced","description":"Plan coverage for your territory","prompt":"Help me plan my sales territory.\n\nTerritory details:\n- Geographic/vertical scope: [WHAT I OWN]\n- Account list: [NUMBER OF ACCOUNTS]\n- Quota: [TARGET]\n- My product: [WHAT I SELL]\n- Average deal size: [TYPICAL ACV]\n- Sales cycle: [LENGTH]\n\nCreate a territory plan that includes:\n1. Account tiering (A/B/C criteria)\n2. Time allocation by tier\n3. Weekly/monthly activity targets\n4. Pipeline math (what I need to hit quota)\n5. Account prioritization framework\n6. Coverage gaps to address\n7. Quick wins vs. long-term plays\n8. Metrics to track\n\nOutput:\n- Account tier definitions\n- Weekly activity template\n- Pipeline goals by month\n- Top 10 accounts to focus on and why"},{"id":"uni-renewal-outreach","title":"Renewal Outreach Sequence","category":"universal","tags":["renewal","retention","customer"],"difficulty":"intermediate","description":"Outreach for upcoming renewals","prompt":"Create a renewal outreach sequence.\n\nCustomer context:\n- Company: [NAME]\n- Current ARR: [VALUE]\n- Renewal date: [DATE]\n- Days until renewal: [DAYS]\n- Usage level: [HIGH / MEDIUM / LOW]\n- NPS/satisfaction: [IF KNOWN]\n- Expansion opportunity: [IF ANY]\n- Risk level: [LOW / MEDIUM / HIGH]\n\nCreate outreach for:\n- 90 days out: Health check\n- 60 days out: Renewal preview\n- 45 days out: Formal renewal conversation\n- 30 days out: Proposal/quote\n- 14 days out: Close push\n- 7 days out: Final ask\n\nFor each touchpoint:\n- Email template\n- Call script key points\n- What to achieve\n- If at-risk, alternative approach\n\nInclude executive sponsor escalation if needed."},{"id":"uni-objection-bank","title":"Common Objection Response Bank","category":"universal","tags":["objections","responses","handling"],"difficulty":"intermediate","description":"Responses to the most common sales objections","prompt":"Create responses for common sales objections.\n\nContext:\n- My product: [WHAT YOU SELL]\n- My typical buyer: [PERSONA]\n- My price point: [RANGE]\n\nGenerate responses for:\n1. \"We're happy with our current solution\"\n2. \"It's not a priority right now\"\n3. \"Send me some information\"\n4. \"I need to talk to my team/boss\"\n5. \"Let me think about it\"\n6. \"We tried something like this before and it didn't work\"\n7. \"We're too busy to implement anything new\"\n8. \"Call me back in [future date]\"\n9. \"We don't have budget allocated for this\"\n10. \"I'm not the decision maker\"\n\nFor each objection:\n- Empathetic acknowledgment\n- Probing question\n- Reframe response\n- Exit gracefully if real\n- Red flag that means stop"},{"id":"uni-email-subject-ab-test","title":"A/B Test Email Subject Lines","category":"universal","tags":["email","subject-line","ab-test"],"difficulty":"beginner","description":"Generate subject line variations for testing","prompt":"Generate A/B test subject line variations.\n\nContext:\n- Original subject: [CURRENT SUBJECT LINE]\n- Email purpose: [COLD / FOLLOW-UP / NURTURE / PROMO]\n- Target persona: [WHO'S RECEIVING]\n- Tone: [PROFESSIONAL / CASUAL / URGENT]\n\nGenerate 10 variations using different psychological triggers:\n1. Curiosity (opens a loop)\n2. Benefit (what they get)\n3. Pain point (what they avoid)\n4. Social proof (others doing it)\n5. Scarcity (limited availability)\n6. Specificity (exact numbers)\n7. Question (engages them)\n8. Personal (uses their name/company)\n9. News hook (timely/relevant)\n10. Direct ask (no games)\n\nFor each variation:\n- The subject line\n- Character count\n- Why it might work\n- Who it works best for"},{"id":"uni-intro-email-new-contact","title":"Introduction to New Contact","category":"universal","tags":["email","introduction","stakeholder"],"difficulty":"beginner","description":"Introduce yourself to a new stakeholder","prompt":"Write an introduction email to a new contact at an existing account.\n\nContext:\n- New contact: [NAME, TITLE]\n- How you learned about them: [REFERRAL / ORG CHART / LINKEDIN]\n- Your existing contact: [NAME, TITLE]\n- Your relationship: [PROSPECT / CUSTOMER / PARTNER]\n- Why you want to connect: [REASON]\n\nIntroduction approaches:\n1. Referral from existing contact\n2. Org chart discovery (direct)\n3. LinkedIn connection first then email\n4. Through shared meeting invite\n5. Value-first (share something useful)\n\nFor each approach:\n- Email template\n- Subject line\n- When to use it\n- How to handle if no response"},{"id":"uni-reactivation-email","title":"Lead Reactivation Campaign","category":"universal","tags":["reactivation","nurture","closed-lost"],"difficulty":"intermediate","description":"Re-engage old leads and closed-lost opps","prompt":"Create a reactivation campaign for old leads.\n\nContext:\n- Lead status: [COLD / CLOSED-LOST / NURTURE]\n- How long since contact: [MONTHS]\n- Original reason for no-deal: [WHY THEY DIDN'T BUY]\n- What's changed since then: [NEW FEATURES / PRICING / POSITIONING]\n- Total leads to reactivate: [NUMBER]\n\nCreate:\n1. Re-engagement email sequence (3 touches)\n2. Phone script for warm calls\n3. LinkedIn message approach\n4. Value-add content to share\n5. Segmentation criteria (who to prioritize)\n\nFor each touch:\n- Acknowledge the time gap\n- Reference previous conversation\n- Lead with new value\n- Make it easy to re-engage\n- Have a clear, low-commitment ask"},{"id":"uni-exec-intro-email","title":"Executive Introduction Email","category":"universal","tags":["executive","cold-email","c-level"],"difficulty":"advanced","description":"Cold email to C-level executives","prompt":"Write a cold email to a C-level executive.\n\nContext:\n- Executive: [NAME, TITLE at COMPANY]\n- Company size: [REVENUE/EMPLOYEES]\n- Signal/trigger: [WHY NOW]\n- Business outcome we drive: [TOP-LINE IMPACT]\n- Exec-level proof point: [SIMILAR EXEC/COMPANY RESULT]\n\nExecutive email rules:\n- Lead with business impact, not product\n- One specific insight they might not have\n- Shorter is better (under 75 words)\n- No fluff or empty compliments\n- Peer credibility matters\n- Ask for direction, not their time\n\nStructure:\n1. Pattern interrupt (first line matters)\n2. One insight or observation\n3. Credibility marker\n4. Soft CTA (who should I speak with?)\n\nWrite 3 versions with different hooks."},{"id":"uni-persona-research","title":"Buyer Persona Research","category":"universal","tags":["persona","research","icp"],"difficulty":"intermediate","description":"Research a buyer persona for better messaging","prompt":"Help me research and understand a buyer persona.\n\nPersona to research:\n- Title/Role: [TITLE]\n- Industry: [INDUSTRY]\n- Company size: [SEGMENT]\n\nI need to understand:\n1. What's in their job description?\n2. How are they measured (KPIs)?\n3. What do they worry about (3 AM problems)?\n4. What's their boss asking them for?\n5. What would make them a hero internally?\n6. What have they tried before that failed?\n7. Who influences their decisions?\n8. How do they prefer to buy?\n9. What content do they consume?\n10. What language do they use?\n\nAlso provide:\n- Day in the life\n- Goals vs. obstacles\n- Buying triggers\n- Objections I'll hear\n- Best way to reach them"},{"id":"uni-power-questions","title":"Power Questions for Sales","category":"universal","tags":["questions","discovery","power-questions"],"difficulty":"intermediate","description":"High-impact questions for any sales conversation","prompt":"Generate power questions for sales conversations.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Conversation type: [COLD CALL / DISCOVERY / DEMO / CLOSE]\n- Buyer persona: [WHO I'M TALKING TO]\n\nGenerate questions in these categories:\n\nOpening Power Questions:\n- To grab attention\n- To understand their world\n- To earn the right to continue\n\nPain Discovery Questions:\n- To find problems\n- To quantify impact\n- To create urgency\n\nProcess Questions:\n- To understand how they buy\n- To identify stakeholders\n- To map timeline\n\nCommitment Questions:\n- To test interest\n- To identify blockers\n- To advance the deal\n\nFor each question:\n- The exact question\n- When to use it\n- What you're really learning\n- Follow-up if they're vague"},{"id":"uni-value-proposition","title":"Value Proposition Builder","category":"universal","tags":["value-prop","messaging","positioning"],"difficulty":"intermediate","description":"Craft value propositions for different audiences","prompt":"Build value propositions for my product.\n\nContext:\n- My product: [WHAT YOU SELL]\n- What it does: [FUNCTIONALITY]\n- Who uses it: [END USERS]\n- Problems it solves: [TOP 3 PAIN POINTS]\n- Outcomes it delivers: [RESULTS]\n- Differentiators: [WHY US VS ALTERNATIVES]\n\nCreate value propositions for:\n1. One-liner (10 words max)\n2. Elevator pitch (30 seconds)\n3. Email opener (one sentence)\n4. Website headline\n5. Cold call opener\n6. Exec summary intro\n\nThen adapt for different personas:\n- Economic buyer (ROI focused)\n- Technical evaluator (capability focused)\n- End user (ease of use focused)\n- Champion (internal justification)\n\nTest each against: \"So what?\" and \"Why you?\""},{"id":"uni-social-proof-bank","title":"Social Proof Library","category":"universal","tags":["social-proof","testimonials","references"],"difficulty":"beginner","description":"Organize and use social proof effectively","prompt":"Help me build a social proof library.\n\nCurrent proof points:\n- Customer quotes: [LIST WHAT YOU HAVE]\n- Case studies: [LIST TITLES]\n- Metrics/results: [KEY NUMBERS]\n- Logos: [RECOGNIZABLE BRANDS]\n- Awards/recognition: [ACCOLADES]\n- Industry validation: [ANALYSTS, PRESS]\n\nHelp me organize this for different uses:\n\nEmail Proof Points:\n- One-liners to drop in\n- Specific results to cite\n\nCall Talk Tracks:\n- How to weave in naturally\n- \"Companies like X are using this to...\"\n\nProposal Proof:\n- Which proof for which objection\n- Industry-specific references\n\nPresentation Slides:\n- Logo slides\n- Quote slides\n- Results slides\n\nFor each situation, show me how to use what I have."},{"id":"uni-urgency-creation","title":"Urgency Creation Techniques","category":"universal","tags":["urgency","closing","motivation"],"difficulty":"advanced","description":"Create genuine urgency without being pushy","prompt":"Help me create urgency in this deal.\n\nContext:\n- Prospect: [COMPANY]\n- Deal stage: [STAGE]\n- Their stated timeline: [WHAT THEY SAID]\n- Actual buying signals: [WHAT YOU'VE SEEN]\n- What's causing delay: [BLOCKER]\n- Our leverage: [WHY THEY NEED US]\n\nGenerate ethical urgency angles:\n1. Cost of delay (what waiting costs them)\n2. Competitive risk (what others are doing)\n3. Implementation timeline (start now to hit goal)\n4. Resource availability (our capacity)\n5. Pricing (legitimate expiration)\n6. Business cycle (their fiscal year/quarter)\n7. External event (industry change, regulation)\n\nFor each angle:\n- How to position it\n- Language to use\n- When it's appropriate\n- When to NOT use it\n- How to avoid being sleazy"},{"id":"uni-negotiation-prep","title":"Negotiation Preparation Framework","category":"universal","tags":["negotiation","preparation","strategy"],"difficulty":"advanced","description":"Prepare for any negotiation conversation","prompt":"Prepare me for a negotiation.\n\nDeal context:\n- Prospect: [COMPANY]\n- Our ask: [PRICE/TERMS]\n- Their position: [WHAT THEY WANT]\n- History: [NEGOTIATION SO FAR]\n- Stakeholders: [WHO'S INVOLVED]\n- Competition: [ALTERNATIVES THEY HAVE]\n- Timeline pressure: [THEIR DEADLINE / OURS]\n\nPrepare:\n1. BATNA Analysis\n   - Our best alternative if this fails\n   - Their best alternative if this fails\n\n2. Zone of Possible Agreement\n   - Our walkaway point\n   - Their likely walkaway\n   - Target outcome\n\n3. Concession Strategy\n   - What we can give\n   - What we want in return\n   - Order of concessions\n\n4. Objection Responses\n   - Anticipated pushback\n   - How to respond\n\n5. Closing Approach\n   - How to ask for the close\n   - How to handle \"no\"\n   - How to leave door open"},{"id":"uni-weekly-planning","title":"Sales Week Planning","category":"universal","tags":["planning","productivity","time-management"],"difficulty":"beginner","description":"Plan your sales activities for the week","prompt":"Help me plan my sales week.\n\nCurrent state:\n- Open pipeline: [TOTAL VALUE]\n- Deals closing this month: [NUMBER AND VALUE]\n- Meetings booked this week: [NUMBER]\n- Prospecting target: [CALLS/EMAILS]\n- Admin tasks due: [WHAT'S NEEDED]\n\nHelp me plan:\n1. Priority deals to advance (top 3-5)\n2. Prospecting blocks (when and how much)\n3. Follow-up tasks (who needs what)\n4. Meeting preparation time\n5. Admin time (CRM, forecasting)\n\nWeekly cadence template:\n- Monday: Week planning + top deals\n- Tuesday-Thursday: Prospecting + meetings\n- Friday: Follow-up + forecast\n\nTime blocking suggestions:\n- Deep work windows\n- Call blocks\n- Email processing\n- CRM updates"},{"id":"uni-lost-deal-analysis","title":"Lost Deal Post-Mortem","category":"universal","tags":["lost-deal","analysis","learning"],"difficulty":"intermediate","description":"Analyze why a deal was lost","prompt":"Analyze this lost deal for learnings.\n\nDeal details:\n- Company: [PROSPECT]\n- Deal value: [AMOUNT]\n- Sales cycle length: [DAYS]\n- Stage reached: [HIGHEST STAGE]\n- Competition: [WHO ELSE]\n- Who won: [COMPETITOR / NO DECISION / INTERNAL]\n- Reason given: [WHAT THEY SAID]\n\nAnalyze:\n1. Where did we lose it? (which stage)\n2. Was it winnable? (qualification check)\n3. What did competition do better?\n4. What would we do differently?\n5. Red flags we missed?\n6. Good things we did?\n\nCategories of loss:\n- Timing (not ready to buy)\n- Budget (couldn't afford)\n- Competition (chose someone else)\n- No decision (did nothing)\n- Bad fit (should have disqualified)\n\nAction items:\n- What to improve for next time\n- How to stay in touch (maybe future opportunity)"},{"id":"uni-champion-checklist","title":"Champion Validation Checklist","category":"universal","tags":["champion","validation","qualification"],"difficulty":"advanced","description":"Validate if your champion is real","prompt":"Validate if my contact is a true champion.\n\nContact details:\n- Name and title: [WHO]\n- Time in role: [TENURE]\n- Relationship with EB: [CONNECTION]\n- What they've done for us: [ACTIONS]\n- What they've said: [COMMITMENTS]\n\nChampion criteria (must have all 3):\n1. POWER: Can influence the decision\n2. ACCESS: Can get you to decision makers\n3. WILL: Actively selling for you internally\n\nValidation tests:\n1. Will they give you info others won't?\n2. Will they coach you on internal dynamics?\n3. Will they introduce you to power?\n4. Will they tell you the truth about your position?\n5. Will they fight for you when you're not there?\n\nIf they fail:\n- How to build a real champion\n- Where else to look\n- Questions to find hidden champions"},{"id":"uni-competitive-landmine","title":"Competitive Landmines","category":"universal","tags":["competitive","differentiation","questions"],"difficulty":"advanced","description":"Plant questions that expose competitor weaknesses","prompt":"Create competitive landmines for my evaluation.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Main competitor: [WHO]\n- Where we're strong: [OUR ADVANTAGES]\n- Where they're weak: [THEIR GAPS]\n- Buyer's likely criteria: [WHAT THEY CARE ABOUT]\n\nCreate landmines (questions for buyer to ask competitor):\n1. Technical landmines (expose capability gaps)\n2. Process landmines (expose complexity)\n3. Support landmines (expose service gaps)\n4. Pricing landmines (expose hidden costs)\n5. Roadmap landmines (expose direction)\n\nFor each landmine:\n- The question to plant\n- Why it hurts competitor\n- Natural way to bring it up\n- What answer exposes the weakness\n\nRules:\n- Don't lie or exaggerate\n- Focus on real differences\n- Make questions reasonable\n- Be ready if they flip it on you"},{"id":"uni-deal-review-prep","title":"Deal Review Preparation","category":"universal","tags":["deal-review","coaching","preparation"],"difficulty":"intermediate","description":"Prepare for a deal review with your manager","prompt":"Prepare for a deal review with my manager.\n\nDeal details:\n- Account: [COMPANY]\n- Deal size: [VALUE]\n- Close date: [TARGET]\n- Current stage: [STAGE]\n- Days in stage: [NUMBER]\n\nPrepare to answer:\n1. SITUATION: What's the deal? (one paragraph)\n2. QUALIFICATION: Is this real? (MEDDPICC/BANT)\n3. COMPETITION: Are we winning?\n4. NEXT STEPS: What happens next?\n5. HELP NEEDED: What support do I need?\n\nAnticipate manager questions:\n- Why will they buy?\n- Why us vs. competition?\n- Is the close date realistic?\n- What could go wrong?\n- What are you doing to advance it?\n\nCome with specific asks, not vague \"I need help.\""},{"id":"uni-email-writing-polish","title":"Email Polish and Improvement","category":"universal","tags":["email","writing","improvement"],"difficulty":"beginner","description":"Improve an existing sales email","prompt":"Improve this sales email.\n\nCurrent email:\n[PASTE YOUR EMAIL HERE]\n\nContext:\n- Purpose: [WHAT YOU'RE TRYING TO ACHIEVE]\n- Recipient: [WHO]\n- Stage: [COLD / WARM / FOLLOW-UP]\n\nCheck and improve:\n1. Subject line (is it compelling?)\n2. Opening line (does it hook?)\n3. Length (too long?)\n4. Clarity (is the ask clear?)\n5. Value (what's in it for them?)\n6. CTA (is it specific?)\n7. Tone (right for the reader?)\n8. Personalization (is it generic?)\n9. Grammar/typos\n10. Mobile readability\n\nProvide:\n- Rewritten version\n- What I changed and why\n- Alternative subject lines\n- Shorter version if too long"},{"id":"uni-buying-committee-map","title":"Buying Committee Mapping","category":"universal","tags":["stakeholders","mapping","enterprise"],"difficulty":"advanced","description":"Map all stakeholders in a complex deal","prompt":"Map the buying committee for this deal.\n\nDeal context:\n- Company: [PROSPECT]\n- Deal size: [VALUE]\n- What we sell: [PRODUCT]\n- Known contacts: [WHO YOU KNOW]\n\nFor each stakeholder type, identify:\n1. Economic Buyer (budget authority)\n2. Technical Buyer (evaluates capabilities)\n3. User Buyer (will use daily)\n4. Champion (wants you to win)\n5. Coach (gives inside info)\n6. Blocker (might say no)\n7. Influencer (shapes opinion)\n8. Legal/Procurement (contract authority)\n\nFor each person found:\n- Name and title\n- Their agenda (what they care about)\n- How to win them\n- Risk they pose\n- Engagement strategy\n\nCreate a visual org chart with relationships."},{"id":"uni-discovery-debrief","title":"Discovery Call Debrief","category":"universal","tags":["discovery","debrief","notes"],"difficulty":"intermediate","description":"Debrief and extract insights from discovery","prompt":"Debrief my discovery call and extract key insights.\n\nCall details:\n- Prospect: [NAME, TITLE at COMPANY]\n- Call duration: [MINUTES]\n- Raw notes: [PASTE YOUR NOTES]\n\nExtract and organize:\n1. SITUATION (current state)\n   - How they do it today\n   - Tools/processes in place\n   - Team structure\n\n2. PAIN (problems)\n   - Problems mentioned\n   - Impact of problems\n   - Urgency level\n\n3. IMPACT (quantified)\n   - Time wasted\n   - Money lost\n   - Risk exposure\n\n4. DECISION (process)\n   - Who else involved\n   - Timeline\n   - Budget\n\n5. NEXT STEPS\n   - What was agreed\n   - Follow-up actions\n\nAlso flag: Red flags, positive signals, info gaps to fill."},{"id":"uni-sales-deck-outline","title":"Sales Presentation Outline","category":"universal","tags":["presentation","deck","pitch"],"difficulty":"intermediate","description":"Structure a compelling sales presentation","prompt":"Create a sales presentation outline.\n\nContext:\n- Audience: [WHO'S ATTENDING]\n- Meeting purpose: [INTRO / DEEP DIVE / EXEC]\n- Time available: [MINUTES]\n- What they know: [BACKGROUND]\n- My product: [WHAT YOU SELL]\n- Key message: [MAIN POINT]\n\nCreate outline for:\n1. Opening (grab attention)\n2. Agenda (set expectations)\n3. Their situation (show you understand)\n4. The problem (pain amplification)\n5. The solution (your approach)\n6. How it works (demo/walkthrough)\n7. Results/proof (social proof)\n8. Investment (pricing)\n9. Next steps (CTA)\n\nFor each section:\n- Key points to make\n- Time allocation\n- Visuals needed\n- Questions to ask audience\n- Transitions between sections"},{"id":"uni-crm-notes","title":"CRM Notes Template","category":"universal","tags":["crm","notes","documentation"],"difficulty":"beginner","description":"Write effective CRM notes for any interaction","prompt":"Write CRM notes for this interaction.\n\nInteraction details:\n- Type: [CALL / EMAIL / MEETING / DEMO]\n- Prospect: [NAME, TITLE]\n- Date: [WHEN]\n- Duration: [HOW LONG]\n- What happened: [RAW NOTES OR MEMORY]\n\nStructure notes as:\n1. SUMMARY (2-3 sentences)\n2. KEY POINTS\n   - What they said about pain\n   - What they said about timeline\n   - What they said about budget\n   - What they said about competition\n3. STAKEHOLDERS (mentioned or involved)\n4. OBJECTIONS (raised concerns)\n5. NEXT STEPS (specific with dates)\n6. FOLLOW-UP ITEMS (what you owe them)\n\nKeep it scannable. Future you (or your manager) needs to understand this deal in 30 seconds."},{"id":"uni-pricing-presentation","title":"Pricing Conversation Framework","category":"universal","tags":["pricing","presentation","value"],"difficulty":"intermediate","description":"Present pricing effectively","prompt":"Prepare to present pricing for this deal.\n\nContext:\n- Prospect: [COMPANY]\n- Our price: [AMOUNT]\n- Their likely budget: [IF KNOWN]\n- Value we deliver: [KEY OUTCOMES]\n- Competition pricing: [IF KNOWN]\n- Decision timeline: [WHEN]\n\nCreate pricing presentation approach:\n1. Before revealing price:\n   - Value summary (what they get)\n   - ROI preview (what it's worth)\n   - Comparison to alternatives\n\n2. The reveal:\n   - How to frame the number\n   - Anchoring strategy\n   - Package/option presentation\n\n3. After revealing:\n   - Silence (let them respond)\n   - Handle initial reaction\n   - Objection responses ready\n\n4. Negotiation prep:\n   - What you can flex on\n   - What you can't\n   - Trade-offs to offer"},{"id":"uni-email-sequence-audit","title":"Email Sequence Audit","category":"universal","tags":["email","sequence","audit","optimization"],"difficulty":"intermediate","description":"Audit and improve an existing email sequence","prompt":"Audit my email sequence and suggest improvements.\n\nCurrent sequence:\n[PASTE YOUR SEQUENCE - SUBJECT LINES AND BODIES]\n\nSequence context:\n- Target persona: [WHO]\n- Goal: [BOOK MEETING / DEMO / ETC]\n- Current performance: [OPEN/REPLY RATES IF KNOWN]\n\nAudit each email for:\n1. Subject line (compelling? right length?)\n2. Opening line (personalized? relevant?)\n3. Value prop (clear? specific?)\n4. Length (too long? too short?)\n5. CTA (clear? low friction?)\n6. Tone (appropriate for persona?)\n\nAudit the sequence as a whole:\n- Pacing (timing between emails)\n- Angle variation (different approaches)\n- Escalation (appropriate progression)\n- Breakup (effective closing)\n\nProvide rewritten versions of weak emails."},{"id":"uni-account-plan","title":"Strategic Account Plan","category":"universal","tags":["account-plan","strategy","enterprise"],"difficulty":"advanced","description":"Create a plan for a strategic account","prompt":"Create a strategic account plan.\n\nAccount details:\n- Company: [NAME]\n- Industry: [INDUSTRY]\n- Size: [REVENUE/EMPLOYEES]\n- Current relationship: [PROSPECT / CUSTOMER / VALUE]\n- Key contacts: [WHO YOU KNOW]\n- My product: [WHAT YOU SELL]\n\nBuild an account plan covering:\n1. ACCOUNT OVERVIEW\n   - Business summary\n   - Strategic initiatives\n   - Key challenges\n   - Decision makers\n\n2. OPPORTUNITY ANALYSIS\n   - Current state with us\n   - Whitespace opportunities\n   - Total addressable value\n   - Competition present\n\n3. RELATIONSHIP MAP\n   - Org chart\n   - Power dynamics\n   - Champion status\n   - Coverage gaps\n\n4. ACTION PLAN\n   - 30-day priorities\n   - 90-day goals\n   - Key meetings needed\n   - Resources required\n\n5. SUCCESS METRICS\n   - How we'll measure progress"},{"id":"uni-win-story","title":"Customer Win Story","category":"universal","tags":["win-story","case-study","documentation"],"difficulty":"beginner","description":"Document a customer win for future reference","prompt":"Document this customer win.\n\nWin details:\n- Customer: [COMPANY]\n- Deal size: [VALUE]\n- Sales cycle: [LENGTH]\n- Key stakeholders: [WHO]\n- Competition: [WHO ELSE]\n- Why they chose us: [REASONS]\n- Close date: [WHEN]\n\nDocument:\n1. DEAL SUMMARY\n   - What they bought\n   - Deal value and terms\n   - Timeline\n\n2. WIN FACTORS\n   - What we did well\n   - Why they chose us over alternatives\n   - Key moments that won it\n\n3. LESSONS LEARNED\n   - What would we repeat\n   - What would we do differently\n   - Surprises along the way\n\n4. REUSABLE ELEMENTS\n   - Talk tracks that worked\n   - Materials that resonated\n   - Proof points to cite\n\n5. REFERENCE POTENTIAL\n   - Can they be a reference?\n   - Quote for marketing?\n   - Case study candidate?"},{"id":"uni-sales-manager-update","title":"Pipeline Update for Manager","category":"universal","tags":["pipeline","manager","update","1:1"],"difficulty":"intermediate","description":"Prepare pipeline update for 1:1","prompt":"Prepare my pipeline update for manager 1:1.\n\nCurrent state:\n- Quota: $[AMOUNT]\n- Closed this month/quarter: $[CLOSED]\n- Pipeline: $[TOTAL]\n- Coverage ratio: [X]x\n\nTop deals to discuss:\n[LIST YOUR TOP 5 DEALS WITH STAGE AND VALUE]\n\nPrepare update covering:\n1. DEALS TO CLOSE\n   - Commit deals (high confidence)\n   - Upside deals (possible)\n   - At-risk deals (needs help)\n\n2. PIPELINE HEALTH\n   - New pipeline added\n   - Pipeline velocity\n   - Stage distribution\n   - Aging deals\n\n3. HELP NEEDED\n   - Specific asks\n   - Resources required\n   - Escalations needed\n\n4. FOCUS AREAS\n   - What I'm prioritizing\n   - Why those priorities\n   - Expected outcomes\n\nCome with answers, not just updates."},{"id":"uni-prospect-research","title":"Pre-Call Prospect Research","category":"universal","tags":["research","preparation","prospecting"],"difficulty":"beginner","description":"Research a prospect before reaching out","prompt":"Research this prospect before I reach out.\n\nProspect:\n- Name: [NAME]\n- Title: [TITLE]\n- Company: [COMPANY]\n\nResearch and compile:\n1. COMPANY INFO\n   - What they do\n   - Company size\n   - Recent news\n   - Funding/financials\n   - Growth trajectory\n\n2. PERSONAL INFO\n   - Background\n   - Previous companies\n   - LinkedIn activity\n   - Recent posts/shares\n   - Mutual connections\n\n3. PAIN INDICATORS\n   - Job postings (what they're hiring for)\n   - Tech stack (what tools they use)\n   - Initiatives mentioned\n   - Challenges in their industry\n\n4. CONVERSATION STARTERS\n   - Personalization hooks\n   - Relevant triggers\n   - Common ground\n\n5. OUTREACH ANGLE\n   - Best channel to reach\n   - Best time to reach\n   - Opening line suggestion"},{"id":"uni-poc-planning","title":"POC/Pilot Planning","category":"universal","tags":["poc","pilot","trial","planning"],"difficulty":"advanced","description":"Plan a proof of concept or pilot","prompt":"Plan a POC/pilot for this prospect.\n\nContext:\n- Prospect: [COMPANY]\n- What they want to test: [SCOPE]\n- Their success criteria: [WHAT THEY SAID]\n- Timeline: [HOW LONG]\n- Who's involved: [STAKEHOLDERS]\n- What's at stake: [DEAL VALUE IF POC SUCCEEDS]\n\nPOC plan should include:\n1. OBJECTIVES\n   - Clear success criteria\n   - Metrics to measure\n   - Decision point\n\n2. SCOPE\n   - What's included\n   - What's excluded\n   - Users/volume\n\n3. TIMELINE\n   - Setup phase\n   - Active testing\n   - Evaluation\n   - Decision meeting\n\n4. RESOURCES\n   - Their commitments\n   - Our commitments\n   - Support model\n\n5. RISK MITIGATION\n   - What could go wrong\n   - How to prevent\n   - Exit criteria\n\n6. CONVERSION PLAN\n   - What happens if successful\n   - Next steps already agreed"},{"id":"uni-competitive-intel","title":"Competitive Intelligence Gathering","category":"universal","tags":["competitive","intelligence","research"],"difficulty":"intermediate","description":"Gather intel on competitor activity","prompt":"Help me gather competitive intelligence.\n\nCompetitor: [COMPETITOR NAME]\nMy product: [WHAT YOU SELL]\n\nResearch and organize:\n1. PRODUCT INTEL\n   - Features and capabilities\n   - Recent releases\n   - Roadmap (if public)\n   - Known limitations\n\n2. PRICING INTEL\n   - Pricing model\n   - Price points (if known)\n   - Discount behavior\n   - Contract terms\n\n3. SALES INTEL\n   - Sales process\n   - Common tactics\n   - Strengths to counter\n   - Weaknesses to exploit\n\n4. CUSTOMER INTEL\n   - Who they sell to\n   - Reference customers\n   - Win/loss patterns\n   - Customer complaints\n\n5. POSITIONING\n   - How they position vs. us\n   - Messaging themes\n   - Claims they make\n\nSources to check:\n- G2/Capterra reviews\n- LinkedIn posts\n- Job postings\n- Press releases\n- Customer testimonials"},{"id":"uni-multi-thread-strategy","title":"Multi-Threading Strategy","category":"universal","tags":["multi-threading","relationships","account"],"difficulty":"advanced","description":"Build relationships across the account","prompt":"Create a multi-threading strategy for this account.\n\nCurrent state:\n- Account: [COMPANY]\n- Current contact: [NAME, TITLE]\n- Contact status: [ENGAGED / STALLED / RESPONSIVE]\n- Other people identified: [WHO ELSE YOU KNOW ABOUT]\n- Deal stage: [WHERE YOU ARE]\n\nMulti-thread plan:\n1. STAKEHOLDER MAP\n   - Who else should we know\n   - Their role in the decision\n   - How to identify them\n\n2. ENTRY STRATEGY\n   - For each new contact\n   - How to get introduced\n   - Value prop for their role\n\n3. MESSAGING\n   - Different messages for different personas\n   - How to coordinate outreach\n   - When to reference other conversations\n\n4. RISK MITIGATION\n   - Don't step on champion's toes\n   - Coordinate internal messaging\n   - Avoid appearing desperate\n\n5. EXECUTION\n   - Sequence of outreach\n   - Timing between touches\n   - Escalation path if blocked"},{"id":"uni-objection-prevention","title":"Objection Prevention Strategy","category":"universal","tags":["objections","prevention","proactive"],"difficulty":"advanced","description":"Prevent objections before they arise","prompt":"Create an objection prevention strategy.\n\nContext:\n- My product: [WHAT YOU SELL]\n- Common objections I hear: [LIST THEM]\n- Typical buyer: [PERSONA]\n- Sales stage: [WHERE OBJECTIONS ARISE]\n\nFor each common objection:\n1. PRICE TOO HIGH\n   - How to prevent: Build value before revealing\n   - Pre-emptive messaging\n   - When to address proactively\n\n2. NOT A PRIORITY\n   - How to prevent: Establish urgency early\n   - Questions to ask\n   - How to quantify cost of delay\n\n3. NEED TO THINK ABOUT IT\n   - How to prevent: Surface concerns early\n   - Trial close questions\n   - How to earn commitment\n\n4. HAPPY WITH CURRENT SOLUTION\n   - How to prevent: Find dissatisfaction early\n   - Questions that expose gaps\n   - How to plant seeds of doubt\n\nFor each prevention strategy:\n- When in the process to deploy\n- What to say\n- Questions to ask\n- Signs it's working"},{"id":"uni-sales-email-templates","title":"Essential Sales Email Templates","category":"universal","tags":["email","templates","essentials"],"difficulty":"beginner","description":"Core email templates every rep needs","prompt":"Create essential sales email templates.\n\nContext:\n- My product: [WHAT YOU SELL]\n- My target buyer: [PERSONA]\n- My value prop: [KEY BENEFIT]\n\nCreate templates for:\n1. First Touch (cold outreach)\n2. Follow-Up #1 (no response)\n3. Follow-Up #2 (still no response)\n4. Breakup Email (final attempt)\n5. Meeting Confirmation\n6. Meeting Reminder (day before)\n7. Post-Meeting Recap\n8. Proposal Delivery\n9. Proposal Follow-Up\n10. Contract Sent\n11. Thank You (after close)\n12. Referral Request\n\nFor each template:\n- Subject line\n- Body (under 100 words)\n- Variables to personalize [BRACKETS]\n- When to send\n- What makes it effective"},{"id":"uni-quota-planning","title":"Quota Achievement Planning","category":"universal","tags":["quota","planning","goals"],"difficulty":"intermediate","description":"Plan how to hit your number","prompt":"Help me plan to hit my quota.\n\nMy numbers:\n- Annual quota: $[AMOUNT]\n- Quota this quarter: $[AMOUNT]\n- Closed so far: $[CLOSED]\n- Current pipeline: $[PIPELINE]\n- Average deal size: $[ACV]\n- Win rate: [%]\n- Average sales cycle: [DAYS]\n\nCalculate and plan:\n1. THE MATH\n   - Gap to quota\n   - Pipeline needed (at my win rate)\n   - Deals needed to close\n   - New opportunities needed\n\n2. PIPELINE ANALYSIS\n   - What will close this quarter\n   - What's at risk\n   - What's missing\n\n3. ACTIVITY REQUIREMENTS\n   - Meetings needed\n   - Calls/emails needed\n   - To generate enough pipeline\n\n4. WEEKLY PLAN\n   - Activity targets\n   - Pipeline milestones\n   - Check-in points\n\n5. RISK FACTORS\n   - What could go wrong\n   - Contingency plans\n   - Help needed from manager"}];

const norm = (map, v) => (v && map[v]) || v;

export function getRelevantGtmSkills({ role, industry, methodology, limit = 6 } = {}) {
  const r = norm(ROLE_ALIAS, role);
  const i = norm(INDUSTRY_ALIAS, industry);
  const m = norm(METH_ALIAS, methodology);
  const scored = [];
  for (const p of PROMPTS) {
    let score = 0;
    const cats = [p.category, p.subcategory, ...(p.tags || []), p.group];
    if (r && (cats.includes(r))) score += 3;
    if (i && (cats.includes(i))) score += 2;
    if (m && (cats.includes(m))) score += 2;
    if (score > 0) scored.push({ score, p });
  }
  scored.sort((a, b) => b.score - a.score);
  const picked = scored.slice(0, limit).map((s) => s.p);
  if (picked.length < limit) {
    for (const u of UNIVERSAL) {
      if (picked.length >= limit) break;
      if (!picked.includes(u)) picked.push(u);
    }
  }
  return picked;
}

export function gtmSkillsPromptForContext({ role, industry, methodology, limit = 4 } = {}) {
  const picked = getRelevantGtmSkills({ role, industry, methodology, limit });
  if (!picked.length) return '';
  const lines = picked.map((p, idx) =>
    `EXAMPLE ${idx + 1} [${p.title || p.id}]
${p.prompt}`
  );
  return lines.join('\n\n---\n\n');
}

export const gtmSkillsFlat = PROMPTS;
export default { gtmSkillsCategories, getRelevantGtmSkills, gtmSkillsPromptForContext, gtmSkillsFlat };
